'@

$Embedded['Modules\Warband.lua'] = @'
-- Modules/Warband.lua
-- Completion Navigator :: which character should do this.
--
-- The per-character data already exists: reputations, titles, professions
-- and recipes are stored on the character that owns them. What was missing
-- is anything that reads across all of them and answers the question the
-- whole design was built around.
--
-- This module also feeds `characterSuitability`, the second scoring term
-- that was weighted in the formula but never set by anything. An objective
-- your current character is poorly suited to should rank below one they can
-- act on now, and the reason should say why.

local ADDON_NAME, CN = ...

local Warband = CN:RegisterModule("Warband")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- ROSTER
------------------------------------------------------------

function Warband.Roster()
    local rows = {}

    for key, character in CN.Characters() do
        table.insert(rows, {
            key      = key,
            name     = character.name,
            realm    = character.realm,
            class    = character.class,
            race     = character.race,
            level    = character.level,
            faction  = character.faction,
            spec     = character.specName,
            lastSeen = character.lastSeen,
            isCurrent = (key == CN.characterKey),

            professions  = CN.CountKeys(character.professions),
            recipes      = CN.CountKeys(character.recipes),
            titles       = CN.CountKeys(character.titles),
            reputations  = CN.CountKeys(character.reputations),
        })
    end

    table.sort(rows, function(a, b)
        if (a.level or 0) ~= (b.level or 0) then
            return (a.level or 0) > (b.level or 0)
        end

        return (a.key or "") < (b.key or "")
    end)

    return rows
end

------------------------------------------------------------
-- WHO SHOULD DO THIS
------------------------------------------------------------

-- Answers for any objective type that has per-character state. Returns
-- bestKey, detail, scope -- where scope explains why the answer is what it
-- is, including "account-wide" meaning the question does not apply.
function Warband.WhoShould(objectiveType, id)
    local types = CN.objectiveTypes

    if objectiveType == types.REPUTATION then
        local module = CN:GetModule("Reputations")

        if not module then
            return nil, nil, "no reputation data"
        end

        local bestKey, bestRecord, accountWide = module.BestCharacterFor(id)

        if accountWide then
            return nil, nil, "account-wide"
        end

        if bestKey then
            return bestKey, tostring(bestRecord and bestRecord.standing), "highest standing"
        end

        return nil, nil, "no character has this faction recorded"
    end

    if objectiveType == types.RECIPE then
        local module = CN:GetModule("Professions")

        if not module then
            return nil, nil, "no profession data"
        end

        local holders = module.WhoKnows(id)

        if #holders > 0 then
            return holders[1], table.concat(holders, ", "), "already knows it"
        end

        return nil, nil, "no character knows this recipe"
    end

    if objectiveType == types.TITLE then
        local module = CN:GetModule("Titles")

        if not module then
            return nil, nil, "no title data"
        end

        local holders = module.WhoHas(id)

        if #holders > 0 then
            return holders[1], table.concat(holders, ", "), "already earned it"
        end

        return nil, nil, "no character has this title"
    end

    if objectiveType == types.PROFESSION then
        local module = CN:GetModule("Professions")

        if not module then
            return nil, nil, "no profession data"
        end

        local bestKey, bestRecord = module.BestCharacterFor(id)

        if bestKey then
            return bestKey,
                   tostring(bestRecord and bestRecord.rank) .. " skill",
                   "highest skill"
        end

        return nil, nil, "no character has this profession"
    end

    if objectiveType == types.PET or objectiveType == types.MOUNT
        or objectiveType == types.TOY or objectiveType == types.ACHIEVEMENT
        or objectiveType == types.APPEARANCE then
        return nil, nil, "account-wide"
    end

    return nil, nil, "not tracked per character"
end

------------------------------------------------------------
-- SUITABILITY
------------------------------------------------------------

-- Positive when the logged-in character is the right one, negative when
-- somebody else is. Fed into the scoring formula so recommendations stop
-- pointing at work this character cannot usefully do.
function Warband.Suitability(objectiveType, id)
    local bestKey, detail, scope = Warband.WhoShould(objectiveType, id)

    if scope == "account-wide" or not bestKey then
        return 0, nil
    end

    if bestKey == CN.characterKey then
        return 1, "you are the best character for this"
    end

    return -2, bestKey .. " is better suited (" .. tostring(detail) .. ")"
end

-- Applied to every candidate before scoring, so no module has to remember
-- to do it.
function Warband.Decorate(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return objective
    end

    if objective.accountWide then
        return objective
    end

    local suitability, reason = Warband.Suitability(objective.type, objective.id)

    if suitability ~= 0 then
        objective.characterSuitability = suitability

        if reason then
            objective.reasons = objective.reasons or {}
            table.insert(objective.reasons, reason)
        end
    end

    return objective
end

CN.RegisterCandidateDecorator("Warband", Warband.Decorate)

------------------------------------------------------------
-- COVERAGE
------------------------------------------------------------

-- What the Warband collectively has, versus what any one character has.
-- This is the number that matters for account completion; a single
-- character's totals understate it.
function Warband.Coverage()
    local professions, recipes, titles = {}, {}, {}

    local characters = 0

    for _, character in CN.Characters() do
        characters = characters + 1

        for skillLineID in pairs(character.professions or {}) do
            professions[skillLineID] = true
        end

        for recipeID in pairs(character.recipes or {}) do
            recipes[recipeID] = true
        end

        for titleID in pairs(character.titles or {}) do
            titles[titleID] = true
        end
    end

    return {
        characters  = characters,
        professions = CN.CountKeys(professions),
        recipes     = CN.CountKeys(recipes),
        titles      = CN.CountKeys(titles),
    }
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "warband",
    aliases = { "roster" },
    order   = 17,
    help    = "Show every known character and what they cover.",
    handler = function()
        local rows = Warband.Roster()

        if #rows == 0 then
            Print("No characters recorded yet.")
            return
        end

        Print("Warband (" .. #rows .. " character"
            .. (#rows == 1 and "" or "s") .. "):")

        for _, row in ipairs(rows) do
            local marker = row.isCurrent and "|cff00ff00>|r " or "  "

            Print(marker .. row.key
                .. " |cff999999" .. tostring(row.level) .. " "
                .. tostring(row.class or "?")
                .. (row.faction and (" " .. row.faction) or "") .. "|r")

            Print("      professions " .. row.professions
                .. ", recipes " .. row.recipes
                .. ", titles " .. row.titles
                .. ", reputations " .. row.reputations)
        end

        local coverage = Warband.Coverage()

        Print("Combined coverage: " .. coverage.professions .. " professions, "
            .. coverage.recipes .. " recipes, " .. coverage.titles .. " titles.")

        if #rows == 1 then
            Print("|cffffff00Only one character has been seen. Log in on your alts "
                .. "with the addon loaded to make these comparisons useful.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "who",
    args    = "<type> <id>",
    order   = 18,
    help    = "Which character should do something. Types: rep, recipe, title, profession.",
    handler = function(args)
        local kind, value = args:match("^(%S+)%s+(.+)$")

        if not kind or not value then
            Print("Usage: /cn who <rep, recipe, title or profession> <id or name>")
            return
        end

        kind = string.lower(kind)

        local types = CN.objectiveTypes

        local map = {
            rep        = types.REPUTATION,
            reputation = types.REPUTATION,
            recipe     = types.RECIPE,
            title      = types.TITLE,
            profession = types.PROFESSION,
            prof       = types.PROFESSION,
        }

        local objectiveType = map[kind]

        if not objectiveType then
            Print("Unknown type: " .. kind)
            Print("Use one of: rep, recipe, title, profession")
            return
        end

        -- Resolve names to IDs through the owning module where possible.
        local id = CN.ToID(value)

        if not id then
            if objectiveType == types.REPUTATION then
                local module = CN:GetModule("Reputations")
                id = module and module.Resolve(value)
            elseif objectiveType == types.TITLE then
                local module = CN:GetModule("Titles")
                id = module and module.Resolve(value)
            end
        end

        if not id then
            Print("Could not resolve: " .. value)
            return
        end

        local bestKey, detail, scope = Warband.WhoShould(objectiveType, id)

        if scope == "account-wide" then
            Print("That is account-wide; any character counts.")
            return
        end

        if not bestKey then
            Print(tostring(scope) .. ".")
            return
        end

        if bestKey == CN.characterKey then
            Print("This character is the best one for it (" .. tostring(detail) .. ").")
        else
            Print("Best character: " .. bestKey .. " |cff999999(" .. tostring(detail) .. ")|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Rares.lua'] = @'
-- Modules/Rares.lua
-- Completion Navigator :: rares and treasures.
--
-- Most rare-tracking addons ship a static database of where rares spawn.
-- That answers "where is it", which is only half the question, and it goes
-- stale every patch.
--
-- This module leads with the client's vignette data instead, because a
-- vignette is the one live signal that a rare is *up right now*. Something
-- that exists this minute and may be dead in five is exactly the kind of
-- objective the opportunity scoring was built for.
--
-- Everything seen is also recorded permanently, so the addon accumulates its
-- own spawn database from play -- same approach as quest harvesting, and it
-- never goes stale because it comes from the live game.

local ADDON_NAME, CN = ...

local Rares = CN:RegisterModule("Rares")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

-- Everything ever seen, keyed by vignetteID. Account-wide: where a rare
-- spawns is a fact about the world.
local function Store()
    return CN.Account("rares")
end

-- Which vignettes this character has already dealt with. Rares are usually
-- once-per-character, so this is character state, not account state.
local function CharacterKills(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.raresKilled = character.raresKilled or {}

    return character.raresKilled
end

Rares.Store          = Store
Rares.CharacterKills = CharacterKills

------------------------------------------------------------
-- LIVE STATE
------------------------------------------------------------

-- Vignettes currently visible, classified and located.
function Rares.GetActive(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    local active = {}

    for _, vignette in ipairs(Blizzard.GetVignettes(mapID)) do
        local kind = Blizzard.ClassifyVignette(vignette.atlas)

        if not vignette.isDead then
            table.insert(active, {
                guid       = vignette.guid,
                vignetteID = vignette.vignetteID,
                name       = vignette.name,
                kind       = kind,
                mapID      = vignette.mapID,
                x          = vignette.x,
                y          = vignette.y,
                inFogOfWar = vignette.inFogOfWar,
            })
        end
    end

    table.sort(active, function(a, b)
        if a.kind ~= b.kind then
            return a.kind < b.kind
        end

        return (a.name or "") < (b.name or "")
    end)

    return active
end

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

function Rares.Record(vignette)
    if not vignette or not vignette.vignetteID then
        return false
    end

    local store    = Store()
    local existing = store[vignette.vignetteID]

    local record = existing or {
        vignetteID = vignette.vignetteID,
        firstSeen  = time(),
        sightings  = 0,
    }

    record.name      = vignette.name or record.name
    record.kind      = vignette.kind or record.kind
    record.lastSeen  = time()
    record.sightings = (record.sightings or 0) + 1

    -- Keep the first coordinates seen; rares roam, and the spawn point is
    -- more useful than wherever it happened to be standing.
    if vignette.mapID and vignette.x and vignette.y then
        if not record.mapID then
            record.mapID = vignette.mapID
            record.x     = math.floor(vignette.x * 10000 + 0.5) / 10000
            record.y     = math.floor(vignette.y * 10000 + 0.5) / 10000
            record.zone  = Blizzard.GetMapName(vignette.mapID)
        end
    end

    store[vignette.vignetteID] = record

    return existing == nil
end

function Rares.Sweep()
    local mapID = select(1, CN.GetPlayerPosition())

    local seen, new = 0, 0

    for _, vignette in ipairs(Rares.GetActive(mapID)) do
        if Rares.Record(vignette) then
            new = new + 1
        end

        seen = seen + 1
    end

    return seen, new
end

------------------------------------------------------------
-- KILL TRACKING
------------------------------------------------------------

-- A vignette that was present and is now gone, while the player was nearby,
-- is very likely dealt with. This is inference, so it is recorded as
-- "cleared by this character" rather than presented as fact.
local lastSeenGuids = {}

function Rares.NoteDisappearances(currentGuids)
    local kills = CharacterKills()

    if not kills then
        return
    end

    for guid, entry in pairs(lastSeenGuids) do
        if not currentGuids[guid] and entry.vignetteID then
            kills[entry.vignetteID] = time()

            DebugPrint("Vignette gone, marking cleared: " .. tostring(entry.name))
        end
    end
end

function Rares.IsClearedByCharacter(vignetteID)
    local kills = CharacterKills()

    return kills and kills[vignetteID] ~= nil
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Rares.Summary()
    local counts = {
        known     = 0,
        rares     = 0,
        treasures = 0,
        located   = 0,
        cleared   = 0,
    }

    local kills = CharacterKills() or {}

    for vignetteID, record in pairs(Store()) do
        counts.known = counts.known + 1

        if record.kind == "TREASURE" then
            counts.treasures = counts.treasures + 1
        else
            counts.rares = counts.rares + 1
        end

        if record.x and record.y then
            counts.located = counts.located + 1
        end

        if kills[vignetteID] then
            counts.cleared = counts.cleared + 1
        end
    end

    return counts
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.RARE, function(vignetteID)
    local states = CN.objectiveStates
    local record = Store()[vignetteID]

    if not record then
        return states.UNKNOWN, "Never seen this rare", nil
    end

    if Rares.IsClearedByCharacter(vignetteID) then
        return states.COMPLETED, "Cleared by this character", record.name
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only what is actually up right now becomes a candidate. A rare that is
-- not spawned is not a next action, and the whole point of using vignettes
-- is knowing the difference.
CN.RegisterCandidateProvider("Rares", function()
    local candidates = {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    for _, vignette in ipairs(Rares.GetActive(playerMap)) do
        local objectiveType = vignette.kind == "TREASURE"
            and CN.objectiveTypes.TREASURE
            or CN.objectiveTypes.RARE

        local id = vignette.vignetteID

        if id
            and not Rares.IsClearedByCharacter(id)
            and not CN.IsIgnored(objectiveType, id)
            and not CN.IsDeferred(objectiveType, id) then

            local reasons = {}
            local travel  = 0

            table.insert(reasons, vignette.kind == "TREASURE"
                and "treasure is up right now"
                or "rare is up right now")

            if vignette.x and vignette.y and playerX and playerY then
                local dx = vignette.x - playerX
                local dy = vignette.y - playerY

                travel = math.sqrt((dx * dx) + (dy * dy)) * 10

                table.insert(reasons, "in your current zone")
            end

            table.insert(candidates, CN.NewObjective({
                id               = id,
                type             = objectiveType,
                name             = vignette.name,
                mapID            = vignette.mapID,
                x                = vignette.x,
                y                = vignette.y,
                accountWide      = false,
                state            = CN.objectiveStates.AVAILABLE,
                completionValue  = 2,

                -- Up now, gone when someone else kills it. That is exactly
                -- what the limited-time term is for.
                limitedTimeBonus = 1.5,

                travelCost       = travel,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, { events = { "VIGNETTE_MINIMAP_UPDATED", "VIGNETTES_UPDATED", "ZONE_CHANGED_NEW_AREA" }, volatile = true })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

local function OnVignetteUpdate()
    local mapID = select(1, CN.GetPlayerPosition())

    local currentGuids = {}

    for _, vignette in ipairs(Rares.GetActive(mapID)) do
        currentGuids[vignette.guid] = true

        Rares.Record(vignette)
    end

    Rares.NoteDisappearances(currentGuids)

    -- Rebuild the seen set for the next comparison.
    local nextSeen = {}

    for _, vignette in ipairs(Rares.GetActive(mapID)) do
        nextSeen[vignette.guid] = {
            vignetteID = vignette.vignetteID,
            name       = vignette.name,
        }
    end

    lastSeenGuids = nextSeen
end

CN:RegisterEvent("VIGNETTE_MINIMAP_UPDATED", OnVignetteUpdate)
CN:RegisterEvent("VIGNETTES_UPDATED", OnVignetteUpdate)

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    -- Vignettes from the previous zone are meaningless now.
    lastSeenGuids = {}
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "rares",
    order   = 74,
    help    = "Show rares and treasures up right now.",
    handler = function()
        local active = Rares.GetActive()

        if #active == 0 then
            Print("Nothing is up nearby.")
            Print("|cff999999Vignettes only appear for content in range; "
                .. "move around the zone.|r")
            return
        end

        Print("Up right now (" .. #active .. "):")

        for index, vignette in ipairs(active) do
            local cleared = vignette.vignetteID
                and Rares.IsClearedByCharacter(vignette.vignetteID)

            Print("  " .. index .. ". " .. tostring(vignette.name)
                .. " |cff999999[" .. tostring(vignette.kind) .. "]|r"
                .. (cleared and " |cff999999(already cleared)|r" or "")
                .. (vignette.x and string.format(" |cff999999%.1f, %.1f|r",
                    vignette.x * 100, vignette.y * 100) or ""))
        end

        Print("|cffffff00/cn rare <number>|r to set a waypoint.")
    end,
}

CN:RegisterCommand{
    name    = "rare",
    args    = "<number>",
    order   = 75,
    help    = "Navigate to something that is up right now.",
    handler = function(args)
        local index = CN.ToID(args)

        if not index then
            Print("Usage: /cn rare <number from /cn rares>")
            return
        end

        local active = Rares.GetActive()
        local vignette = active[index]

        if not vignette then
            Print("There is no number " .. index .. " in the current list.")
            return
        end

        CN.NavigateToObjective({
            id    = vignette.vignetteID,
            type  = vignette.kind == "TREASURE"
                and CN.objectiveTypes.TREASURE
                or CN.objectiveTypes.RARE,
            name  = vignette.name,
            mapID = vignette.mapID,
            x     = vignette.x,
            y     = vignette.y,
        })
    end,
}

CN:RegisterCommand{
    name    = "raredb",
    order   = 76,
    help    = "Summarize every rare and treasure recorded from play.",
    handler = function()
        local counts = Rares.Summary()

        if counts.known == 0 then
            Print("Nothing recorded yet. Rares and treasures are captured "
                .. "automatically as you encounter them.")
            return
        end

        Print("Recorded: " .. counts.known
            .. " (" .. counts.rares .. " rares, " .. counts.treasures .. " treasures)")
        Print("With coordinates: " .. counts.located)
        Print("Cleared by this character: " .. counts.cleared)
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Currencies.lua'] = @'
-- Modules/Currencies.lua
-- Completion Navigator :: currencies, caps, and wasted earning potential.
--
-- A currency total on its own is not a decision. What matters is whether you
-- are at a cap, because a capped currency is earning potential you are
-- throwing away, and a weekly cap you have not filled resets in a few days
-- whether you use it or not.
--
-- Both of those are time-sensitive, which is why this module contributes to
-- the opportunity side of the scoring rather than sitting in a list.

local ADDON_NAME, CN = ...

local Currencies = CN:RegisterModule("Currencies")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

-- Currency quantities are character state; which currencies exist is not.
local function NameStore()
    return CN.Account("currencyNames")
end

local function CharacterStore(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.currencies = character.currencies or {}

    return character.currencies
end

Currencies.NameStore      = NameStore
Currencies.CharacterStore = CharacterStore

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Currencies.Scan()
    local names = NameStore()
    local mine  = CharacterStore()

    if not mine then
        return 0, 0, 0
    end

    local seen, atCap, weeklyRemaining = 0, 0, 0

    for _, currency in ipairs(Blizzard.GetCurrencyList()) do
        if currency.currencyID then
            names[currency.currencyID] = currency.name

            local capped = currency.maxQuantity > 0
                and currency.quantity >= currency.maxQuantity

            local weeklyLeft = 0

            if currency.maxWeeklyQuantity > 0 then
                weeklyLeft = math.max(0,
                    currency.maxWeeklyQuantity - currency.earnedThisWeek)
            end

            mine[currency.currencyID] = {
                currencyID        = currency.currencyID,
                quantity          = currency.quantity,
                maxQuantity       = currency.maxQuantity,
                totalEarned       = currency.totalEarned,
                earnedThisWeek    = currency.earnedThisWeek,
                maxWeeklyQuantity = currency.maxWeeklyQuantity,
                capped            = capped,
                weeklyRemaining   = weeklyLeft,
                lastSeen          = time(),
            }

            seen = seen + 1

            if capped then
                atCap = atCap + 1
            end

            if weeklyLeft > 0 then
                weeklyRemaining = weeklyRemaining + 1
            end
        end
    end

    CN.MarkScanned("currencies")

    return seen, atCap, weeklyRemaining
end

------------------------------------------------------------
-- QUERIES
------------------------------------------------------------

function Currencies.Capped(character)
    local capped = {}

    for currencyID, record in pairs(CharacterStore(character) or {}) do
        if record.capped then
            table.insert(capped, {
                currencyID = currencyID,
                name       = NameStore()[currencyID],
                quantity   = record.quantity,
                maximum    = record.maxQuantity,
            })
        end
    end

    table.sort(capped, function(a, b) return (a.name or "") < (b.name or "") end)

    return capped
end

function Currencies.WeeklyUnfilled(character)
    local rows = {}

    for currencyID, record in pairs(CharacterStore(character) or {}) do
        if record.weeklyRemaining and record.weeklyRemaining > 0 then
            table.insert(rows, {
                currencyID = currencyID,
                name       = NameStore()[currencyID],
                remaining  = record.weeklyRemaining,
                earned     = record.earnedThisWeek,
                maximum    = record.maxWeeklyQuantity,
            })
        end
    end

    table.sort(rows, function(a, b) return (a.remaining or 0) > (b.remaining or 0) end)

    return rows
end

function Currencies.Summary(character)
    local store = CharacterStore(character) or {}

    return {
        known           = CN.CountKeys(store),
        capped          = #Currencies.Capped(character),
        weeklyUnfilled  = #Currencies.WeeklyUnfilled(character),
    }
end

function Currencies.Resolve(text)
    local currencyID = CN.ToID(text)

    if currencyID and NameStore()[currencyID] then
        return currencyID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for id, name in pairs(NameStore()) do
        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = id, name = name })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A capped currency is not a place to travel to, so these carry no
-- coordinates. They surface as high-priority advisories: stop earning this
-- and go spend it.
CN.RegisterCandidateProvider("Currencies", function()
    local candidates = {}

    for _, currency in ipairs(Currencies.Capped()) do
        if not CN.IsIgnored(CN.objectiveTypes.CURRENCY, currency.currencyID)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, currency.currencyID) then

            table.insert(candidates, CN.NewObjective({
                id               = currency.currencyID,
                type             = CN.objectiveTypes.CURRENCY,
                name             = "Spend " .. tostring(currency.name),
                accountWide      = false,
                completionValue  = 2,
                limitedTimeBonus = 1,
                travelCost       = 0,

                -- A capped currency is not "expiring", but every hour spent
                -- at cap is earning thrown away, and the weekly reset is when
                -- that waste is realised. Treating the reset as its deadline
                -- makes the urgency curve say the true thing: this matters
                -- more on Monday night than on Wednesday morning.
                expiresIn        = CN.Blizzard.GetSecondsUntilWeeklyReset(),

                reasons          = {
                    "at cap: " .. tostring(currency.quantity)
                        .. " / " .. tostring(currency.maximum),
                    "further earning is wasted until you spend it",
                },
            }))
        end
    end

    return candidates
end, { events = { "CURRENCY_DISPLAY_UPDATE" }, volatile = true })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

local lastScan = 0

CN:RegisterEvent("CURRENCY_DISPLAY_UPDATE", function()
    local now = time()

    if now - lastScan < 10 then
        return
    end

    lastScan = now

    Currencies.Scan()
end)

CN:OnLogin(function()
    Currencies.Scan()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "currencies",
    aliases = { "currency" },
    order   = 77,
    help    = "Show currency caps and unfilled weekly earning.",
    handler = function()
        local counts = Currencies.Summary()

        if counts.known == 0 then
            Print("No currency data yet. Run /cn currencyscan.")
            return
        end

        Print("Currencies tracked: " .. counts.known)

        local capped = Currencies.Capped()

        if #capped > 0 then
            Print("|cffff4444At cap (" .. #capped .. ") - spend these:|r")

            for _, currency in ipairs(capped) do
                Print("  " .. tostring(currency.name)
                    .. " |cff999999" .. currency.quantity
                    .. " / " .. currency.maximum .. "|r")
            end
        end

        local weekly = Currencies.WeeklyUnfilled()

        if #weekly > 0 then
            Print("Weekly earning still available (" .. #weekly .. "):")

            for index = 1, math.min(#weekly, 8) do
                local currency = weekly[index]

                Print("  " .. tostring(currency.name)
                    .. " |cff999999" .. currency.earned .. " / " .. currency.maximum
                    .. ", " .. currency.remaining .. " left this week|r")
            end
        end

        if #capped == 0 and #weekly == 0 then
            Print("Nothing capped, nothing left to earn this week.")
        end
    end,
}

CN:RegisterCommand{
    name    = "currencyscan",
    order   = 78,
    help    = "Rescan currencies for this character.",
    handler = function()
        local seen, atCap, weekly = Currencies.Scan()

        Print("Scanned " .. seen .. " currencies.")
        Print("At cap: " .. atCap .. "   With weekly earning left: " .. weekly)
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Breakdown.lua'] = @'
-- Modules/Breakdown.lua
-- Completion Navigator :: "why isn't this 100%?"
--
-- Every other module answers what it tracks. None of them answer the
-- question a completionist actually asks, which is why a category is not
-- finished and what specifically is in the way.
--
-- Two rules shape this module.
--
-- 1. A percentage is only shown where the denominator is trustworthy. The
--    client knows exactly how many mounts exist; nobody knows how many
--    quests exist. Where the denominator is unknown, counts are shown and
--    the reason is stated, rather than inventing a number that looks
--    authoritative and is not.
--
-- 2. Every line says what to do next, not just what is missing. "4 vendor
--    recipes" is trivia; "4 recipes, open the profession window to see
--    which" is an instruction.

local ADDON_NAME, CN = ...

local Breakdown = CN:RegisterModule("Breakdown")

local Print = CN.Print

-- "1 are locked" reads as a bug even when the number is right.
local function Are(count)
    return count == 1 and "is" or "are"
end

local function Plural(count, singular, plural)
    return count == 1 and singular or (plural or (singular .. "s"))
end

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

-- Each category reports: collected, total (or nil when unknowable),
-- remaining lines, and the next action.
Breakdown.categories = {}

function Breakdown.Register(definition)
    if type(definition) ~= "table" or not definition.name then
        return
    end

    definition.order = definition.order or 100

    table.insert(Breakdown.categories, definition)

    table.sort(Breakdown.categories, function(a, b)
        if a.order == b.order then
            return a.name < b.name
        end

        return a.order < b.order
    end)
end

------------------------------------------------------------
-- REPORT
------------------------------------------------------------

local function Percentage(collected, total)
    if not total or total <= 0 then
        return nil
    end

    return collected / total * 100
end

function Breakdown.Report(categoryName)
    local rows = {}

    for _, category in ipairs(Breakdown.categories) do
        if not categoryName
            or string.lower(category.name) == string.lower(categoryName) then

            local ok, result = pcall(category.report)

            if ok and type(result) == "table" then
                result.name  = category.name
                result.order = category.order

                table.insert(rows, result)
            end
        end
    end

    return rows
end

------------------------------------------------------------
-- BUILT-IN CATEGORIES
------------------------------------------------------------

Breakdown.Register{
    name  = "Mounts",
    order = 10,
    report = function()
        local module = CN:GetModule("Mounts")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.wrongFaction > 0 then
            table.insert(reasons, counts.wrongFaction .. " " .. Are(counts.wrongFaction)
                .. " locked to the opposite faction")
        end

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn mountscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Pets",
    order = 11,
    report = function()
        local module = CN:GetModule("Pets")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.unobtainable > 0 then
            table.insert(reasons, counts.unobtainable .. " " .. Are(counts.unobtainable)
                .. " no longer obtainable and can never be collected")
        end

        if counts.wildMissing > 0 then
            table.insert(reasons, counts.wildMissing .. " " .. Are(counts.wildMissing) .. " "
                .. Plural(counts.wildMissing, "a wild pet", "wild pets")
                .. " you can catch in the world")
        end

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn petscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Toys",
    order = 12,
    report = function()
        local module = CN:GetModule("Toys")

        if not module then return nil end

        local counts = module.Summary()

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            action    = counts.known == 0 and "/cn toyscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Appearances",
    order = 13,
    report = function()
        local module = CN:GetModule("Appearances")

        if not module then return nil end

        local counts = module.Summary()
        local rows   = module.Remaining()

        local reasons = {}

        for index = 1, math.min(3, #rows) do
            table.insert(reasons, rows[index].name .. ": "
                .. rows[index].remaining .. " left")
        end

        return {
            collected = counts.collected,
            total     = counts.total,
            remaining = counts.total - counts.collected,
            reasons   = reasons,
            action    = counts.categories == 0 and "/cn appearancescan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Achievements",
    order = 14,
    report = function()
        local module = CN:GetModule("Achievements")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.nearlyDone > 0 then
            table.insert(reasons, counts.nearlyDone .. " " .. Are(counts.nearlyDone)
                .. " within two criteria of finishing")
        end

        return {
            collected = counts.completed,
            total     = counts.total,
            remaining = counts.total - counts.completed,
            reasons   = reasons,
            action    = counts.total == 0 and "/cn achievescan"
                or (counts.nearlyDone > 0 and "/cn closest" or nil),
        }
    end,
}

Breakdown.Register{
    name  = "Titles",
    order = 15,
    report = function()
        local module = CN:GetModule("Titles")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.onAccount > counts.onThisOne then
            local elsewhere = counts.onAccount - counts.onThisOne

            table.insert(reasons, elsewhere .. " " .. Are(elsewhere)
                .. " held by another character, not this one")
        end

        return {
            collected = counts.onAccount,
            total     = counts.known,
            remaining = counts.known - counts.onAccount,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn titlescan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Reputations",
    order = 16,
    report = function()
        local module = CN:GetModule("Reputations")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.paragonPending > 0 then
            table.insert(reasons, counts.paragonPending .. " " .. Plural(counts.paragonPending, "has", "have")
                .. " a Paragon reward waiting to be collected")
        end

        if counts.character > 0 then
            table.insert(reasons, counts.character .. " " .. Are(counts.character)
                .. " character-specific, so an alt may be further ahead")
        end

        -- Total factions in the game is not knowable from the client.
        return {
            collected = counts.exalted + counts.maxedRenown,
            total     = nil,
            remaining = nil,
            unknownTotal = "the client does not expose how many factions exist",
            reasons   = reasons,
            action    = (counts.account + counts.character) == 0
                and "/cn repscan"
                or (counts.paragonPending > 0 and "/cn paragon" or nil),
        }
    end,
}

Breakdown.Register{
    name  = "Recipes",
    order = 17,
    report = function()
        local module = CN:GetModule("Professions")

        if not module then return nil end

        local waiting = module.AwaitingRecipeCapture()

        local reasons = {}

        if #waiting > 0 then
            table.insert(reasons, "recipe lists not captured for: "
                .. table.concat(waiting, ", "))
        end

        local known = 0

        for _, record in ipairs(module.Summary()) do
            known = known + (record.recipeKnown or 0)
        end

        return {
            collected    = known,
            total        = nil,
            unknownTotal = "recipes are only countable while a profession window is open",
            reasons      = reasons,
            action       = #waiting > 0 and "open each profession window once" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Quests",
    order = 18,
    report = function()
        local discovered = CN.CountKeys(CN.Account("discoveredQuests"))

        local completed = 0

        for _, status in pairs(CN.Account("questStatus")) do
            if status.characterCompleted then
                completed = completed + 1
            end
        end

        return {
            collected    = completed,
            total        = nil,
            unknownTotal = "no API reports how many quests exist; "
                .. "only quests this addon has seen can be counted",
            reasons      = {
                discovered .. " quests discovered so far",
                CN.CountKeys(CN.Account("questHarvest")) .. " harvested with location data",
            },
            action = "/cn harvest",
        }
    end,
}

Breakdown.Register{
    name  = "Currencies",
    order = 19,
    report = function()
        local module = CN:GetModule("Currencies")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.capped > 0 then
            table.insert(reasons, counts.capped .. " " .. Are(counts.capped)
                .. " at cap; further earning is wasted")
        end

        if counts.weeklyUnfilled > 0 then
            table.insert(reasons, counts.weeklyUnfilled .. " still " .. Plural(counts.weeklyUnfilled, "has", "have")
                .. " weekly earning available")
        end

        return {
            collected    = counts.known - counts.capped,
            total        = nil,
            unknownTotal = "currencies are a state to manage, not a set to complete",
            reasons      = reasons,
            action       = counts.capped > 0 and "/cn currencies" or nil,
        }
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

local function PrintRow(row)
    local percentage = Percentage(row.collected, row.total)

    if percentage then
        Print(string.format("|cffffd100%s|r  %d / %d  (%.1f%%)",
            row.name, row.collected, row.total, percentage))
    else
        Print(string.format("|cffffd100%s|r  %d collected",
            row.name, row.collected or 0))

        if row.unknownTotal then
            Print("    |cff999999no percentage: " .. row.unknownTotal .. "|r")
        end
    end

    for _, reason in ipairs(row.reasons or {}) do
        Print("    " .. reason)
    end

    if row.action then
        Print("    |cffffff00-> " .. row.action .. "|r")
    end
end

CN:RegisterCommand{
    name    = "breakdown",
    aliases = { "remaining" },
    args    = "[category]",
    order   = 19,
    help    = "Explain what is left in each category, and why.",
    handler = function(args)
        local requested = args ~= "" and args or nil

        local rows = Breakdown.Report(requested)

        if #rows == 0 then
            if requested then
                Print("No category matches: " .. requested)

                local names = {}

                for _, category in ipairs(Breakdown.categories) do
                    table.insert(names, category.name)
                end

                Print("Try: " .. table.concat(names, ", "))
            else
                Print("Nothing to report yet. Run the scans first.")
            end

            return
        end

        Print("What is left, and why:")

        for _, row in ipairs(rows) do
            PrintRow(row)
        end

        if not requested then
            Print("|cff999999/cn breakdown <category> for one at a time.|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Exploration.lua'] = @'
-- Modules/Exploration.lua
-- Completion Navigator :: map exploration.
--
-- The map API exposes which overlay textures you have revealed but never how
-- many exist, so a genuine "percent explored" cannot be computed from it.
-- The Exploration achievement category does carry one criterion per subzone,
-- which is the only countable exploration data the client offers -- and each
-- unfinished criterion is the literal name of a place you have not been.
--
-- That turns out to be the more useful shape anyway: "Eversong Woods, 3 of
-- 12 subzones, missing Sunsail Anchorage" is actionable. "78% explored" is
-- not.

local ADDON_NAME, CN = ...

local Exploration = CN:RegisterModule("Exploration")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("exploration")
end

Exploration.Store = Store

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Exploration.Scan()
    local store = Store()

    local seen, complete = 0, 0

    for _, achievement in ipairs(Blizzard.GetExplorationAchievements()) do
        store[achievement.achievementID] = {
            achievementID = achievement.achievementID,
            name          = achievement.name,
            completed     = achievement.completed,
            done          = achievement.done,
            criteria      = achievement.criteria,
            lastSeen      = time(),
        }

        seen = seen + 1

        if achievement.completed then
            complete = complete + 1
        end
    end

    CN.MarkScanned("exploration")

    return seen, complete
end

------------------------------------------------------------
-- QUERIES
------------------------------------------------------------

function Exploration.Summary()
    local counts = {
        zones     = 0,
        complete  = 0,
        criteria  = 0,
        done      = 0,
    }

    for _, record in pairs(Store()) do
        counts.zones    = counts.zones + 1
        counts.criteria = counts.criteria + (record.criteria or 0)
        counts.done     = counts.done + (record.done or 0)

        if record.completed then
            counts.complete = counts.complete + 1
        end
    end

    return counts
end

-- Zones with the fewest subzones left, so the cheapest wins come first.
function Exploration.Closest(limit)
    local rows = {}

    for _, record in pairs(Store()) do
        if not record.completed and (record.criteria or 0) > 0 then
            table.insert(rows, {
                achievementID = record.achievementID,
                name          = record.name,
                done          = record.done,
                criteria      = record.criteria,
                remaining     = record.criteria - record.done,
            })
        end
    end

    table.sort(rows, function(a, b)
        if a.remaining == b.remaining then
            return (a.name or "") < (b.name or "")
        end

        return a.remaining < b.remaining
    end)

    local results = {}

    for index = 1, math.min(limit or 10, #rows) do
        table.insert(results, rows[index])
    end

    return results
end

-- The exploration achievement matching the zone the player is standing in,
-- matched on name because no API maps a UiMapID to its achievement.
function Exploration.ForCurrentZone()
    local zone = GetZoneText and GetZoneText()

    if not zone or zone == "" then
        return nil
    end

    local needle = string.lower(zone)

    for _, record in pairs(Store()) do
        if record.name and string.find(string.lower(record.name), needle, 1, true) then
            return record
        end
    end

    return nil
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only the zone the player is already in. Exploration elsewhere is a
-- project, and the criteria carry no coordinates to route to.
CN.RegisterCandidateProvider("Exploration", function()
    local candidates = {}

    local record = Exploration.ForCurrentZone()

    if record and not record.completed and (record.criteria or 0) > 0 then
        local remaining = record.criteria - record.done

        if remaining > 0
            and not CN.IsIgnored(CN.objectiveTypes.EXPLORATION, record.achievementID)
            and not CN.IsDeferred(CN.objectiveTypes.EXPLORATION, record.achievementID) then

            local reasons = {
                remaining .. " subzone" .. (remaining == 1 and "" or "s")
                    .. " left in this zone",
            }

            local missing = Blizzard.GetIncompleteCriteria(record.achievementID, 3)

            if #missing > 0 then
                table.insert(reasons, "missing: " .. table.concat(missing, ", "))
            end

            table.insert(candidates, CN.NewObjective({
                id              = record.achievementID,
                type            = CN.objectiveTypes.EXPLORATION,
                name            = record.name,
                accountWide     = true,
                completionValue = math.max(1, 4 - remaining),
                travelCost      = 0,
                reasons         = reasons,
            }))
        end
    end

    return candidates
end, { events = { "CRITERIA_UPDATE", "ZONE_CHANGED_NEW_AREA" } })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    -- Discovering a subzone fires criteria updates; the Achievements module
    -- already throttles those, so only refresh the exploration view.
    local record = Exploration.ForCurrentZone()

    if record then
        local done, criteria = Blizzard.GetAchievementProgress(record.achievementID)

        record.done     = done
        record.criteria = criteria
    end
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "explorescan",
    order   = 67,
    help    = "Scan exploration achievements.",
    handler = function()
        local seen, complete = Exploration.Scan()

        Print("Scanned " .. seen .. " exploration achievements.")
        Print("Complete: " .. complete)
    end,
}

CN:RegisterCommand{
    name    = "exploration",
    aliases = { "explore" },
    args    = "[count]",
    order   = 68,
    help    = "Show zones with the least exploration left.",
    handler = function(args)
        local counts = Exploration.Summary()

        if counts.zones == 0 then
            Print("No exploration data yet. Run /cn explorescan.")
            return
        end

        Print("Exploration: " .. counts.complete .. " / " .. counts.zones .. " zones")

        if counts.criteria > 0 then
            Print(string.format("Subzones discovered: %d / %d (%.1f%%)",
                counts.done, counts.criteria, counts.done / counts.criteria * 100))
        end

        local here = Exploration.ForCurrentZone()

        if here then
            if here.completed then
                Print("This zone: |cff00ff00fully explored|r")
            else
                Print("This zone: " .. here.done .. " / " .. here.criteria)

                local missing = Blizzard.GetIncompleteCriteria(here.achievementID, 6)

                for _, name in ipairs(missing) do
                    Print("  missing: " .. name)
                end
            end
        end

        local closest = Exploration.Closest(CN.ToID(args) or 5)

        if #closest > 0 then
            Print("Closest to finishing:")

            for _, row in ipairs(closest) do
                Print("  " .. row.name .. " |cff999999("
                    .. row.done .. "/" .. row.criteria .. ")|r")
            end
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Filters.lua'] = @'
-- Modules/Filters.lua
-- Completion Navigator :: managing what you told the addon to hide.
--
-- Ignore and defer have existed since the first build, and until now there
-- was no way to see either list or undo anything in them. Ignoring something
-- by accident meant it was gone permanently with no recourse, which is a
-- bug wearing a feature's clothes.
--
-- Defer also only offered one hour. The spec asked for a real set of
-- durations, and "until the weekly reset" is the one that actually matches
-- how the game works.

local ADDON_NAME, CN = ...

local Filters = CN:RegisterModule("Filters")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local HOUR = 3600
local DAY  = 86400

------------------------------------------------------------
-- DURATIONS
------------------------------------------------------------

-- Ordered, because they are offered as a list in the UI.
Filters.durations = {
    { key = "hour",    label = "1 hour",        seconds = HOUR },
    { key = "day",     label = "Today",         seconds = DAY },
    { key = "tomorrow",label = "Tomorrow",      seconds = 2 * DAY },
    { key = "week",    label = "This week",     seconds = 7 * DAY },
    { key = "reset",   label = "Until reset",   seconds = nil },  -- computed
    { key = "forever", label = "Until I undo it", seconds = math.huge },
}

function Filters.SecondsFor(key)
    for _, duration in ipairs(Filters.durations) do
        if duration.key == key then
            if duration.key == "reset" then
                local opportunities = CN:GetModule("Opportunities")

                if opportunities then
                    local resets = opportunities.GetResets()

                    -- Weekly if it is sooner than a week away, else daily.
                    return resets.weekly or resets.daily or DAY
                end

                return DAY
            end

            return duration.seconds
        end
    end

    return nil
end

------------------------------------------------------------
-- TYPE FILTERING
------------------------------------------------------------

-- Which KINDS of objective the recommendation list may contain.
--
-- Distinct from ignore and defer, which hide one specific objective. This is a
-- standing preference about what you want to be told about at all: someone
-- levelling wants quests, someone finishing a collection does not.
--
-- Only DISABLED types are stored. That way a type added in a later release is
-- enabled by default rather than silently invisible to everyone who upgraded,
-- which is the failure mode of storing an allow-list.
local function HiddenTypes()
    local settings = CN.Settings()

    if not settings then
        return {}
    end

    settings.hiddenTypes = settings.hiddenTypes or {}

    return settings.hiddenTypes
end

Filters.HiddenTypes = HiddenTypes

-- Bumped whenever the filter changes, so the ranked list knows to rebuild
-- without invalidating the providers, which have not changed at all.
CN.typeFilterGeneration = 0

local function Bump()
    CN.typeFilterGeneration = (CN.typeFilterGeneration or 0) + 1
end

function Filters.IsTypeEnabled(objectiveType)
    if not objectiveType then
        return true
    end

    local hidden = HiddenTypes()

    if next(hidden) == nil then
        return true
    end

    return not hidden[objectiveType]
end

function Filters.SetTypeEnabled(objectiveType, enabled)
    if not objectiveType then
        return false
    end

    local hidden = HiddenTypes()

    if enabled then
        hidden[objectiveType] = nil
    else
        hidden[objectiveType] = true
    end

    Bump()

    return true
end

function Filters.ToggleType(objectiveType)
    local enabled = Filters.IsTypeEnabled(objectiveType)

    Filters.SetTypeEnabled(objectiveType, not enabled)

    return not enabled
end

function Filters.EnableAllTypes()
    local hidden = HiddenTypes()

    local count = CN.CountKeys(hidden)

    for key in pairs(hidden) do
        hidden[key] = nil
    end

    Bump()

    return count
end

-- Everything except this one.
function Filters.OnlyType(objectiveType)
    local hidden = HiddenTypes()

    for key in pairs(hidden) do
        hidden[key] = nil
    end

    for _, known in ipairs(Filters.TypeOrder()) do
        if known ~= objectiveType then
            hidden[known] = true
        end
    end

    Bump()

    return true
end

-- The types worth offering, in a stable order. Deliberately not every entry in
-- CN.objectiveTypes: VENDOR and COLLECTIBLE are internal plumbing rather than
-- things anyone would choose to be shown.
function Filters.TypeOrder()
    local types = CN.objectiveTypes

    return {
        types.QUEST,
        types.ACHIEVEMENT,
        types.REPUTATION,
        types.PET,
        types.MOUNT,
        types.TOY,
        types.APPEARANCE,
        types.RECIPE,
        types.PROFESSION,
        types.RARE,
        types.TREASURE,
        types.EXPLORATION,
        types.TITLE,
        types.CURRENCY,
    }
end

-- Friendly names, because "APPEARANCE" is how the code thinks and not how a
-- person reads a checkbox.
Filters.typeLabels = {
    QUEST       = "Quests",
    ACHIEVEMENT = "Achievements",
    REPUTATION  = "Reputations",
    PET         = "Battle pets",
    MOUNT       = "Mounts",
    TOY         = "Toys",
    APPEARANCE  = "Appearances",
    RECIPE      = "Recipes",
    PROFESSION  = "Professions",
    RARE        = "Rares",
    TREASURE    = "Treasures",
    EXPLORATION = "Exploration",
    TITLE       = "Titles",
    CURRENCY    = "Currencies",
}

function Filters.TypeLabel(objectiveType)
    return Filters.typeLabels[objectiveType] or tostring(objectiveType)
end

-- Accepts what a person would actually type.
function Filters.ResolveType(text)
    if not text or text == "" then
        return nil
    end

    local needle = string.lower(CN.Trim(text))

    for _, objectiveType in ipairs(Filters.TypeOrder()) do
        if string.lower(objectiveType) == needle
            or string.lower(Filters.TypeLabel(objectiveType)) == needle then
            return objectiveType
        end

        -- "quest" should match QUEST, "pet" should match PET.
        if string.lower(Filters.TypeLabel(objectiveType)):find(needle, 1, true) then
            return objectiveType
        end
    end

    return nil
end

function Filters.HiddenTypeCount()
    return CN.CountKeys(HiddenTypes())
end

-- Exposed on CN so the scoring layer can consult it without knowing that a
-- Filters module exists.
function CN.IsObjectiveTypeEnabled(objectiveType)
    return Filters.IsTypeEnabled(objectiveType)
end

------------------------------------------------------------
-- READING THE LISTS
------------------------------------------------------------

-- Objective keys are "TYPE:id". Splitting them back out is what lets the
-- lists show a name rather than an opaque string.
local function SplitKey(key)
    local objectiveType, id = string.match(tostring(key), "^(.-):(.+)$")

    return objectiveType, tonumber(id) or id
end

Filters.SplitKey = SplitKey

-- Best-effort name for anything the addon might have hidden.
function Filters.DescribeObjective(objectiveType, id)
    local types = CN.objectiveTypes

    local numericID = tonumber(id)

    if objectiveType == types.QUEST and numericID then
        return CN.GetQuestName(numericID) or ("Quest " .. numericID)
    end

    -- Cached name first, then ask the client.
    --
    -- Names used to come only from a previous scan, so pinning something the
    -- addon had not seen yet produced "Faction 2600" -- which is the addon
    -- telling the player it does not know what they just asked for. The
    -- client knows. Ask it.
    if objectiveType == types.REPUTATION and numericID then
        local cached = CN.Account("factionNames")[numericID]

        if cached then
            return cached
        end

        local data = CN.Blizzard.GetFactionByID(numericID)

        return (data and data.name) or ("Faction " .. numericID)
    end

    if objectiveType == types.PET and numericID then
        local record = CN.Account("pets")[numericID]
        return record and record.name or ("Pet " .. numericID)
    end

    if objectiveType == types.MOUNT and numericID then
        local record = CN.Account("mounts")[numericID]

        if record and record.name then
            return record.name
        end

        local live = CN.Blizzard.GetMountByID(numericID)

        return (live and live.name) or ("Mount " .. numericID)
    end

    if objectiveType == types.TOY and numericID then
        local record = CN.Account("toys")[numericID]
        return record and record.name or ("Toy " .. numericID)
    end

    if (objectiveType == types.RARE or objectiveType == types.TREASURE) and numericID then
        local record = CN.Account("rares")[numericID]
        return record and record.name or (objectiveType .. " " .. numericID)
    end

    if objectiveType == types.ACHIEVEMENT and numericID then
        local record = CN.Account("achievements")[numericID]

        if record and record.name then
            return record.name
        end

        return CN.Blizzard.GetAchievementName(numericID)
            or ("Achievement " .. numericID)
    end

    if objectiveType == types.CURRENCY and numericID then
        return CN.Account("currencyNames")[numericID] or ("Currency " .. numericID)
    end

    if objectiveType == types.RECIPE and numericID then
        return CN.Account("recipeNames")[numericID] or ("Recipe " .. numericID)
    end

    if objectiveType == types.TITLE and numericID then
        return CN.Account("titleNames")[numericID] or ("Title " .. numericID)
    end

    return tostring(objectiveType) .. " " .. tostring(id)
end

function Filters.ListIgnored()
    local rows = {}

    for key, entry in pairs(CN.Account("ignoredObjectives")) do
        local objectiveType, id = SplitKey(key)

        table.insert(rows, {
            key   = key,
            type  = objectiveType,
            id    = id,
            name  = Filters.DescribeObjective(objectiveType, id),
            since = entry and entry.since,
        })
    end

    table.sort(rows, function(a, b) return (a.name or "") < (b.name or "") end)

    return rows
end

function Filters.ListDeferred()
    local rows = {}

    local now = time()

    for key, entry in pairs(CN.Account("deferredObjectives")) do
        local objectiveType, id = SplitKey(key)

        local remaining

        if entry and entry.until_ then
            remaining = entry.until_ - now
        end

        table.insert(rows, {
            key       = key,
            type      = objectiveType,
            id        = id,
            name      = Filters.DescribeObjective(objectiveType, id),
            remaining = remaining,
            expired   = remaining ~= nil and remaining <= 0,
        })
    end

    table.sort(rows, function(a, b)
        return (a.remaining or math.huge) < (b.remaining or math.huge)
    end)

    return rows
end

------------------------------------------------------------
-- UNDO
------------------------------------------------------------

function Filters.Restore(key)
    local ignored  = CN.Account("ignoredObjectives")
    local deferred = CN.Account("deferredObjectives")

    local removed = false

    if ignored[key] then
        ignored[key] = nil
        removed = true
    end

    if deferred[key] then
        deferred[key] = nil
        removed = true
    end

    return removed
end

function Filters.RestoreAll()
    local ignored  = CN.Account("ignoredObjectives")
    local deferred = CN.Account("deferredObjectives")

    local count = CN.CountKeys(ignored) + CN.CountKeys(deferred)

    for key in pairs(ignored) do
        ignored[key] = nil
    end

    for key in pairs(deferred) do
        deferred[key] = nil
    end

    return count
end

-- Deferrals that have run out are dead weight in SavedVariables.
function Filters.PruneExpired()
    local deferred = CN.Account("deferredObjectives")

    local now, pruned = time(), 0

    for key, entry in pairs(deferred) do
        if entry and entry.until_ and entry.until_ <= now then
            deferred[key] = nil
            pruned = pruned + 1
        end
    end

    return pruned
end

CN:OnLogin(function()
    local pruned = Filters.PruneExpired()

    if pruned > 0 then
        DebugPrint("Pruned " .. pruned .. " expired deferrals.")
    end
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

local function FormatRemaining(seconds)
    if not seconds then
        return "indefinitely"
    end

    if seconds <= 0 then
        return "expired"
    end

    if seconds < HOUR then
        return math.floor(seconds / 60) .. "m"
    end

    if seconds < DAY then
        return math.floor(seconds / HOUR) .. "h"
    end

    return math.floor(seconds / DAY) .. "d"
end

Filters.FormatRemaining = FormatRemaining

CN:RegisterCommand{
    name    = "hidden",
    aliases = { "ignored" },
    order   = 20,
    help    = "Show everything you have ignored or deferred.",
    handler = function()
        local ignored  = Filters.ListIgnored()
        local deferred = Filters.ListDeferred()

        if #ignored == 0 and #deferred == 0 then
            Print("Nothing is hidden.")
            return
        end

        if #ignored > 0 then
            Print("Ignored (" .. #ignored .. "):")

            for _, row in ipairs(ignored) do
                Print("  " .. row.name .. " |cff999999[" .. tostring(row.type)
                    .. " " .. tostring(row.id) .. "]|r")
            end
        end

        if #deferred > 0 then
            Print("Deferred (" .. #deferred .. "):")

            for _, row in ipairs(deferred) do
                Print("  " .. row.name .. " |cff999999["
                    .. FormatRemaining(row.remaining) .. " left]|r")
            end
        end

        Print("|cffffff00/cn unhide <id>|r to restore one, "
            .. "|cffffff00/cn unhide all|r for everything.")
    end,
}

CN:RegisterCommand{
    name    = "unhide",
    aliases = { "restore" },
    args    = "<id or all>",
    order   = 21,
    help    = "Undo an ignore or a deferral.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn unhide <id or all>")
            return
        end

        if string.lower(args) == "all" then
            local count = Filters.RestoreAll()

            Print("Restored " .. count .. " hidden objective"
                .. (count == 1 and "" or "s") .. ".")
            return
        end

        local wanted = tostring(CN.ToID(args) or args)

        local restored = 0

        -- Match on the id alone, since the player sees ids and not the
        -- internal TYPE:id key.
        for _, row in ipairs(Filters.ListIgnored()) do
            if tostring(row.id) == wanted then
                if Filters.Restore(row.key) then
                    Print("Restored: " .. row.name)
                    restored = restored + 1
                end
            end
        end

        for _, row in ipairs(Filters.ListDeferred()) do
            if tostring(row.id) == wanted then
                if Filters.Restore(row.key) then
                    Print("Restored: " .. row.name)
                    restored = restored + 1
                end
            end
        end

        if restored == 0 then
            Print("Nothing hidden matches: " .. args)
            Print("Run |cffffff00/cn hidden|r to see the list.")
        end
    end,
}

------------------------------------------------------------
-- MODES
------------------------------------------------------------

-- Applying a mode is two existing operations performed together, plus a
-- record of what was on before so it can be undone.
function Filters.ApplyMode(name)
    local mode = CN.modes[name]

    if not mode then
        return false, "No such mode."
    end

    local settings = CN.Settings()

    -- Remember what to go back to. One level deep on purpose: an undo stack
    -- for a display preference is a feature nobody asked for.
    settings.modePrevious = {
        profile = settings.priorityMode,
        hidden  = {},
    }

    for _, objectiveType in ipairs(Filters.TypeOrder()) do
        if not Filters.IsTypeEnabled(objectiveType) then
            table.insert(settings.modePrevious.hidden, objectiveType)
        end
    end

    settings.priorityMode = mode.profile or "balanced"

    Filters.EnableAllTypes()

    if mode.show then
        local wanted = {}

        for _, objectiveType in ipairs(mode.show) do
            wanted[objectiveType] = true
        end

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            if not wanted[objectiveType] then
                Filters.SetTypeEnabled(objectiveType, false)
            end
        end
    end

    settings.mode = name

    CN.InvalidateCandidates("mode")

    return true, mode
end

function Filters.CurrentMode()
    local settings = CN.Settings()

    return settings and settings.mode, settings and CN.modes[settings.mode]
end

function Filters.ClearMode()
    local settings = CN.Settings()

    local previous = settings.modePrevious

    Filters.EnableAllTypes()

    if previous then
        settings.priorityMode = previous.profile or "balanced"

        for _, objectiveType in ipairs(previous.hidden or {}) do
            Filters.SetTypeEnabled(objectiveType, false)
        end
    end

    settings.mode         = nil
    settings.modePrevious = nil

    CN.InvalidateCandidates("mode")

    return true
end

CN:RegisterCommand{
    name    = "show",
    aliases = { "types" },
    args    = "[type, only <type>, or all]",
    order   = 17,
    help    = "Choose which kinds of objective appear in recommendations.",
    handler = function(args)
        args = CN.Trim(args or "")

        local lowered = string.lower(args)

        if lowered == "all" then
            local restored = Filters.EnableAllTypes()

            Print("Showing every type again"
                .. (restored > 0 and (" (" .. restored .. " restored)") or "") .. ".")

        elseif lowered:match("^only%s+") then
            local wanted = Filters.ResolveType(lowered:gsub("^only%s+", ""))

            if not wanted then
                Print("Not a type: " .. args)
                Print("|cffffff00/cn show|r lists them.")
                return
            end

            Filters.OnlyType(wanted)

            Print("Showing only " .. Filters.TypeLabel(wanted) .. ".")

        elseif args ~= "" then
            local wanted = Filters.ResolveType(args)

            if not wanted then
                Print("Not a type: " .. args)
                Print("|cffffff00/cn show|r lists them.")
                return
            end

            local nowEnabled = Filters.ToggleType(wanted)

            Print(Filters.TypeLabel(wanted) .. ": " .. CN.YesNo(nowEnabled))
        end

        local hiddenCount = Filters.HiddenTypeCount()

        Print("Recommendation types"
            .. (hiddenCount > 0 and (" |cffffff00" .. hiddenCount .. " hidden|r") or ""))

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            local enabled = Filters.IsTypeEnabled(objectiveType)

            Print("  " .. CN.YesNo(enabled) .. " " .. Filters.TypeLabel(objectiveType)
                .. " |cff999999" .. string.lower(objectiveType) .. "|r")
        end

        Print("|cff999999/cn show pets|r toggles one, |cff999999/cn show only quests|r "
            .. "narrows to one, |cff999999/cn show all|r restores everything.")

        if hiddenCount > 0 then
            Print("|cff999999Hidden types still appear in /cn breakdown and the "
                .. "Collections tab; this only filters recommendations.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "percharacter",
    aliases = { "perchar" },
    args    = "[setting]",
    order   = 18,
    help    = "Make a setting apply to this character only.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        local settings = CN.Settings()

        if args ~= "" then
            if not CN.characterOverridable[args] then
                Print("That setting cannot be set per character: " .. args)
                Print("|cff999999Overridable: priorityMode, autoWaypoint, "
                    .. "arrow, tooltips|r")
                return
            end

            if CN.IsOverridden(args) then
                CN.ClearOverride(args)

                Print(args .. " now follows the account setting again ("
                    .. tostring(settings[args]) .. ").")
            else
                -- Seed the override with whatever this character sees now, so
                -- taking control never changes the current behaviour.
                local ok, message = CN.SetOverride(args, settings[args])

                if not ok then
                    Print(message)
                    return
                end

                Print(args .. " is now set for this character only ("
                    .. tostring(settings[args]) .. ").")
            end
        end

        Print("Settings for " .. tostring(CN.characterKey or "this character") .. ":")

        for _, key in ipairs({ "priorityMode", "autoWaypoint", "arrow", "tooltips" }) do
            local overridden = CN.IsOverridden(key)

            Print("  " .. key .. " = " .. tostring(settings[key])
                .. (overridden
                    and " |cffffff00this character only|r"
                    or " |cff999999account-wide|r"))
        end

        Print("|cff999999/cn perchar priorityMode|r toggles whether a setting "
            .. "is shared or per character.")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Vendors.lua'] = @'
-- Modules/Vendors.lua
-- Completion Navigator :: who sells what, and where they stand.
--
-- This is the module the flagship example in the design needs:
--
--   Recipe X is sold by Vendor A. Vendor A is in <zone> at <coords>.
--   The recipe requires Revered with Faction B. This character is Honored.
--   Another character is already Revered and has the profession.
--   -> Switch to that character and buy it.
--
-- Every other piece of that already exists. The missing link was that
-- nothing knew where anything is sold.
--
-- Vendor inventories are only readable while the merchant window is open --
-- the same client restriction as trade skill recipes. So this records every
-- vendor you talk to, permanently and account-wide, and the database grows
-- as you play rather than shipping stale.

local ADDON_NAME, CN = ...

local Vendors = CN:RegisterModule("Vendors")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("vendors")
end

-- Reverse index: itemID -> { npcID, npcID, ... }. Rebuilt from the vendor
-- store rather than persisted, so it can never drift out of sync with it.
local itemIndex = nil

Vendors.Store = Store

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

function Vendors.CaptureOpenMerchant()
    local npcID, npcName = Blizzard.GetInteractingNPC()

    if not npcID then
        return false, 0
    end

    local items = Blizzard.GetMerchantItems()

    if #items == 0 then
        return false, 0
    end

    local store  = Store()
    local record = store[npcID] or { npcID = npcID, firstSeen = time() }

    record.name     = npcName or record.name
    record.lastSeen = time()

    local mapID, x, y = CN.GetPlayerPosition()

    -- Keep the first location seen; vendors do not move, and later readings
    -- are just wherever you happened to be standing when you opened the
    -- window a second time.
    if mapID and x and y and not record.mapID then
        record.mapID = mapID
        record.x     = math.floor(x * 10000 + 0.5) / 10000
        record.y     = math.floor(y * 10000 + 0.5) / 10000
        record.zone  = Blizzard.GetMapName(mapID)
    end

    record.items = {}

    for _, item in ipairs(items) do
        if item.itemID then
            record.items[item.itemID] = {
                name         = item.name,
                price        = item.price,
                extendedCost = item.extendedCost,
            }
        end
    end

    record.itemCount = CN.CountKeys(record.items)

    store[npcID] = record

    -- The reverse index is now stale.
    itemIndex = nil

    CN.MarkScanned("vendors")

    return true, record.itemCount
end

------------------------------------------------------------
-- LOOKUP
------------------------------------------------------------

local function BuildItemIndex()
    local index = {}

    for npcID, record in pairs(Store()) do
        for itemID in pairs(record.items or {}) do
            index[itemID] = index[itemID] or {}
            table.insert(index[itemID], npcID)
        end
    end

    itemIndex = index

    return index
end

-- The candidate provider asks this question thousands of times per rebuild,
-- once per known recipe, and almost always gets no answer. WhoSells allocates
-- a result array every time it is called; this does not allocate at all until
-- there is something to return.
function Vendors.FirstLocatedSeller(itemID)
    if not itemID then
        return nil
    end

    local index = itemIndex or BuildItemIndex()

    local npcIDs = index[itemID]

    if not npcIDs then
        return nil
    end

    local store = Store()

    for _, npcID in ipairs(npcIDs) do
        local record = store[npcID]

        if record and record.mapID and record.x and record.y then
            return record, npcID
        end
    end

    return nil
end

function Vendors.WhoSells(itemID)
    if not itemID then
        return {}
    end

    local index = itemIndex or BuildItemIndex()

    local sellers = {}

    for _, npcID in ipairs(index[itemID] or {}) do
        local record = Store()[npcID]

        if record then
            table.insert(sellers, {
                npcID = npcID,
                name  = record.name,
                zone  = record.zone,
                mapID = record.mapID,
                x     = record.x,
                y     = record.y,
                item  = record.items and record.items[itemID],
            })
        end
    end

    return sellers
end

-- Finds an item by name across every recorded vendor. This is what makes
-- "who sells Flask of Testing" work without knowing an item ID.
function Vendors.FindItem(text)
    if not text or text == "" then
        return nil, {}
    end

    local itemID = CN.ToID(text)

    if itemID then
        return itemID, Vendors.WhoSells(itemID)
    end

    local needle  = string.lower(text)
    local matches = {}

    for npcID, record in pairs(Store()) do
        for id, item in pairs(record.items or {}) do
            if item.name and string.find(string.lower(item.name), needle, 1, true) then
                matches[id] = item.name
            end
        end
    end

    local bestID, bestName

    for id, name in pairs(matches) do
        if not bestName or #name < #bestName then
            bestID, bestName = id, name
        end
    end

    if not bestID then
        return nil, {}
    end

    return bestID, Vendors.WhoSells(bestID)
end

function Vendors.Summary()
    local counts = { vendors = 0, items = 0, located = 0 }

    local uniqueItems = {}

    for _, record in pairs(Store()) do
        counts.vendors = counts.vendors + 1

        if record.x and record.y then
            counts.located = counts.located + 1
        end

        for itemID in pairs(record.items or {}) do
            uniqueItems[itemID] = true
        end
    end

    counts.items = CN.CountKeys(uniqueItems)

    return counts
end

------------------------------------------------------------
-- RECIPE LINKING
------------------------------------------------------------

-- The payoff: a recipe this character does not know, sold by a vendor whose
-- location is recorded, becomes an objective with real coordinates.
CN.RegisterCandidateProvider("Vendors", function()
    local professions = CN:GetModule("Professions")

    if not professions then
        return {}
    end

    local known = professions.CharacterRecipes() or {}
    local names = professions.RecipeNames()

    local playerMap = select(1, CN.GetPlayerPosition())

    local candidates, considered, dropped = CN.CollectBounded(names, nil,
        function(itemID)
            if known[itemID] then
                return nil
            end

            if CN.IsIgnored(CN.objectiveTypes.RECIPE, itemID)
                or CN.IsDeferred(CN.objectiveTypes.RECIPE, itemID) then
                return nil
            end

            local seller = Vendors.FirstLocatedSeller(itemID)

            if not seller then
                return nil
            end

            -- A recipe you can walk to in this zone beats one across the
            -- continent, and that is the only distinction worth ranking here.
            return (seller.mapID == playerMap) and 3 or 2
        end,
        function(itemID, recipeName)
            local seller = Vendors.FirstLocatedSeller(itemID)

            if not seller then
                return nil
            end

            local reasons = { "sold by " .. tostring(seller.name) }

            if seller.zone then
                table.insert(reasons, "in " .. seller.zone)
            end

            return CN.NewObjective({
                id              = itemID,
                type            = CN.objectiveTypes.RECIPE,
                name            = recipeName,
                mapID           = seller.mapID,
                x               = seller.x,
                y               = seller.y,
                completionValue = 2,
                travelCost      = (seller.mapID == playerMap) and 2 or 25,
                reasons         = reasons,
            })
        end)

    CN.providerTruncation["Vendors"] = { considered = considered, dropped = dropped }

    return candidates
end, { events = { "MERCHANT_SHOW", "TRADE_SKILL_LIST_UPDATE", "ZONE_CHANGED_NEW_AREA" }, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("MERCHANT_SHOW", function()
    local captured, count = Vendors.CaptureOpenMerchant()

    if captured then
        DebugPrint("Recorded vendor with " .. count .. " items.")
    end
end)

CN:RegisterEvent("MERCHANT_UPDATE", function()
    Vendors.CaptureOpenMerchant()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "vendors",
    order   = 79,
    help    = "Summarize recorded vendors.",
    handler = function()
        local counts = Vendors.Summary()

        if counts.vendors == 0 then
            Print("No vendors recorded yet.")
            Print("|cff999999Open a merchant window and the addon records "
                .. "what they sell and where they stand.|r")
            return
        end

        Print("Vendors recorded: " .. counts.vendors
            .. " (" .. counts.located .. " with coordinates)")
        Print("Distinct items seen: " .. counts.items)
    end,
}

CN:RegisterCommand{
    name    = "sells",
    aliases = { "whosells" },
    args    = "<itemID or name>",
    order   = 80,
    help    = "Find which recorded vendor sells something.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn sells <itemID or name>")
            return
        end

        local itemID, sellers = Vendors.FindItem(args)

        if not itemID or #sellers == 0 then
            Print("Nothing recorded matches: " .. args)
            Print("|cff999999Only vendors you have opened are known.|r")
            return
        end

        Print("Item " .. itemID .. " is sold by:")

        for index, seller in ipairs(sellers) do
            Print("  " .. index .. ". " .. tostring(seller.name)
                .. (seller.zone and (" |cff999999in " .. seller.zone .. "|r") or "")
                .. (seller.x and string.format(" |cff999999%.1f, %.1f|r",
                    seller.x * 100, seller.y * 100) or ""))
        end

        Print("|cffffff00/cn tovendor " .. itemID .. "|r to set a waypoint.")
    end,
}

CN:RegisterCommand{
    name    = "tovendor",
    args    = "<itemID or name>",
    order   = 81,
    help    = "Navigate to a vendor that sells something.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn tovendor <itemID or name>")
            return
        end

        local itemID, sellers = Vendors.FindItem(args)

        if not itemID or #sellers == 0 then
            Print("Nothing recorded matches: " .. args)
            return
        end

        for _, seller in ipairs(sellers) do
            if seller.mapID and seller.x and seller.y then
                CN.NavigateToObjective({
                    id    = seller.npcID,
                    type  = CN.objectiveTypes.VENDOR,
                    name  = seller.name,
                    mapID = seller.mapID,
                    x     = seller.x,
                    y     = seller.y,
                })

                return
            end
        end

        Print("No recorded seller has coordinates yet.")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Tooltips.lua'] = @'
-- Modules/Tooltips.lua
-- Completion Navigator :: what the addon knows, shown where you are looking.
--
-- Everything in this addon already knows whether you own a toy, which of your
-- characters knows a recipe, and which vendor sells an item. Until now you had
-- to go and ask. A tooltip is where that question actually gets asked -- while
-- hovering the thing in a vendor list, a loot window or the auction house.
--
-- The line-building functions are deliberately separate from the hooks: the
-- lines are pure data, so they can be tested offline, and the hooks are a thin
-- adapter over whichever tooltip API the client is running.

local ADDON_NAME, CN = ...

local Tooltips = CN:RegisterModule("Tooltips")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local GREEN  = { 0.4, 1.0, 0.4 }
local RED    = { 1.0, 0.4, 0.4 }
local YELLOW = { 1.0, 0.85, 0.3 }
local GREY   = { 0.6, 0.6, 0.6 }

local HEADER = "Completion Navigator"

local function Enabled()
    local settings = CN.Settings()

    return settings and settings.tooltips ~= false
end

Tooltips.Enabled = Enabled

------------------------------------------------------------
-- LINE BUILDERS
------------------------------------------------------------

local function Add(lines, text, color)
    table.insert(lines, { text = text, color = color or GREY })
end

local function CollectedLine(lines, label, collected)
    if collected then
        Add(lines, label .. ": collected", GREEN)
    else
        Add(lines, label .. ": not collected", RED)
    end
end

-- Toys are keyed by item ID in both the toy box and our own store, so this is
-- the one collection lookup that needs no translation.
local function ToyLines(lines, itemID)
    local record = CN.Account("toys")[itemID]

    if record then
        CollectedLine(lines, "Toy", record.collected)
        return true
    end

    -- No scan yet, but the client can still answer for this one item.
    if PlayerHasToy and C_ToyBox and C_ToyBox.GetToyInfo then
        local _, name = C_ToyBox.GetToyInfo(itemID)

        if name then
            CollectedLine(lines, "Toy", PlayerHasToy(itemID))
            return true
        end
    end

    return false
end

local function MountLines(lines, itemID)
    local mountID = Blizzard.GetMountFromItem(itemID)

    if not mountID then
        return false
    end

    local record = CN.Account("mounts")[mountID]

    if record then
        CollectedLine(lines, "Mount", record.collected)

        if record.isFactionSpecific and record.faction then
            Add(lines, "Faction-locked", YELLOW)
        end

        return true
    end

    local mount = Blizzard.GetMountByID(mountID)

    if mount then
        CollectedLine(lines, "Mount", mount.isCollected)
        return true
    end

    return false
end

local function PetLines(lines, itemID)
    local speciesID = Blizzard.GetPetSpeciesFromItem(itemID)

    if not speciesID then
        return false
    end

    local record = CN.Account("pets")[speciesID]

    local count, limit

    if record then
        count, limit = record.count, record.limit
    else
        count, limit = Blizzard.GetPetCollectedCount(speciesID)
    end

    count = count or 0
    limit = limit or 3

    if count > 0 then
        Add(lines, "Battle pet: collected " .. count .. " of " .. limit, GREEN)
    else
        Add(lines, "Battle pet: not collected", RED)
    end

    return true
end

local function AppearanceLines(lines, itemID)
    local has = Blizzard.HasTransmogByItem(itemID)

    if has == nil then
        return false
    end

    if has then
        Add(lines, "Appearance: already known", GREEN)
    else
        Add(lines, "Appearance: not yet known", RED)
    end

    return true
end

-- Recipes are the messy case. The trade skill API keys recipes by recipe ID
-- while a vendor sells an item ID, and the two are not the same number. The
-- ID lookup is tried first because it is exact; the name match is the fallback
-- that actually fires most of the time, and it is reported as a match on name
-- rather than dressed up as certainty.
local function RecipeLines(lines, itemID, itemName)
    local professions = CN:GetModule("Professions")

    if not professions then
        return false
    end

    local names = professions.RecipeNames() or {}
    local mine  = professions.CharacterRecipes() or {}

    local recipeID, matchedOnName

    if names[itemID] then
        recipeID = itemID
    elseif itemName and itemName ~= "" then
        -- "Recipe: Flask of Testing" teaches "Flask of Testing".
        local needle = string.lower(itemName)

        for id, name in pairs(names) do
            if name and name ~= "" then
                local candidate = string.lower(name)

                if candidate == needle or string.find(needle, candidate, 1, true) then
                    recipeID      = id
                    matchedOnName = true
                    break
                end
            end
        end
    end

    if not recipeID then
        return false
    end

    if mine[recipeID] then
        Add(lines, "Recipe: known by this character", GREEN)
    else
        Add(lines, "Recipe: not known by this character", RED)

        local holders = professions.WhoKnows(recipeID) or {}

        if #holders > 0 then
            Add(lines, "Known by: " .. table.concat(holders, ", "), YELLOW)
        end
    end

    if matchedOnName then
        Add(lines, "matched by name", GREY)
    end

    return true
end

local function VendorLines(lines, itemID)
    local vendors = CN:GetModule("Vendors")

    if not vendors then
        return false
    end

    local sellers = vendors.WhoSells(itemID)

    if #sellers == 0 then
        return false
    end

    for index, seller in ipairs(sellers) do
        if index > 3 then
            Add(lines, "and " .. (#sellers - 3) .. " more recorded seller"
                .. ((#sellers - 3) == 1 and "" or "s"), GREY)
            break
        end

        local text = "Sold by " .. tostring(seller.name or seller.npcID)

        if seller.zone then
            text = text .. " in " .. seller.zone
        end

        if seller.x and seller.y then
            text = text .. string.format(" (%.1f, %.1f)", seller.x * 100, seller.y * 100)
        end

        Add(lines, text, YELLOW)
    end

    return true
end

-- The whole item block, as data. Returns an array of { text, color }.
function Tooltips.ItemLines(itemID, itemName)
    local lines = {}

    if not itemID or not CN.db then
        return lines
    end

    itemName = itemName or Blizzard.GetItemName(itemID)

    local collectible = false

    collectible = ToyLines(lines, itemID)         or collectible
    collectible = MountLines(lines, itemID)       or collectible
    collectible = PetLines(lines, itemID)         or collectible
    collectible = RecipeLines(lines, itemID, itemName) or collectible

    -- Appearance state is noise on something that is not gear, so it is only
    -- consulted when nothing else claimed the item.
    if not collectible then
        AppearanceLines(lines, itemID)
    end

    VendorLines(lines, itemID)

    return lines
end

-- Unit tooltips answer a narrower question: have I shopped here, and is this
-- creature one the addon is tracking as a rare.
function Tooltips.UnitLines(npcID)
    local lines = {}

    if not npcID or not CN.db then
        return lines
    end

    local vendors = CN:GetModule("Vendors")

    if vendors then
        local record = vendors.Store()[npcID]

        if record then
            Add(lines, "Recorded vendor: " .. (record.itemCount or 0) .. " items", YELLOW)

            if not record.mapID then
                Add(lines, "no coordinates recorded yet", GREY)
            end
        end
    end

    -- The rare database is keyed by vignette ID, not creature ID, so there is
    -- deliberately nothing to say here about rares. Adding a guess would be
    -- worse than the silence.

    return lines
end

------------------------------------------------------------
-- RENDERING
------------------------------------------------------------

function Tooltips.Render(tooltip, lines)
    if not tooltip or not tooltip.AddLine or #lines == 0 then
        return 0
    end

    tooltip:AddLine(" ")
    tooltip:AddLine(HEADER, 0.2, 1.0, 0.6)

    for _, line in ipairs(lines) do
        tooltip:AddLine(line.text, line.color[1], line.color[2], line.color[3])
    end

    if tooltip.Show then
        tooltip:Show()
    end

    return #lines
end

------------------------------------------------------------
-- HOOKS
------------------------------------------------------------

-- Which tooltip API resolved, reported by /cn tooltips so a silent hook is
-- diagnosable rather than mysterious.
Tooltips.backend = "none"

local function OnItemTooltip(tooltip, itemID, itemName)
    if not Enabled() then
        return
    end

    local ok, err = pcall(function()
        Tooltips.Render(tooltip, Tooltips.ItemLines(itemID, itemName))
    end)

    if not ok then
        DebugPrint("Item tooltip failed: " .. tostring(err))
    end
end

local function OnUnitTooltip(tooltip, unit)
    if not Enabled() then
        return
    end

    local ok, err = pcall(function()
        local npcID = Blizzard.GetUnitNPCID(unit or "mouseover")

        Tooltips.Render(tooltip, Tooltips.UnitLines(npcID))
    end)

    if not ok then
        DebugPrint("Unit tooltip failed: " .. tostring(err))
    end
end

Tooltips.OnItemTooltip = OnItemTooltip
Tooltips.OnUnitTooltip = OnUnitTooltip

function Tooltips.Install()
    if Tooltips.installed then
        return Tooltips.backend
    end

    -- Modern retail: every tooltip is data-driven and post-processed. Post
    -- calls run after the tooltip is rebuilt, so lines are added once per
    -- render rather than accumulating.
    if TooltipDataProcessor
        and TooltipDataProcessor.AddTooltipPostCall
        and Enum and Enum.TooltipDataType then

        TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item,
            function(tooltip, data)
                local itemID, itemName

                if data then
                    itemID = data.id
                end

                if TooltipUtil and TooltipUtil.GetDisplayedItem then
                    local name, _, id = TooltipUtil.GetDisplayedItem(tooltip)

                    itemName = name
                    itemID   = itemID or id
                end

                OnItemTooltip(tooltip, itemID, itemName)
            end)

        TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Unit,
            function(tooltip, data)
                local unit

                if TooltipUtil and TooltipUtil.GetDisplayedUnit then
                    unit = select(2, TooltipUtil.GetDisplayedUnit(tooltip))
                end

                OnUnitTooltip(tooltip, unit)
            end)

        Tooltips.installed = true
        Tooltips.backend   = "TooltipDataProcessor"

        return Tooltips.backend
    end

    -- Older clients. Kept because the addon is expected to load on more than
    -- one flavour, and a missing hook here is silent otherwise.
    if GameTooltip and GameTooltip.HookScript then
        GameTooltip:HookScript("OnTooltipSetItem", function(self)
            local name, link = self:GetItem()

            local itemID = link and tonumber(link:match("item:(%d+)"))

            OnItemTooltip(self, itemID, name)
        end)

        GameTooltip:HookScript("OnTooltipSetUnit", function(self)
            local _, unit = self:GetUnit()

            OnUnitTooltip(self, unit)
        end)

        Tooltips.installed = true
        Tooltips.backend   = "OnTooltipSet"

        return Tooltips.backend
    end

    Tooltips.backend = "none"

    return Tooltips.backend
end

CN:OnLogin(function()
    Tooltips.Install()

    DebugPrint("Tooltip backend: " .. tostring(Tooltips.backend))
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "tooltips",
    args    = "[on or off]",
    order   = 82,
    help    = "Toggle addon lines on item and unit tooltips.",
    handler = function(args)
        local settings = CN.Settings()

        args = string.lower(CN.Trim(args))

        if args == "on" then
            settings.tooltips = true
        elseif args == "off" then
            settings.tooltips = false
        elseif args ~= "" then
            Print("Usage: /cn tooltips [on or off]")
            return
        else
            -- Default is on, so nil counts as enabled.
            settings.tooltips = (settings.tooltips == false)
        end

        Print("Tooltip lines: " .. CN.YesNo(settings.tooltips ~= false))
        Print("|cff999999Backend: " .. tostring(Tooltips.backend) .. "|r")

        if Tooltips.backend == "none" then
            Print("|cff999999No tooltip API resolved, so nothing will be added.|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Setup.lua'] = @'
-- Modules/Setup.lua
-- Completion Navigator :: the first five minutes.
--
-- Every recommendation this addon makes is only as good as what it has
-- scanned, and until now a new install had to discover eleven separate scan
-- commands to get there. Worse, it looked broken in the meantime: an empty
-- database and a confident "nothing actionable is known yet" read as a bug
-- rather than as a first run.
--
-- /cn setup runs every scan in order, one per frame, and then reports what
-- the client genuinely could not answer -- recipes and vendors, which are
-- readable only while their windows are open, and so can never be batched.

local ADDON_NAME, CN = ...

local Setup = CN:RegisterModule("Setup")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- STEPS
------------------------------------------------------------

-- Ordered so the cheap scans report first and the journal scans -- which
-- open and filter collection UIs -- come last.
Setup.steps = {
    { key = "reputations", label = "Reputations", module = "Reputations", fn = "Scan" },
    { key = "currencies",  label = "Currencies",  module = "Currencies",  fn = "Scan" },
    { key = "titles",      label = "Titles",      module = "Titles",      fn = "Scan" },
    { key = "professions", label = "Professions", module = "Professions", fn = "Scan" },
    { key = "exploration", label = "Exploration", module = "Exploration", fn = "Scan" },
    { key = "quests",      label = "Quests",      module = "Quests",      fn = "ScanKnown" },
    { key = "achievements",label = "Achievements",module = "Achievements",fn = "Scan" },
    { key = "toys",        label = "Toys",        module = "Toys",        fn = "Scan" },
    { key = "mounts",      label = "Mounts",      module = "Mounts",      fn = "Scan" },
    { key = "pets",        label = "Battle pets", module = "Pets",        fn = "Scan" },
    { key = "appearances", label = "Appearances", module = "Appearances", fn = "Scan" },
}

function Setup.RunStep(step)
    local module = CN:GetModule(step.module)

    if not module or type(module[step.fn]) ~= "function" then
        return false, "module not loaded"
    end

    local ok, first = pcall(module[step.fn])

    if not ok then
        return false, tostring(first)
    end

    return true, first
end

------------------------------------------------------------
-- RUN
------------------------------------------------------------

Setup.running = false

-- Spreading the steps across frames matters: several of these walk the entire
-- pet journal or achievement tree, and doing all eleven inside one frame is a
-- visible stutter on a login that is already busy.
function Setup.Run(onComplete)
    if Setup.running then
        Print("Setup is already running.")
        return false
    end

    Setup.running = true

    local results = {}
    local index   = 0

    local function step()
        index = index + 1

        local entry = Setup.steps[index]

        if not entry then
            Setup.running = false

            CN.Account("setup").completedAt = time()

            Setup.Report(results)

            if onComplete then
                pcall(onComplete, results)
            end

            return
        end

        local ok, value = Setup.RunStep(entry)

        table.insert(results, {
            label = entry.label,
            ok    = ok,
            value = ok and value or nil,
            error = (not ok) and value or nil,
        })

        if C_Timer and C_Timer.After then
            C_Timer.After(0, step)
        else
            step()
        end
    end

    Print("Running setup: " .. #Setup.steps .. " scans.")

    step()

    return true
end

function Setup.Report(results)
    local scanned, failed = 0, 0

    for _, result in ipairs(results) do
        if result.ok then
            scanned = scanned + 1

            Print("  " .. result.label .. ": "
                .. (type(result.value) == "number" and result.value or "done"))
        else
            failed = failed + 1

            Print("  " .. result.label .. ": |cffff4444" .. tostring(result.error) .. "|r")
        end
    end

    Print("Setup complete: " .. scanned .. " scanned"
        .. (failed > 0 and (", " .. failed .. " unavailable") or "") .. ".")

    for _, line in ipairs(Setup.Outstanding()) do
        Print("|cffffff00" .. line .. "|r")
    end

    Print("Now try |cffffff00/cn next|r.")
end

------------------------------------------------------------
-- WHAT SETUP CANNOT DO
------------------------------------------------------------

-- Two subsystems are readable only while their window is open. Saying so is
-- the difference between "this addon does not track recipes" and "open your
-- profession window once".
function Setup.Outstanding()
    local lines = {}

    local professions = CN:GetModule("Professions")

    if professions and professions.AwaitingRecipeCapture then
        local awaiting = professions.AwaitingRecipeCapture()

        if awaiting and #awaiting > 0 then
            local names = {}

            for _, entry in ipairs(awaiting) do
                table.insert(names, tostring(entry))
            end

            table.insert(lines, "Open each profession window once to record recipes: "
                .. table.concat(names, ", "))
        end
    end

    local vendors = CN:GetModule("Vendors")

    if vendors then
        local counts = vendors.Summary()

        if counts.vendors == 0 then
            table.insert(lines,
                "No vendors recorded yet; they are captured as you open merchant windows.")
        end
    end

    return lines
end

function Setup.HasRun()
    local record = CN.Account("setup")

    return (record and record.completedAt) and true or false
end

------------------------------------------------------------
-- FIRST-RUN PROMPT
------------------------------------------------------------

-- Prompt, never act. Running eleven scans uninvited on someone's login is the
-- same discourtesy as seizing their waypoint.
CN:OnLogin(function()
    if Setup.HasRun() then
        return
    end

    local account = CN.Account("setup")

    if account.prompted then
        return
    end

    account.prompted = time()

    if C_Timer and C_Timer.After then
        C_Timer.After(8, function()
            if not Setup.HasRun() then
                Print("First run: type |cffffff00/cn setup|r to scan everything once.")
            end
        end)
    else
        Print("First run: type |cffffff00/cn setup|r to scan everything once.")
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "setup",
    aliases = { "scanall" },
    order   = 5,
    help    = "Scan every subsystem once. Run this first.",
    handler = function()
        Setup.Run()
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Goals.lua'] = @'
-- Modules/Goals.lua
-- Completion Navigator :: what you are actually working toward.
--
-- Everything else in this addon answers "what should I do next?" from the
-- whole field of what is available. That is the right default, and it is the
-- wrong answer when you have decided you want one specific thing.
--
-- A goal is a target you pin. Once pinned:
--
--   * it becomes a candidate in its own right, even when nothing else would
--     have surfaced it -- an uncollected mount is not normally actionable,
--     but if you have decided you want it, it is;
--   * anything that plausibly leads to it is weighted up, and says so;
--   * /cn goal prints what is actually known about getting it -- the source,
--     where it is, which of your characters is best placed, and what the
--     next concrete step is.
--
-- Goals are account-wide. Deciding you want a mount is not a fact about the
-- character you happened to be playing when you decided it.

local ADDON_NAME, CN = ...

local Goals = CN:RegisterModule("Goals")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("goals")
end

Goals.Store = Store

-- How many goals are worth having at once. Beyond a handful, "goal" stops
-- meaning anything and the weighting stops discriminating.
Goals.limit = 10

------------------------------------------------------------
-- TYPES
------------------------------------------------------------

-- Which objective types can be pinned, and what the user types for each.
Goals.types = {
    quest       = CN.objectiveTypes.QUEST,
    achievement = CN.objectiveTypes.ACHIEVEMENT,
    mount       = CN.objectiveTypes.MOUNT,
    pet         = CN.objectiveTypes.PET,
    toy         = CN.objectiveTypes.TOY,
    recipe      = CN.objectiveTypes.RECIPE,
    title       = CN.objectiveTypes.TITLE,
    rep         = CN.objectiveTypes.REPUTATION,
    reputation  = CN.objectiveTypes.REPUTATION,
    rare        = CN.objectiveTypes.RARE,
    currency    = CN.objectiveTypes.CURRENCY,
}

local function ResolveType(text)
    if not text then
        return nil
    end

    return Goals.types[string.lower(text)]
end

Goals.ResolveType = ResolveType

Goals.ResolveType = ResolveType

local function Key(objectiveType, id)
    return CN.ObjectiveKey(objectiveType, id)
end

------------------------------------------------------------
-- MANAGING GOALS
------------------------------------------------------------

function Goals.IsGoal(objectiveType, id)
    if not objectiveType or not id then
        return false
    end

    local store = Store()

    if not store or next(store) == nil then
        return false
    end

    return store[Key(objectiveType, id)] ~= nil
end

function Goals.Add(objectiveType, id)
    if not objectiveType or not id then
        return false, "A goal needs a type and an ID."
    end

    local store = Store()

    local key = Key(objectiveType, id)

    if store[key] then
        return false, "That is already a goal."
    end

    if CN.CountKeys(store) >= Goals.limit then
        return false, "You already have " .. Goals.limit
            .. " goals. Clear one first."
    end

    local filters = CN:GetModule("Filters")

    local name = filters and filters.DescribeObjective(objectiveType, id)
        or (objectiveType .. " " .. tostring(id))

    store[key] = {
        type  = objectiveType,
        id    = id,
        name  = name,
        since = time(),
    }

    -- A goal changes the weight of everything, and objectives are decorated
    -- when their provider builds them. Force a full rebuild so the new
    -- weighting takes effect immediately rather than whenever something
    -- happens to go stale.
    CN.InvalidateCandidates()

    return true, name
end

function Goals.Remove(objectiveType, id)
    local store = Store()

    local key = Key(objectiveType, id)

    if not store[key] then
        return false
    end

    local name = store[key].name

    store[key] = nil

    CN.InvalidateCandidates()

    return true, name
end

function Goals.Clear()
    local store = Store()

    local count = CN.CountKeys(store)

    for key in pairs(store) do
        store[key] = nil
    end

    CN.InvalidateCandidates()

    return count
end

-- Ordered oldest first, so the list is stable and numbering means something
-- between calls.
function Goals.List()
    local list = {}

    for key, goal in pairs(Store()) do
        table.insert(list, {
            key   = key,
            type  = goal.type,
            id    = goal.id,
            name  = goal.name,
            since = goal.since or 0,
        })
    end

    table.sort(list, function(a, b)
        if a.since ~= b.since then
            return a.since < b.since
        end

        return tostring(a.key) < tostring(b.key)
    end)

    return list
end

------------------------------------------------------------
-- WHAT IS KNOWN ABOUT GETTING IT
------------------------------------------------------------

-- Everything the addon can say about how to obtain one goal. Deliberately
-- honest: where nothing is known, it says so and names what would make it
-- knowable, rather than inventing a route.
--
-- Returns a table:
--   name, source, mapID, x, y, zone, steps (array of strings),
--   done (boolean), character (string or nil)
function Goals.Plan(goal)
    local plan = {
        name  = goal.name,
        steps = {},
    }

    local types = CN.objectiveTypes

    local function step(text)
        table.insert(plan.steps, text)
    end

    ------------------------------------------------------------
    -- Is it already done?
    ------------------------------------------------------------

    local state, reason = CN.Explain(goal.type, goal.id)

    if state == CN.objectiveStates.COMPLETED then
        plan.done = true

        step(reason or "Already complete.")

        return plan
    end

    ------------------------------------------------------------
    -- Where is it?
    ------------------------------------------------------------

    if goal.type == types.QUEST then
        local quests = CN:GetModule("Quests")

        if quests then
            local mapID, x, y, source = quests.GetLocation(goal.id)

            plan.mapID, plan.x, plan.y = mapID, x, y
            plan.source = source

            if mapID then
                plan.zone = Blizzard.GetMapName(mapID)
            end
        end

        if state == CN.objectiveStates.LOCKED and reason then
            step(reason)
        end
    end

    if goal.type == types.MOUNT then
        local record = CN.Account("mounts")[goal.id]

        if record then
            plan.source = record.source

            if record.isFactionSpecific then
                step("Faction-locked. Only obtainable on one faction.")
            end
        end
    end

    if goal.type == types.PET then
        local record = CN.Account("pets")[goal.id]

        if record and record.isWild then
            step("Wild pet: find and capture it in the world.")
        end
    end

    if goal.type == types.RECIPE then
        local vendors = CN:GetModule("Vendors")

        if vendors then
            local seller = vendors.FirstLocatedSeller(goal.id)

            if seller then
                plan.source = "Sold by " .. tostring(seller.name)
                plan.mapID, plan.x, plan.y = seller.mapID, seller.x, seller.y
                plan.zone = seller.zone

                step("Buy it from " .. tostring(seller.name)
                    .. (seller.zone and (" in " .. seller.zone) or "") .. ".")
            else
                step("No recorded vendor sells this. Open merchants to record them.")
            end
        end
    end

    if goal.type == types.RARE or goal.type == types.TREASURE then
        local record = CN.Account("rares")[goal.id]

        if record then
            plan.mapID, plan.x, plan.y = record.mapID, record.x, record.y
            plan.zone = record.zone

            step("Seen " .. (record.sightings or 1) .. " time"
                .. ((record.sightings or 1) == 1 and "" or "s") .. " here.")
        end
    end

    if goal.type == types.ACHIEVEMENT then
        local record = CN.Account("achievements")[goal.id]

        if record and record.criteria then
            local remaining = (record.criteria or 0) - (record.done or 0)

            step(remaining .. " of " .. record.criteria .. " criteria left.")

            for _, criterion in ipairs(Blizzard.GetIncompleteCriteria(goal.id, 5) or {}) do
                step("Missing: " .. criterion)
            end
        end
    end

    if goal.type == types.REPUTATION then
        local record = CN.Account("reputations")[goal.id]

        if record then
            if record.accountWide then
                step("Account-wide: any character's progress counts.")
            else
                step("Character-specific: progress does not carry across your Warband.")
            end
        end
    end

    ------------------------------------------------------------
    -- Who should do it?
    ------------------------------------------------------------

    local warband = CN:GetModule("Warband")

    if warband then
        local ok, best, _, why = pcall(warband.WhoShould, goal.type, goal.id)

        if ok and best then
            plan.character = best

            step("Best character: " .. tostring(best)
                .. (why and (" (" .. why .. ")") or ""))
        end
    end

    ------------------------------------------------------------
    -- Fall back to honesty.
    ------------------------------------------------------------

    if plan.mapID and plan.x and plan.y then
        step("Location known: " .. (plan.zone or ("map " .. plan.mapID))
            .. string.format(" (%.1f, %.1f)", plan.x * 100, plan.y * 100))
    elseif #plan.steps == 0 then
        step("Nothing is known about how to obtain this yet.")
        step("The addon learns sources from play: open vendors, scan "
            .. "collections, and travel.")
    end

    return plan
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A goal is actionable by definition. Most goals would never surface on their
-- own -- an uncollected mount is not a next action for most people -- which is
-- exactly the point of having said you want it.
CN.RegisterCandidateProvider("Goals", function()
    local candidates = {}

    for _, goal in ipairs(Goals.List()) do
        if not CN.IsIgnored(goal.type, goal.id)
            and not CN.IsDeferred(goal.type, goal.id) then

            local plan = Goals.Plan(goal)

            if not plan.done then
                local reasons = { "you set this as a goal" }

                if plan.source then
                    table.insert(reasons, plan.source)
                end

                local travel

                if plan.mapID then
                    local playerMap = select(1, CN.GetPlayerPosition())

                    travel = (plan.mapID == playerMap) and 2 or 25
                end

                table.insert(candidates, CN.NewObjective({
                    id              = goal.id,
                    type            = goal.type,
                    name            = goal.name,
                    mapID           = plan.mapID,
                    x               = plan.x,
                    y               = plan.y,
                    zone            = plan.zone,
                    accountWide     = true,
                    completionValue = 6,
                    travelCost      = travel,
                    isGoal          = true,
                    reasons         = reasons,
                }))
            end
        end
    end

    return candidates
end, { events = { "ZONE_CHANGED_NEW_AREA" }, cooldown = 2 })

------------------------------------------------------------
-- WEIGHTING
------------------------------------------------------------

-- Anything that leads to a goal is worth more than it would be otherwise.
-- "Leads to" is deliberately narrow -- three relationships the addon can
-- actually establish, rather than a guess dressed up as a plan.
function Goals.Decorate(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return objective
    end

    local store = Store()

    if not store or next(store) == nil then
        return objective
    end

    -- 1. It IS a goal.
    if Goals.IsGoal(objective.type, objective.id) then
        objective.userPreference = (objective.userPreference or 0) + 8

        if not objective.isGoal then
            objective.isGoal  = true
            objective.reasons = objective.reasons or {}
            table.insert(objective.reasons, "this is one of your goals")
        end

        return objective
    end

    -- 2. It unlocks a goal, per the dependency graph.
    if objective.type == CN.objectiveTypes.QUEST then
        local dependency = CN.GetDependency(CN.ObjectiveKey(objective.type, objective.id))

        if dependency and dependency.unlocks then
            for _, unlocked in ipairs(dependency.unlocks) do
                -- Dependency edges are stored as keys, but static data writes
                -- plain quest IDs. Accept both.
                local unlockedID = tonumber(unlocked)
                    or tonumber(tostring(unlocked):match(":(%d+)$"))

                if unlockedID and Goals.IsGoal(CN.objectiveTypes.QUEST, unlockedID) then
                    objective.userPreference = (objective.userPreference or 0) + 5
                    objective.reasons = objective.reasons or {}
                    table.insert(objective.reasons, "unlocks a goal")

                    return objective
                end
            end
        end
    end

    -- 3. It is in the same zone as a located goal. Weak, and weighted weakly:
    --    being in the right place is worth something, but it is not progress.
    if objective.mapID then
        for _, goal in ipairs(Goals.List()) do
            local plan = Goals.Plan(goal)

            if plan.mapID == objective.mapID and not plan.done then
                objective.userPreference = (objective.userPreference or 0) + 2
                objective.reasons = objective.reasons or {}
                table.insert(objective.reasons, "in the same zone as a goal")

                return objective
            end
        end
    end

    return objective
end

CN.RegisterCandidateDecorator("Goals", Goals.Decorate)

------------------------------------------------------------
-- OUTPUT
------------------------------------------------------------

local function PrintPlan(index, goal)
    local plan = Goals.Plan(goal)

    Print(index .. ". |cffffff00" .. tostring(plan.name) .. "|r"
        .. " |cff999999(" .. tostring(goal.type) .. " " .. tostring(goal.id) .. ")|r"
        .. (plan.done and " |cff00ff00done|r" or ""))

    if plan.source then
        Print("   Source: " .. tostring(plan.source))
    end

    for _, step in ipairs(plan.steps) do
        Print("   - " .. step)
    end

    if plan.character then
        Print("   Best character: |cffffff00" .. tostring(plan.character) .. "|r")
    end

    if plan.mapID and plan.x and plan.y then
        Print("   |cffffff00/cn gogoal " .. index .. "|r to set a waypoint.")
    end
end

Goals.PrintPlan = PrintPlan

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "goal",
    args    = "<type> <id>",
    order   = 12,
    help    = "Pin something as a goal. Types: quest, achievement, mount, pet, toy, recipe, title, rep, rare, currency.",
    handler = function(args)
        local typeText, idText = string.match(CN.Trim(args or ""), "^(%S+)%s+(%S+)$")

        if not typeText then
            Print("Usage: /cn goal <type> <id>")
            Print("|cff999999Types: quest, achievement, mount, pet, toy, recipe, "
                .. "title, rep, rare, currency|r")
            Print("|cffffff00/cn goals|r lists what you have pinned.")
            return
        end

        local objectiveType = ResolveType(typeText)

        if not objectiveType then
            Print("Not a goal type: " .. typeText)
            Print("|cff999999Types: quest, achievement, mount, pet, toy, recipe, "
                .. "title, rep, rare, currency|r")
            return
        end

        local id = CN.ToID(idText)

        if not id then
            Print("Not an ID: " .. idText)
            return
        end

        local added, message = Goals.Add(objectiveType, id)

        if not added then
            Print(message)
            return
        end

        Print("Goal set: |cffffff00" .. tostring(message) .. "|r")
        Print("|cff999999See the path with |cffffff00/cn chase " .. typeText
            .. " " .. idText .. "|r")

        local list = Goals.List()

        for index, goal in ipairs(list) do
            if goal.type == objectiveType and goal.id == id then
                PrintPlan(index, goal)
                break
            end
        end
    end,
}

CN:RegisterCommand{
    name    = "goals",
    order   = 13,
    help    = "List your goals and what is known about reaching them.",
    handler = function()
        local list = Goals.List()

        if #list == 0 then
            Print("No goals set.")
            Print("|cffffff00/cn goal mount 1234|r pins something to work toward.")
            Print("|cff999999A goal becomes actionable even when nothing else "
                .. "would have surfaced it, and anything leading to it ranks higher.|r")
            return
        end

        Print("Goals (" .. #list .. " of " .. Goals.limit .. "):")

        for index, goal in ipairs(list) do
            PrintPlan(index, goal)
        end
    end,
}

CN:RegisterCommand{
    name    = "ungoal",
    args    = "<number or all>",
    order   = 14,
    help    = "Remove a goal.",
    handler = function(args)
        args = CN.Trim(args or "")

        if string.lower(args) == "all" then
            local count = Goals.Clear()

            Print("Cleared " .. count .. " goal" .. (count == 1 and "" or "s") .. ".")
            return
        end

        local index = CN.ToID(args)

        local list = Goals.List()

        if not index or not list[index] then
            Print("Usage: /cn ungoal <number or all>")

            if #list > 0 then
                Print("|cff999999Numbers come from |cffffff00/cn goals|r.|r")
            end

            return
        end

        local goal = list[index]

        local removed, name = Goals.Remove(goal.type, goal.id)

        if removed then
            Print("Goal removed: " .. tostring(name))
        end
    end,
}

CN:RegisterCommand{
    name    = "gogoal",
    args    = "<number>",
    order   = 15,
    help    = "Navigate to a goal.",
    handler = function(args)
        local index = CN.ToID(CN.Trim(args or ""))

        local list = Goals.List()

        if not index or not list[index] then
            Print("Usage: /cn gogoal <number>")
            return
        end

        local goal = list[index]
        local plan = Goals.Plan(goal)

        if not (plan.mapID and plan.x and plan.y) then
            Print("No location is known for " .. tostring(plan.name) .. ".")

            for _, step in ipairs(plan.steps) do
                Print("  - " .. step)
            end

            return
        end

        CN.NavigateToObjective({
            id    = goal.id,
            type  = goal.type,
            name  = plan.name,
            mapID = plan.mapID,
            x     = plan.x,
            y     = plan.y,
        })
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Chase.lua'] = @'
-- Modules/Chase.lua
-- Completion Navigator :: what stands between you and the thing you want.
--
-- `/cn goal` has always been able to say "I want that" and re-weight the
-- list accordingly. What it could never say is what the PATH is. A player
-- chasing a mount got a line saying the mount was a goal, and nothing about
-- which four things had to happen first, how many of them were already done,
-- or which one to go and do now.
--
-- This is that path. Chase turns a goal into an ordered chain of steps, each
-- one carrying a state -- done, next, blocked, or simply outstanding -- and,
-- where the game will tell us, a real count.
--
-- ON NUMBERS. The addon's standing rule is that it does not invent a
-- denominator. That rule is doing real work here, because a progress bar is
-- exactly the kind of thing that begs to be faked. So:
--
--   * Achievement criteria, appearance sources, and reputation standing have
--     denominators the client vouches for. Those get a fraction.
--   * A mount whose source is a sentence of English does not. It gets the
--     sentence, and no bar.
--
-- Showing "1 of 1 steps" for something we know nothing about would be a lie
-- told in a font that looks like a fact.

local ADDON_NAME, CN = ...

local Chase = CN:RegisterModule("Chase")

local Print = CN.Print

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- STEP STATES
------------------------------------------------------------

-- Ordered by how much the player needs to look at them.
Chase.states = {
    NEXT    = "NEXT",     -- go and do this one
    TODO    = "TODO",     -- outstanding, but not the immediate move
    BLOCKED = "BLOCKED",  -- cannot be done yet, and we know why
    DONE    = "DONE",     -- already behind you
    NOTE    = "NOTE",     -- context, not a step
}

Chase.stateLabels = {
    NEXT    = "next",
    TODO    = "to do",
    BLOCKED = "blocked",
    DONE    = "done",
    NOTE    = "",
}

Chase.stateColors = {
    NEXT    = { 0.365, 0.824, 0.984 },
    TODO    = { 0.85, 0.85, 0.85 },
    BLOCKED = { 0.96, 0.42, 0.38 },
    DONE    = { 0.45, 0.72, 0.45 },
    NOTE    = { 0.6, 0.6, 0.6 },
}

local function NewStep(state, text, extra)
    local step = extra or {}

    step.state = state
    step.text  = text

    return step
end

------------------------------------------------------------
-- PER-TYPE CHAINS
------------------------------------------------------------

-- Each builder returns steps and, optionally, a progress table:
--   { done = n, total = m, unit = "criteria" }
--
-- Returning no progress table is a positive statement -- "the game does not
-- give me a trustworthy count here" -- not an oversight.

local builders = {}

builders.ACHIEVEMENT = function(goal)
    local steps = {}

    local criteria = Blizzard.GetAchievementCriteriaList(goal.id, 25) or {}

    if #criteria == 0 then
        return steps, nil
    end

    local done = 0
    local first = true

    for _, criterion in ipairs(criteria) do
        local text = criterion.description

        -- Some criteria carry their own counter. Where they do, it is the
        -- most useful thing on the line.
        if criterion.required and criterion.required > 1 and criterion.quantity then
            text = string.format("%s (%d/%d)",
                text, criterion.quantity, criterion.required)
        end

        if criterion.completed then
            done = done + 1

            table.insert(steps, NewStep(Chase.states.DONE, text))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, text))
        end
    end

    return steps, { done = done, total = #criteria, unit = "criteria" }
end

builders.REPUTATION = function(goal)
    local steps = {}

    local standing = Blizzard.GetReputationRemaining(goal.id)

    if not standing then
        return steps, nil
    end

    if Blizzard.IsAccountWideReputation(goal.id) then
        table.insert(steps, NewStep(Chase.states.NOTE,
            "Account-wide: any character's progress counts."))
    else
        table.insert(steps, NewStep(Chase.states.NOTE,
            "Character-specific: progress does not carry across your Warband."))
    end

    table.insert(steps, NewStep(Chase.states.NEXT, string.format(
        "%s reputation to the next rank", CN.Comma(standing.remaining))))

    return steps, {
        done  = standing.earned,
        total = standing.needed,
        unit  = "reputation",
    }
end

builders.APPEARANCE = function(goal)
    local steps = {}

    local sources = Blizzard.GetAppearanceSources(goal.id) or {}

    if #sources == 0 then
        return steps, nil
    end

    local collected = 0
    local first = true

    for _, source in ipairs(sources) do
        local name = source.name or ("item " .. tostring(source.itemID or "?"))

        if source.collected then
            collected = collected + 1

            table.insert(steps, NewStep(Chase.states.DONE, name))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, name, { itemID = source.itemID }))
        end
    end

    -- An appearance needs ONE of its sources, not all of them, so the count
    -- is deliberately not offered as progress toward the appearance. Saying
    -- "1 of 9" would suggest eight more to go when in fact you are finished.
    table.insert(steps, 1, NewStep(Chase.states.NOTE,
        collected > 0
            and "Collected. Any one source is enough."
            or string.format("Any ONE of these %d sources unlocks it.", #sources)))

    return steps, nil
end

builders.QUEST = function(goal)
    local steps = {}

    local dependencies = CN.GetPrerequisites and CN.GetPrerequisites(goal.id)

    if type(dependencies) ~= "table" or #dependencies == 0 then
        return steps, nil
    end

    local done = 0
    local first = true

    for _, questID in ipairs(dependencies) do
        local name = Blizzard.GetQuestTitle(questID, true)
            or ("Quest " .. tostring(questID))

        if CN.IsQuestComplete and CN.IsQuestComplete(questID) then
            done = done + 1

            table.insert(steps, NewStep(Chase.states.DONE, name,
                { objectiveType = CN.objectiveTypes.QUEST, objectiveID = questID }))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, name,
                { objectiveType = CN.objectiveTypes.QUEST, objectiveID = questID }))
        end
    end

    return steps, { done = done, total = #dependencies, unit = "prerequisites" }
end

Chase.builders = builders

------------------------------------------------------------
-- THE CHAIN
------------------------------------------------------------

-- The full picture for one goal: where it is, what remains, how far along
-- you are, and which single step to go and do.
function Chase.Chain(goal)
    local chain = {
        name  = goal and goal.name,
        type  = goal and goal.type,
        id    = goal and goal.id,
        steps = {},
    }

    if type(goal) ~= "table" or not goal.type or not goal.id then
        return chain
    end

    local goals = CN:GetModule("Goals")

    -- Location, source and "who should do it" already exist. Reuse them
    -- rather than growing a second, subtly different answer.
    local plan = goals and goals.Plan(goal) or {}

    chain.done      = plan.done
    chain.source    = plan.source
    chain.mapID     = plan.mapID
    chain.x         = plan.x
    chain.y         = plan.y
    chain.zone      = plan.zone
    chain.character = plan.character

    if chain.done then
        table.insert(chain.steps, NewStep(Chase.states.DONE, "Already complete."))

        chain.progress = { done = 1, total = 1, unit = "steps" }

        return chain
    end

    local builder = builders[goal.type]

    if builder then
        local ok, steps, progress = pcall(builder, goal)

        if ok and type(steps) == "table" then
            chain.steps    = steps
            chain.progress = progress
        end
    end

    -- Nothing structured? Fall back to what the existing planner knows, which
    -- is prose rather than a chain -- and say so, rather than dressing a
    -- sentence up as a step.
    if #chain.steps == 0 then
        for _, text in ipairs(plan.steps or {}) do
            table.insert(chain.steps, NewStep(Chase.states.NOTE, text))
        end

        if chain.mapID and chain.x and chain.y then
            table.insert(chain.steps, 1,
                NewStep(Chase.states.NEXT, "Travel to " ..
                    (chain.zone or ("map " .. tostring(chain.mapID))), {
                    mapID = chain.mapID,
                    x     = chain.x,
                    y     = chain.y,
                }))
        end
    end

    chain.next = Chase.NextStep(chain)

    return chain
end

-- The one step to go and do. Nil when everything outstanding is blocked or
-- unknown, which is itself worth saying out loud.
function Chase.NextStep(chain)
    for _, step in ipairs(chain and chain.steps or {}) do
        if step.state == Chase.states.NEXT then
            return step
        end
    end

    for _, step in ipairs(chain and chain.steps or {}) do
        if step.state == Chase.states.TODO then
            return step
        end
    end

    return nil
end

-- A single line for chat: where you are, and what to do about it.
function Chase.Summarize(chain)
    if not chain or not chain.name then
        return "Nothing to chase."
    end

    if chain.done then
        return tostring(chain.name) .. " is complete."
    end

    local parts = {}

    if chain.progress and chain.progress.total and chain.progress.total > 0 then
        table.insert(parts, string.format("%s of %s %s",
            CN.Comma(chain.progress.done or 0),
            CN.Comma(chain.progress.total),
            chain.progress.unit or "steps"))
    end

    local nextStep = chain.next or Chase.NextStep(chain)

    if nextStep then
        table.insert(parts, "next: " .. tostring(nextStep.text))
    elseif #parts == 0 then
        return tostring(chain.name)
            .. " -- the game does not say how this is obtained."
    end

    return tostring(chain.name) .. " -- " .. table.concat(parts, ", ")
end

-- Percent complete, or nil. Nil is a real answer and callers must render it
-- as "unknown" rather than as zero.
function Chase.Fraction(chain)
    local progress = chain and chain.progress

    if not progress or not progress.total or progress.total <= 0 then
        return nil
    end

    local fraction = (progress.done or 0) / progress.total

    if fraction < 0 then return 0 end
    if fraction > 1 then return 1 end

    return fraction
end

-- Every goal, chained, with the least-finished first: the thing you are
-- furthest from is the thing most in need of a plan.
function Chase.All()
    local goals = CN:GetModule("Goals")

    if not goals then
        return {}
    end

    local chains = {}

    for _, goal in ipairs(goals.List()) do
        table.insert(chains, Chase.Chain(goal))
    end

    table.sort(chains, function(a, b)
        local left  = Chase.Fraction(a)
        local right = Chase.Fraction(b)

        -- Finished goals sink. Unmeasurable ones sit between measurable
        -- progress and completion, because "no idea" is more actionable than
        -- "done" and less actionable than "you are 80% there".
        local leftDone  = a.done and 1 or 0
        local rightDone = b.done and 1 or 0

        if leftDone ~= rightDone then
            return leftDone < rightDone
        end

        if left and right then
            return left > right
        end

        if left or right then
            return left ~= nil
        end

        return tostring(a.name) < tostring(b.name)
    end)

    return chains
end

------------------------------------------------------------
-- NAVIGATION
------------------------------------------------------------

-- Go to the next step of a chain, not to the goal itself.
--
-- Those differ, and the difference is the whole point: the mount is in a
-- dungeon you cannot enter yet, but the attunement quest is forty yards away.
function Chase.NavigateNext(chain)
    local step = chain and (chain.next or Chase.NextStep(chain))

    if step and step.objectiveType and step.objectiveID then
        local located = CN.FindCandidate
            and CN.FindCandidate(step.objectiveType, step.objectiveID)

        if located then
            return CN.NavigateToObjective(located)
        end
    end

    if step and step.mapID and step.x and step.y then
        return CN.SetWaypoint(step.mapID, step.x, step.y, step.text)
    end

    if chain and chain.mapID and chain.x and chain.y then
        return CN.SetWaypoint(chain.mapID, chain.x, chain.y, chain.name)
    end

    Print("No location is known for the next step of "
        .. tostring(chain and chain.name or "that goal") .. ".")

    return false
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

local function PrintChain(chain)
    Print(Chase.Summarize(chain))

    local fraction = Chase.Fraction(chain)

    if fraction then
        Print(string.format("  |cff5dd2fb%s|r %d%%",
            CN.ProgressBar and CN.ProgressBar(fraction, 20) or "",
            math.floor(fraction * 100 + 0.5)))
    end

    local shown = 0

    for _, step in ipairs(chain.steps) do
        if shown >= 12 then
            Print("  |cff999999... and " .. (#chain.steps - shown) .. " more|r")
            break
        end

        local label = Chase.stateLabels[step.state] or ""

        local colour = "|cffcccccc"

        if step.state == Chase.states.DONE then
            colour = "|cff73b873"
        elseif step.state == Chase.states.NEXT then
            colour = "|cff5dd2fb"
        elseif step.state == Chase.states.BLOCKED then
            colour = "|cfff56b61"
        elseif step.state == Chase.states.NOTE then
            colour = "|cff999999"
        end

        Print(string.format("  %s%s%s|r",
            colour,
            label ~= "" and ("[" .. label .. "] ") or "",
            step.text))

        shown = shown + 1
    end

    if chain.character then
        Print("  |cff999999Best character: " .. tostring(chain.character) .. "|r")
    end
end

Chase.PrintChain = PrintChain

CN:RegisterCommand{
    name    = "chase",
    aliases = { "chain", "path" },
    args    = "[type id, or nothing for all goals]",
    order   = 16,
    help    = "Show what stands between you and a goal, step by step.",
    handler = function(args)
        args = CN.Trim(args or "")

        local goals = CN:GetModule("Goals")

        if not goals then
            Print("The Goals module is not loaded.")
            return
        end

        if args ~= "" then
            local typeText, idText = string.match(args, "^(%S+)%s+(%S+)$")

            local objectiveType = typeText and goals.ResolveType(typeText)
            local id            = idText and CN.ToID(idText)

            if not objectiveType or not id then
                Print("Usage: |cffffff00/cn chase <type> <id>|r"
                    .. "   e.g. /cn chase mount 1234")
                Print("|cff999999Types: quest, achievement, mount, pet, toy, "
                    .. "recipe, title, rep, rare, currency|r")
                return
            end

            -- Chasing something you have not pinned pins it. Asking for the
            -- path to a thing is the clearest possible statement that you
            -- want it, and making the player run two commands to say so once
            -- is the addon being pedantic at the player's expense.
            if not goals.IsGoal(objectiveType, id) then
                goals.Add(objectiveType, id)
            end

            for _, goal in ipairs(goals.List()) do
                if goal.type == objectiveType and goal.id == id then
                    PrintChain(Chase.Chain(goal))
                    return
                end
            end

            Print("Could not pin that as a goal.")
            return
        end

        local chains = Chase.All()

        if #chains == 0 then
            Print("Nothing pinned. Try |cffffff00/cn chase mount 1234|r, or")
            Print("|cffffff00/cn goal <type> <id>|r to pin something first.")
            return
        end

        for _, chain in ipairs(chains) do
            PrintChain(chain)
        end
    end,
}

return Chase
'@

$Embedded['Modules\Progress.lua'] = @'
-- Modules/Progress.lua
-- Completion Navigator :: how much you have actually done.
--
-- REPORTED FROM LIVE PLAY: "It doesn't show how many quests I've completed
-- anymore, which I kinda liked seeing. But my first weekend, I did 350+
-- quests, so I think I can definitely do even more."
--
-- That is the whole design brief in two sentences, and the second one is the
-- important half. He is not asking for a statistic. He is asking for the
-- thing that made him want to beat his own number -- and 0.26.1 took it away
-- while fixing something else, which is a fair trade only if it comes back
-- better.
--
-- Better means: a number the client will vouch for, rather than a count of
-- rows this addon happened to write. `C_QuestLog.GetAllCompletedQuestIDs`
-- returns every quest this character has ever finished. That is the real
-- lifetime total, it is correct on a fresh install with no scan history, and
-- it does not saturate.
--
-- On top of it, the numbers that make a session feel like progress: what you
-- have done since you logged in, what you have done today, and the rate.
-- Those the addon does have to keep itself, so they are stored per character
-- and reset on the game's own clock rather than on a timer of our invention.

local ADDON_NAME, CN = ...

local Progress = CN:RegisterModule("Progress")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

local function Store()
    local character = CN.character

    if not character then
        return nil
    end

    character.progress = character.progress or {}

    return character.progress
end

Progress.Store = Store

-- Where the session began. Held in memory only: a session is by definition
-- the thing that ends when you log out.
local sessionStart = {
    completed = nil,
    at        = nil,
}

------------------------------------------------------------
-- THE REAL TOTAL
------------------------------------------------------------

-- Lifetime quests completed by this character, straight from the client.
-- Nil, not zero, when the client will not say -- an unknown total and a
-- total of none are different facts.
function Progress.LifetimeCompleted()
    local ids = Blizzard.GetAllCompletedQuestIDs()

    if not ids then
        return nil
    end

    return #ids
end

------------------------------------------------------------
-- DAY BOUNDARIES
------------------------------------------------------------

-- "Today" means the game's day, which turns over at the daily reset rather
-- than at your local midnight. Using local midnight would show a player a
-- number that disagrees with everything else the game tells them.
function Progress.CurrentDayKey()
    local seconds = Blizzard.GetSecondsUntilDailyReset()

    if not seconds then
        return tonumber(date("%Y%m%d"))
    end

    -- The reset that is coming, as an absolute time, identifies the day
    -- unambiguously without needing to know the server's timezone.
    return math.floor((time() + seconds) / 86400)
end

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

-- Called when the client tells us a quest was turned in.
function Progress.NoteCompleted(questID)
    local store = Store()

    if not store then
        return
    end

    local today = Progress.CurrentDayKey()

    if store.dayKey ~= today then
        -- A new day. Keep yesterday so "yesterday you did 84" is possible
        -- later, but do not accumulate an unbounded history.
        store.previousDay      = store.today or 0
        store.previousDayKey   = store.dayKey
        store.today            = 0
        store.dayKey           = today
    end

    store.today   = (store.today or 0) + 1
    store.session = (store.session or 0) + 1
    store.total   = (store.total or 0) + 1

    if (store.best or 0) < store.today then
        store.best    = store.today
        store.bestDay = today
    end

    DebugPrint("Quest " .. tostring(questID) .. " completed; "
        .. store.today .. " today.")
end

function Progress.BeginSession()
    local store = Store()

    if store then
        store.session = 0

        -- Roll the day over at login too, so a player who logs in the next
        -- morning does not see yesterday's number labelled "today".
        local today = Progress.CurrentDayKey()

        if store.dayKey ~= today then
            store.previousDay    = store.today or 0
            store.previousDayKey = store.dayKey
            store.today          = 0
            store.dayKey         = today
        end
    end

    sessionStart.completed = Progress.LifetimeCompleted()
    sessionStart.at        = time()
end

------------------------------------------------------------
-- THE NUMBERS
------------------------------------------------------------

-- Everything worth showing, in one table. Fields are nil rather than zero
-- when the client has not answered, so callers can tell the difference.
function Progress.Summary()
    local store = Store() or {}

    local summary = {
        lifetime = Progress.LifetimeCompleted(),
        today    = store.today or 0,
        session  = store.session or 0,
        best     = store.best or 0,
        previous = store.previousDay,
    }

    -- Prefer the client's own delta for the session where we have it: it
    -- counts quests completed by any means, including ones the addon did not
    -- see an event for.
    if sessionStart.completed and summary.lifetime then
        local delta = summary.lifetime - sessionStart.completed

        if delta >= 0 then
            summary.session = math.max(summary.session, delta)
        end
    end

    if sessionStart.at then
        summary.sessionSeconds = time() - sessionStart.at

        -- A rate needs enough time behind it to mean anything. Five minutes
        -- in, "240 quests per hour" is arithmetic, not information.
        if summary.sessionSeconds >= 600 and summary.session > 0 then
            summary.perHour = summary.session / (summary.sessionSeconds / 3600)
        end
    end

    return summary
end

function Progress.Describe()
    local summary = Progress.Summary()

    local parts = {}

    if summary.lifetime then
        table.insert(parts, CN.Comma(summary.lifetime) .. " quests completed")
    end

    table.insert(parts, summary.today .. " today")

    if summary.session > 0 and summary.session ~= summary.today then
        table.insert(parts, summary.session .. " this session")
    end

    if summary.perHour then
        table.insert(parts, string.format("%.0f/hour", summary.perHour))
    end

    return table.concat(parts, ", ")
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    Progress.NoteCompleted(questID)
end)

CN:OnLogin(function()
    Progress.BeginSession()
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "progress",
    aliases = { "done", "stats" },
    order   = 11,
    help    = "How many quests you have completed: lifetime, today, this session.",
    handler = function()
        local summary = Progress.Summary()

        if summary.lifetime then
            Print("|cffffd100" .. CN.Comma(summary.lifetime)
                .. "|r quests completed on this character.")
        else
            Print("The client will not report a lifetime total right now.")
        end

        Print("Today: |cffffff00" .. summary.today .. "|r"
            .. (summary.best > 0 and ("   |cff999999best day: "
                .. summary.best .. "|r") or ""))

        if summary.session > 0 then
            local line = "This session: |cffffff00" .. summary.session .. "|r"

            if summary.perHour then
                line = line .. string.format(
                    "   |cff999999%.0f per hour|r", summary.perHour)
            end

            Print(line)
        end

        if summary.previous then
            Print("|cff999999Previous day: " .. summary.previous .. "|r")
        end
    end,
}

return Progress
'@

$Embedded['Modules\Loremaster.lua'] = @'
-- Modules/Loremaster.lua
-- Completion Navigator :: finishing zones, continents and expansions.
--
-- FROM A PLAYER'S OWN STATED PLAN:
--
--   "Once I finish the story this weekend, I'm gonna do all the side quests
--    on the continent I'm currently on. Then I'll move from one continent to
--    another. After that, I'm gonna switch timelines and work backwards to
--    the previous expansion... Basically, I'm gonna try to complete every
--    main quest and side quest in the entire game."
--
-- That is a two-year project measured in zones and continents, and the addon
-- had nothing to say about it. It could tell him what to do in the next
-- hundred yards and nothing about where he was in the campaign.
--
-- THE DENOMINATOR PROBLEM, AND WHY THIS WORKS ANYWAY.
--
-- The client will not tell you how many quests exist in a zone. Counting
-- "quests I know about" would produce a denominator that grows as you play,
-- so your percentage would go DOWN as you did more -- which is worse than no
-- percentage at all, and this addon has a standing rule against inventing
-- one.
--
-- But the game already ships the exact tracker this player needs: the quest
-- achievements. "Loremaster of Khaz Algar", the per-zone story achievements,
-- the exploration-style quest counts. Those have criteria the client
-- enumerates and vouches for. So the progress here is real, and it is real
-- because we did not compute it -- we read it.

local ADDON_NAME, CN = ...

local Loremaster = CN:RegisterModule("Loremaster")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local Blizzard = CN.Blizzard

-- Blizzard's "Quests" achievement category. A stable constant for many
-- years, and everything below degrades to "nothing found" rather than to an
-- error if it ever moves.
Loremaster.questCategoryID = 96

------------------------------------------------------------
-- THE CATEGORY TREE
------------------------------------------------------------

-- Every category descending from Quests: one per expansion, and below those,
-- per continent. Walked rather than hardcoded, so a new expansion needs no
-- code.
function Loremaster.QuestCategories()
    local categories = {}

    if not GetCategoryList or not GetCategoryInfo then
        return categories
    end

    local ok, list = pcall(GetCategoryList)

    if not ok or type(list) ~= "table" then
        return categories
    end

    -- Parentage is only one level per lookup, so resolve to a root by
    -- walking upward. Cheap: the tree is three deep at most.
    local function rootOf(categoryID)
        local guard = 0
        local current = categoryID

        while current and guard < 8 do
            local name, parent = GetCategoryInfo(current)

            if not name then
                return nil
            end

            if current == Loremaster.questCategoryID then
                return current
            end

            if not parent or parent <= 0 then
                return nil
            end

            current = parent
            guard   = guard + 1
        end

        return nil
    end

    for _, categoryID in ipairs(list) do
        if rootOf(categoryID) == Loremaster.questCategoryID then
            local name, parent = GetCategoryInfo(categoryID)

            table.insert(categories, {
                categoryID = categoryID,
                name       = name,
                parentID   = parent,
            })
        end
    end

    return categories
end

------------------------------------------------------------
-- SCANNING
------------------------------------------------------------

local function Records()
    return CN.Account("loremaster")
end

Loremaster.Records = Records

-- Reads every quest achievement and stores what the client says about it.
-- Stored rather than recomputed because walking the achievement tree is not
-- something to do on every frame, and because it lets the Warband view show
-- what other characters have finished.
function Loremaster.Scan()
    local store = Records()

    local scanned = 0

    for _, category in ipairs(Loremaster.QuestCategories()) do
        local total = select(1, Blizzard.GetCategoryCounts(category.categoryID))

        for index = 1, (total or 0) do
            local achievement = Blizzard.GetAchievementInCategory(
                category.categoryID, index)

            if achievement and achievement.achievementID then
                local id = achievement.achievementID

                local done, criteria = Blizzard.GetAchievementProgress(id)

                store[id] = {
                    name      = achievement.name,
                    category  = category.name,
                    completed = achievement.completed and true or false,
                    done      = done,
                    criteria  = criteria,
                }

                scanned = scanned + 1
            end
        end
    end

    CN.MarkScanned("loremaster")

    DebugPrint("Loremaster scan: " .. scanned .. " quest achievements.")

    return scanned
end

------------------------------------------------------------
-- GROUPING
------------------------------------------------------------

-- Quest achievements grouped by the category they live in -- which is to say,
-- by expansion and continent, because that is how Blizzard files them and
-- how the player thinks about them.
function Loremaster.ByCategory(includeCompleted)
    local groups, order = {}, {}

    for id, record in pairs(Records()) do
        if includeCompleted or not record.completed then
            local key = record.category or "Other"

            if not groups[key] then
                groups[key] = {}
                table.insert(order, key)
            end

            table.insert(groups[key], {
                id        = id,
                name      = record.name,
                completed = record.completed,
                done      = record.done or 0,
                criteria  = record.criteria or 0,
            })
        end
    end

    table.sort(order)

    for _, key in pairs(order) do
        table.sort(groups[key], function(a, b)
            local left  = (a.criteria or 0) > 0 and (a.done / a.criteria) or -1
            local right = (b.criteria or 0) > 0 and (b.done / b.criteria) or -1

            if left ~= right then
                return left > right
            end

            return tostring(a.name) < tostring(b.name)
        end)
    end

    return groups, order
end

-- The ones worth finishing next: started, not finished, closest first.
-- An untouched zone is not "nearly done", so it sorts below one you have
-- already put an evening into.
function Loremaster.Closest(limit)
    local candidates = {}

    for id, record in pairs(Records()) do
        if not record.completed
            and (record.criteria or 0) > 0
            and (record.done or 0) > 0 then

            table.insert(candidates, {
                id       = id,
                name     = record.name,
                category = record.category,
                done     = record.done,
                criteria = record.criteria,
                fraction = record.done / record.criteria,
            })
        end
    end

    table.sort(candidates, function(a, b)
        if a.fraction ~= b.fraction then
            return a.fraction > b.fraction
        end

        return (a.criteria - a.done) < (b.criteria - b.done)
    end)

    return CN.CapCandidates(candidates, limit or 10)
end

-- The quest achievement that matches the zone you are standing in.
--
-- Matched by name, which is imperfect and honest about being so: the client
-- does not link an achievement to a map. "Loremaster of Khaz Algar" will not
-- match "Isle of Dorn", and it is not supposed to -- the per-zone achievement
-- is the one that will.
function Loremaster.ForZone(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return nil
    end

    local zoneName = Blizzard.GetMapName(mapID)

    if not zoneName or zoneName == "" then
        return nil
    end

    local best

    for id, record in pairs(Records()) do
        if record.name and string.find(record.name, zoneName, 1, true) then
            -- Prefer an unfinished one; a completed zone achievement is not
            -- the thing you want to be shown while standing in it.
            if not best or (best.completed and not record.completed) then
                best = {
                    id        = id,
                    name      = record.name,
                    completed = record.completed,
                    done      = record.done or 0,
                    criteria  = record.criteria or 0,
                }
            end
        end
    end

    return best
end

------------------------------------------------------------
-- THE STORY, AS DISTINCT FROM EVERYTHING ELSE
------------------------------------------------------------

-- "Finish the story, then do the side quests" is how players actually talk,
-- and the client knows which quests are campaign quests. Splitting the zone's
-- work along that line costs one API call per quest and matches the plan the
-- player already has in their head.
function Loremaster.SplitZoneWork(mapID)
    local quests = CN:GetModule("Quests")

    if not quests then
        return { story = {}, side = {} }
    end

    local split = { story = {}, side = {} }

    for _, poi in ipairs(quests.AvailableOnMap(mapID)) do
        if Blizzard.IsQuestCampaign(poi.questID) then
            table.insert(split.story, poi)
        else
            table.insert(split.side, poi)
        end
    end

    return split
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A zone achievement you are most of the way through is a genuine next
-- action: three quests from Loremaster is worth knowing about while you are
-- standing in the zone, and worthless as a line in a list of four hundred.
CN.RegisterCandidateProvider("Loremaster", function()
    local candidates = {}

    local zone = Loremaster.ForZone()

    if not zone or zone.completed or (zone.criteria or 0) == 0 then
        return candidates
    end

    local remaining = zone.criteria - zone.done

    if remaining <= 0 or remaining > 10 then
        return candidates
    end

    local mapID = select(1, CN.GetPlayerPosition())

    table.insert(candidates, CN.NewObjective({
        id              = zone.id,
        type            = CN.objectiveTypes.ACHIEVEMENT,
        name            = zone.name,
        mapID           = mapID,
        accountWide     = false,
        completionValue = 4,
        reasons         = {
            remaining .. " of " .. zone.criteria .. " left in this zone",
        },
    }))

    return candidates
end, { events = { "ZONE_CHANGED_NEW_AREA", "CRITERIA_UPDATE" }, cooldown = 5 })

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

local function PrintAchievement(entry, indent)
    local bar = ""

    if (entry.criteria or 0) > 0 then
        local fraction = entry.done / entry.criteria

        bar = " |cff5dd2fb" .. CN.ProgressBar(fraction, 12) .. "|r "
            .. entry.done .. "/" .. entry.criteria
    end

    Print((indent or "  ")
        .. (entry.completed and "|cff73b873" or "|cffffff00")
        .. tostring(entry.name) .. "|r" .. bar)
end

CN:RegisterCommand{
    name    = "loremaster",
    aliases = { "lore", "zones" },
    args    = "[all, zone, or a name to filter]",
    order   = 12,
    help    = "Quest completion by zone, continent and expansion.",
    handler = function(args)
        args = CN.Trim(args or "")

        if CN.CountKeys(Records()) == 0 then
            Print("No quest achievements scanned yet. Running a scan now.")
            Loremaster.Scan()
        end

        if string.lower(args) == "zone" or args == "" then
            local zone = Loremaster.ForZone()

            if zone then
                Print("This zone:")
                PrintAchievement(zone)
            end

            local split = Loremaster.SplitZoneWork()

            if #split.story > 0 or #split.side > 0 then
                Print("Available here: |cffffff00" .. #split.story
                    .. "|r story, |cffffff00" .. #split.side .. "|r side.")
            end

            if args ~= "" then
                return
            end

            Print("Closest to finished:")

            for _, entry in ipairs(Loremaster.Closest(8)) do
                PrintAchievement(entry)
            end

            Print("|cff999999/cn loremaster all|r lists everything by expansion.")

            return
        end

        local includeCompleted = string.lower(args) == "all"

        local filter = (not includeCompleted) and string.lower(args) or nil

        local groups, order = Loremaster.ByCategory(includeCompleted)

        local shown = 0

        for _, key in ipairs(order) do
            if not filter or string.find(string.lower(key), filter, 1, true) then
                Print("|cffffd100" .. key .. "|r")

                for _, entry in ipairs(groups[key]) do
                    PrintAchievement(entry, "    ")
                    shown = shown + 1
                end
            end
        end

        if shown == 0 then
            Print("Nothing matched. Try |cffffff00/cn loremaster all|r.")
        end
    end,
}

CN:RegisterCommand{
    name    = "scanlore",
    order   = 27,
    help    = "Rescan quest achievements by zone and expansion.",
    handler = function()
        Print("Quest achievements scanned: " .. Loremaster.Scan() .. ".")
    end,
}

CN:OnLogin(function()
    if CN.CountKeys(Records()) == 0 then
        Loremaster.Scan()
    end
end)

return Loremaster
'@

$Embedded['Modules\Follow.lua'] = @'
-- Modules/Follow.lua
-- Completion Navigator :: stop consulting the addon, start following it.
--
-- Everything this addon knows is currently something you have to ASK for.
-- You type a command, read a list, close it, and play from memory. The
-- routing engine computes stops, orders them, improves the order, and then
-- hands all of that to a player who has to carry it in their head.
--
-- Follow mode makes it present. One small frame showing the stop you are
-- walking to and what you do when you get there, ticking things off as the
-- game reports them, advancing to the next stop when this one is clear, with
-- the arrow already pointed the right way.
--
-- THE RULE THIS FILE IS BUILT AROUND: a co-pilot that fights you is worse
-- than no co-pilot.
--
--   * Off by default. It is started deliberately and stopped with one word.
--   * It never re-points the waypoint while you are walking to something.
--     Advancing happens when the current stop is DONE, not on a timer.
--   * If you wander off and do something it did not suggest, it re-plans
--     around where you actually are rather than herding you back.
--   * It says nothing in chat while it runs. A frame that updates silently
--     is a companion; one that narrates is a nuisance.

local ADDON_NAME, CN = ...

local Follow = CN:RegisterModule("Follow")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local function Settings()
    return CN.Settings() or {}
end

------------------------------------------------------------
-- STATE
------------------------------------------------------------

Follow.active = false

-- The stop currently being walked to, and what it held when we set out.
local current = {
    hub        = nil,
    objectives = nil,
    startedAt  = nil,
}

local frame

Follow.recheckSeconds = 3

------------------------------------------------------------
-- WHAT IS LEFT AT THIS STOP
------------------------------------------------------------

-- An objective is done when it is no longer a candidate.
--
-- Deliberately defined by absence rather than by watching for completion
-- events. Events are per-type and there are eleven types; absence is one
-- rule that covers all of them, including the ones added later, and it is
-- also correct when something is finished by means the addon never saw.
-- The live index, memoised against the candidate generation.
--
-- PERFORMANCE, AND A BUG I SHIPPED IN 0.27.0: a single redraw calls this
-- three times -- once to test whether the stop is finished, once for the
-- header, once for the body -- and each call walked the entire candidate list
-- and built a fresh set of several thousand keys. Three full scans, three
-- throwaway tables, every three seconds, for an answer that cannot have
-- changed between them.
--
-- The candidate list already publishes a generation number that increments
-- when anything is rebuilt. Keyed on that, this is built once per actual
-- change instead of once per question.
local liveIndex = { generation = -1, keys = nil }

local function LiveKeys()
    local generation = 0

    if CN.GetCandidateCacheState then
        local ok, state = pcall(CN.GetCandidateCacheState)

        if ok and state then
            generation = state.generation or 0
        end
    end

    if liveIndex.keys and liveIndex.generation == generation then
        return liveIndex.keys
    end

    local keys = {}

    for _, candidate in ipairs(CN.CollectCandidates() or {}) do
        keys[tostring(candidate.type) .. ":" .. tostring(candidate.id)] = true
    end

    liveIndex.generation = generation
    liveIndex.keys       = keys

    return keys
end

Follow.LiveKeys = LiveKeys

function Follow.Remaining(objectives)
    local remaining = {}

    if type(objectives) ~= "table" then
        return remaining
    end

    local live = LiveKeys()

    for _, objective in ipairs(objectives) do
        local key = tostring(objective.type) .. ":" .. tostring(objective.id)

        if live[key] then
            table.insert(remaining, objective)
        end
    end

    return remaining
end

function Follow.IsStopComplete()
    if not current.objectives then
        return false
    end

    return #Follow.Remaining(current.objectives) == 0
end

------------------------------------------------------------
-- CHOOSING A STOP
------------------------------------------------------------

-- The next stop is the first stop of a route built from where you are
-- STANDING, recomputed rather than remembered.
--
-- Remembering the route and walking down it would be cheaper and wrong: the
-- player who took a detour, took a flight path, or died and released is no
-- longer on the route that was computed, and the honest answer is to look at
-- where they are now.
function Follow.NextStop()
    local mapID, x, y = CN.GetPlayerPosition()

    if not mapID then
        return nil
    end

    local _, _, hubs = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    if type(hubs) ~= "table" then
        return nil
    end

    for _, hub in ipairs(hubs) do
        local remaining = Follow.Remaining(hub.objectives)

        if #remaining > 0 then
            return hub, remaining
        end
    end

    return nil
end

function Follow.SetStop(hub, objectives)
    current.hub        = hub
    current.objectives = objectives or (hub and hub.objectives)
    current.startedAt  = time()

    if hub and hub.mapID and hub.x and hub.y then
        local label = CN.DescribeHub and CN.DescribeHub(hub) or "Next stop"

        CN.SetWaypoint(hub.mapID, hub.x, hub.y, label)
    end
end

-- Advance only when there is a reason to.
--
-- `force` exists for the player asking out loud ("/cn follow next"), which is
-- a different thing from the addon deciding on its own.
function Follow.Advance(force)
    if not Follow.active then
        return false
    end

    if not force and current.hub and not Follow.IsStopComplete() then
        -- Still work here. Do not move the waypoint out from under someone
        -- who is walking toward it.
        return false
    end

    local hub, remaining = Follow.NextStop()

    if not hub then
        current.hub        = nil
        current.objectives = nil

        return false
    end

    -- Do not re-set the waypoint for the stop we are already on.
    if current.hub
        and current.hub.x == hub.x
        and current.hub.y == hub.y
        and not force then

        current.objectives = remaining

        return false
    end

    Follow.SetStop(hub, remaining)

    return true
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

Follow.maxLines = 6

-- What the frame should say, computed separately from the frame itself so it
-- can be asserted without a client.
function Follow.Lines()
    local lines = {}

    if not current.hub then
        table.insert(lines, { text = "Nothing left to route here.", state = "NOTE" })

        return lines
    end

    local remaining = Follow.Remaining(current.objectives)

    local quests = CN:GetModule("Quests")

    local shown = 0

    local open = {}

    for _, objective in ipairs(remaining) do
        open[tostring(objective.type) .. ":" .. tostring(objective.id)] = true
    end

    for _, objective in ipairs(current.objectives or {}) do
        local stillOpen =
            open[tostring(objective.type) .. ":" .. tostring(objective.id)] == true

        if shown >= Follow.maxLines then
            table.insert(lines, {
                text  = "and " .. (#current.objectives - shown) .. " more",
                state = "NOTE",
            })
            break
        end

        local verb = "do"

        if objective.phase and quests and quests.PhaseVerb then
            verb = quests.PhaseVerb(objective.phase)
        end

        table.insert(lines, {
            text  = verb .. ": " .. tostring(objective.name or objective.id),
            state = stillOpen and "OPEN" or "DONE",
        })

        shown = shown + 1
    end

    return lines
end

function Follow.HeaderText()
    if not current.hub then
        return "Completion Navigator"
    end

    local remaining = #Follow.Remaining(current.objectives)

    local total = #(current.objectives or {})

    return string.format("Stop: %d of %d left", remaining, total)
end

local function BuildFrame()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorFollow", UIParent)

    frame:SetSize(240, 120)
    frame:SetFrameStrata("MEDIUM")
    frame:SetMovable(true)
    frame:EnableMouse(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetClampedToScreen(true)

    local saved = Settings()

    saved.followPosition = saved.followPosition or {}

    frame:SetPoint(
        saved.followPosition.point or "TOPLEFT",
        UIParent,
        saved.followPosition.point or "TOPLEFT",
        saved.followPosition.x or 40,
        saved.followPosition.y or -200)

    frame.header = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal")
    frame.header:SetPoint("TOPLEFT", 8, -8)
    frame.header:SetJustifyH("LEFT")

    frame.body = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    frame.body:SetPoint("TOPLEFT", frame.header, "BOTTOMLEFT", 0, -6)
    frame.body:SetJustifyH("LEFT")
    frame.body:SetJustifyV("TOP")

    frame:SetScript("OnDragStart", function(self) self:StartMoving() end)

    frame:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        local point, _, _, x, y = self:GetPoint()

        Settings().followPosition = { point = point, x = x, y = y }
    end)

    frame:Hide()

    return frame
end

Follow.BuildFrame = BuildFrame

function Follow.Redraw()
    if not frame then
        return
    end

    frame.header:SetText(Follow.HeaderText())

    local rendered = {}

    for _, line in ipairs(Follow.Lines()) do
        local colour = "|cffcccccc"

        if line.state == "DONE" then
            colour = "|cff73b873"
        elseif line.state == "NOTE" then
            colour = "|cff999999"
        end

        table.insert(rendered, colour
            .. (line.state == "DONE" and "x " or "- ")
            .. line.text .. "|r")
    end

    frame.body:SetText(table.concat(rendered, "\n"))
end

------------------------------------------------------------
-- THE LOOP
------------------------------------------------------------

local ticker

-- Driven by events, with a slow clock as a backstop rather than as the
-- mechanism. Position changes with no event attached -- walking into range of
-- something -- are the only reason the clock exists at all.
local function Tick()
    if not Follow.active then
        return
    end

    Follow.Advance(false)
    Follow.Redraw()
end

function Follow.Start()
    if Follow.active then
        return false
    end

    Follow.active = true

    Settings().follow = true

    BuildFrame()

    if frame then
        frame:Show()
    end

    Follow.Advance(true)
    Follow.Redraw()

    if C_Timer and C_Timer.NewTicker and not ticker then
        ticker = C_Timer.NewTicker(Follow.recheckSeconds, Tick)
    end

    return true
end

function Follow.Stop()
    Follow.active = false

    Settings().follow = false

    current.hub        = nil
    current.objectives = nil

    if ticker then
        ticker:Cancel()
        ticker = nil
    end

    if frame then
        frame:Hide()
    end

    return true
end

function Follow.Toggle()
    if Follow.active then
        Follow.Stop()
        return false
    end

    Follow.Start()

    return true
end

function Follow.CurrentStop()
    return current.hub, current.objectives
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- Something finished. Check whether it emptied the stop; the check is cheap
-- and the alternative is a co-pilot that lags behind the player.
local function OnSomethingChanged()
    if Follow.active then
        Follow.Advance(false)
        Follow.Redraw()
    end
end

CN:RegisterEvent("QUEST_TURNED_IN", OnSomethingChanged)
CN:RegisterEvent("QUEST_ACCEPTED", OnSomethingChanged)
CN:RegisterEvent("QUEST_LOG_UPDATE", OnSomethingChanged)

-- A new zone invalidates the route entirely, so re-plan rather than advance.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    if Follow.active then
        Follow.Advance(true)
        Follow.Redraw()
    end
end)

CN:OnLogin(function()
    if Settings().follow then
        Follow.Start()
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "follow",
    aliases = { "copilot", "run" },
    args    = "[on, off, next, or nothing to toggle]",
    order   = 10,
    help    = "Follow the route: current stop on screen, advancing as you finish.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "off" or args == "stop" then
            Follow.Stop()
            Print("Follow mode off.")
            return
        end

        if args == "next" or args == "skip" then
            if not Follow.active then
                Print("Follow mode is not running. |cffffff00/cn follow|r starts it.")
                return
            end

            Follow.Advance(true)
            Follow.Redraw()

            local hub = Follow.CurrentStop()

            if hub then
                Print("Moved on: " .. (CN.DescribeHub(hub) or "next stop") .. ".")
            else
                Print("Nothing left to route here.")
            end

            return
        end

        if args == "on" or args == "" then
            if args == "" and Follow.active then
                Follow.Stop()
                Print("Follow mode off.")
                return
            end

            Follow.Start()

            local hub = Follow.CurrentStop()

            if hub then
                Print("Following. First stop: "
                    .. (CN.DescribeHub(hub) or "ahead") .. ".")
                Print("|cff999999It advances when the stop is clear. "
                    .. "|cffffff00/cn follow off|r|cff999999 stops.|r")
            else
                Print("Following, but nothing here needs doing.")
            end

            return
        end

        Print("Usage: /cn follow [on | off | next]")
    end,
}

return Follow
'@

$Embedded['Modules\Session.lua'] = @'
-- Modules/Session.lua
-- Completion Navigator :: "I have forty minutes. What should I do?"
--
-- The single most common shape a play session actually has, and the addon
-- had nothing to say about it. It could rank everything and route between
-- stops, and it could not answer the one question a person with a job and a
-- bedtime asks before logging in.
--
-- WHY THIS IS HARD TO DO HONESTLY.
--
-- A plan that fits in forty minutes requires knowing how long things take,
-- and the client does not say. The tempting move is to make numbers up --
-- "quests take four minutes" -- and present them in a font that looks like
-- measurement. This addon has a standing rule against exactly that.
--
-- So the estimate is built from two halves, and only one of them is guessed:
--
--   TRAVEL is computed. The router already knows the real yard distance
--   between stops, and this module measures how fast you actually move by
--   watching your position. That is arithmetic on observations.
--
--   TASK TIME is learned. Every completion is timed against when the
--   objective was first offered as the current stop, and the median per type
--   is kept. Until a type has been seen enough times, it has NO estimate and
--   the plan says so rather than inventing one.
--
-- A plan therefore starts out honest and vague -- "these stops, distance
-- known, duration not yet" -- and sharpens as it watches you play. That is
-- slower to become useful than a table of invented constants, and it is the
-- only version that is ever true.

local ADDON_NAME, CN = ...

local Session = CN:RegisterModule("Session")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- MEASURED TRAVEL SPEED
------------------------------------------------------------

-- Yards per second. Seeded with a walking-speed figure that is immediately
-- replaced by measurement; it exists so the first plan is not divided by nil.
Session.defaultSpeed = 7

Session.minSamples = 5

-- THE CLOCK.
--
-- `time()` returns whole seconds. Sampling a ten-second interval with a
-- one-second ruler is up to ten per cent of error baked into every estimate
-- the planner produces, and it silently discarded every task that finished
-- within the same second it was offered -- which, in the offline suite, was
-- all of them. `GetTime()` is the client's fractional monotonic clock and is
-- the right instrument for measuring a duration.
--
-- Kept behind a function so the offline harness can drive it.
function Session.Now()
    if GetTime then
        return GetTime()
    end

    return os.clock()
end

-- Speed is kept in two buckets, not one.
--
-- A single median across mounted and unmounted travel is a number that is
-- wrong in both states: too slow to plan a mounted route, too fast to plan a
-- walk around a town. Two medians are two honest answers.
local speed = {
    lastMapID  = nil,
    lastX      = nil,
    lastY      = nil,
    lastAt     = nil,
    lastMounted = nil,
    samples    = { mounted = {}, onFoot = {} },
}

Session.speedSampleCap = 40

local function Mounted()
    if IsMounted and IsMounted() then
        return true
    end

    if UnitOnTaxi and UnitOnTaxi("player") then
        return true
    end

    return false
end

Session.IsMounted = Mounted

-- Called on a slow clock. Measures the distance covered since the last look.
--
-- Deliberately discards anything implausible: a teleport, a flight path, a
-- hearthstone or a zone change would otherwise register as a very fast
-- player and make every estimate useless.
function Session.Observe()
    local mapID, x, y = CN.GetPlayerPosition()

    local now     = Session.Now()
    local mounted = Mounted()

    if not mapID or not x or not y then
        return nil
    end

    local previousMap, previousX, previousY, previousAt, previousMounted =
        speed.lastMapID, speed.lastX, speed.lastY, speed.lastAt, speed.lastMounted

    speed.lastMapID, speed.lastX, speed.lastY = mapID, x, y
    speed.lastAt, speed.lastMounted = now, mounted

    if previousMap ~= mapID or not previousAt then
        return nil
    end

    -- Mounting halfway through an interval makes the sample a blend of both
    -- speeds and belongs to neither bucket.
    if previousMounted ~= mounted then
        return nil
    end

    local elapsed = now - previousAt

    if elapsed <= 0 or elapsed > 30 then
        return nil
    end

    local nav = CN:GetModule("Navigation")

    if not nav or not nav.DistanceYards then
        return nil
    end

    local yards = nav.DistanceYards(mapID, previousX, previousY, x, y)

    if not yards or yards <= 0 then
        return nil
    end

    local observed = yards / elapsed

    -- A player on foot does about 7 yards a second; mounted, roughly 14 to
    -- 20. Anything above 60 is not travel, it is a loading screen.
    if observed < 0.5 or observed > 60 then
        return nil
    end

    local bucket = mounted and speed.samples.mounted or speed.samples.onFoot

    table.insert(bucket, observed)

    while #bucket > Session.speedSampleCap do
        table.remove(bucket, 1)
    end

    return observed, mounted
end

-- The median, not the mean: standing still for a minute should not halve the
-- estimate, and one flight path should not double it.
local function Median(values)
    if #values == 0 then
        return nil
    end

    local sorted = {}

    for index = 1, #values do
        sorted[index] = values[index]
    end

    table.sort(sorted)

    local middle = math.floor(#sorted / 2) + 1

    if #sorted % 2 == 1 then
        return sorted[middle]
    end

    return (sorted[middle - 1] + sorted[middle]) / 2
end

Session.Median = Median

-- The speed to plan with.
--
-- Defaults to however the player is travelling right now, because that is
-- the best available guess at how they will travel next. Falls back to the
-- other bucket rather than to a constant: measured-but-wrong-state beats
-- unmeasured.
function Session.Speed(mounted)
    if mounted == nil then
        mounted = Mounted()
    end

    local preferred = mounted and speed.samples.mounted or speed.samples.onFoot
    local other     = mounted and speed.samples.onFoot or speed.samples.mounted

    if #preferred >= Session.minSamples then
        return Median(preferred), true
    end

    if #other >= Session.minSamples then
        return Median(other), false
    end

    return Session.defaultSpeed, false
end

function Session.SpeedSampleCount(mounted)
    if mounted == nil then
        return #speed.samples.mounted + #speed.samples.onFoot
    end

    return mounted and #speed.samples.mounted or #speed.samples.onFoot
end

function Session.SpeedBuckets()
    return {
        mounted = Median(speed.samples.mounted),
        onFoot  = Median(speed.samples.onFoot),
    }
end

------------------------------------------------------------
-- LEARNED TASK DURATION
------------------------------------------------------------

local function Durations()
    return CN.Account("taskDurations")
end

Session.Durations = Durations

Session.minDurationSamples = 4
Session.durationSampleCap  = 25

-- When each objective was first put in front of the player. A completion
-- timed from here is "how long it took once it was the thing to do", which is
-- the number a plan needs.
-- BOUNDED, because it was not.
--
-- Every objective the addon decorated used to get an entry here and only a
-- completion removed one. Cross a dozen zones and it accumulates a timestamp
-- for everything that ever scrolled past -- a slow leak I shipped in 0.28.0.
--
-- Two bounds now: entries expire, and the table is capped. Neither costs
-- accuracy, because an entry older than the expiry window would have been
-- rejected as implausible at completion time anyway.
local offeredAt = {}
local offeredCount = 0

Session.offerMemoryCap     = 400
Session.offerMemorySeconds = 1800

-- HYSTERESIS, and why it is not optional.
--
-- Pruning the moment the table reaches its cap means every subsequent insert
-- triggers a full sweep of four hundred entries. Recommend(25) does twenty
-- five inserts, so a single call became ten thousand iterations -- measured
-- at 1.5ms, up from 0.02ms. A fix for a memory leak that costs seventy times
-- the CPU is not a fix.
--
-- So: let it overshoot by a quarter, then prune back to the cap. Sweeps
-- happen once per hundred inserts instead of once per insert, and the table
-- is still bounded, which was the entire point.
Session.offerMemorySlack = 0.25

local function Prune(force)
    local trigger = Session.offerMemoryCap
        * (1 + Session.offerMemorySlack)

    if not force and offeredCount <= trigger then
        return 0
    end

    local now = Session.Now()

    local removed = 0

    for key, at in pairs(offeredAt) do
        if now - at > Session.offerMemorySeconds then
            offeredAt[key] = nil
            removed = removed + 1
        end
    end

    offeredCount = offeredCount - removed

    -- Still over cap after expiring? Drop the oldest until it fits. A
    -- timestamp we cannot afford to keep is worth less than a bounded table.
    if offeredCount > Session.offerMemoryCap then
        local ordered = {}

        for key, at in pairs(offeredAt) do
            table.insert(ordered, { key = key, at = at })
        end

        table.sort(ordered, function(a, b) return a.at < b.at end)

        local excess = offeredCount - Session.offerMemoryCap

        for index = 1, excess do
            offeredAt[ordered[index].key] = nil
            removed = removed + 1
        end

        offeredCount = offeredCount - excess
    end

    return removed
end

Session.Prune = Prune

function Session.OfferedCount()
    return offeredCount
end

function Session.NoteOffered(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return
    end

    local key = tostring(objective.type) .. ":" .. tostring(objective.id)

    if offeredAt[key] then
        return
    end

    offeredAt[key] = Session.Now()
    offeredCount   = offeredCount + 1

    Prune()
end

function Session.NoteCompleted(objectiveType, id)
    if not objectiveType or not id then
        return nil
    end

    local key = tostring(objectiveType) .. ":" .. tostring(id)

    local started = offeredAt[key]

    if offeredAt[key] then
        offeredAt[key] = nil
        offeredCount   = offeredCount - 1
    end

    if not started then
        return nil
    end

    local elapsed = Session.Now() - started

    -- Anything over twenty minutes was not "doing the thing", it was living
    -- your life with the thing still on the list.
    --
    -- The lower bound is now a fraction of a second rather than a whole one.
    -- With a one-second clock, anything finished in the same second it was
    -- offered read as zero elapsed and was thrown away -- which quietly
    -- discarded exactly the fast turn-ins a quest grinder produces most of.
    if elapsed <= 0.05 or elapsed > 1200 then
        return nil
    end

    local store = Durations()

    store[objectiveType] = store[objectiveType] or {}

    table.insert(store[objectiveType], elapsed)

    while #store[objectiveType] > Session.durationSampleCap do
        table.remove(store[objectiveType], 1)
    end

    DebugPrint(objectiveType .. " took " .. elapsed .. "s ("
        .. #store[objectiveType] .. " samples).")

    return elapsed
end

-- Seconds this type usually takes, or NIL when the addon has not watched it
-- often enough to have an opinion. Nil is a real answer here and every
-- caller must handle it rather than substituting a guess.
function Session.TypicalSeconds(objectiveType)
    local samples = Durations()[objectiveType]

    if not samples or #samples < Session.minDurationSamples then
        return nil
    end

    return Median(samples)
end

function Session.HasEnoughData()
    for _, samples in pairs(Durations()) do
        if #samples >= Session.minDurationSamples then
            return true
        end
    end

    return false
end

------------------------------------------------------------
-- THE PLAN
------------------------------------------------------------

-- Estimates a stop: travel to it, plus the work at it.
--
-- Returns seconds and a confidence flag. `false` means part of this was not
-- measured, and callers must say so out loud.
function Session.EstimateHub(hub, fromX, fromY)
    local confident = true

    local nav = CN:GetModule("Navigation")

    local travelSeconds = 0

    if nav and nav.DistanceYards and hub.mapID and hub.x and hub.y
        and fromX and fromY then

        local yards = nav.DistanceYards(hub.mapID, fromX, fromY, hub.x, hub.y)

        if yards then
            local rate, measured = Session.Speed()

            travelSeconds = yards / math.max(0.5, rate)

            if not measured then
                confident = false
            end
        else
            confident = false
        end
    else
        confident = false
    end

    local workSeconds = 0

    for _, objective in ipairs(hub.objectives or {}) do
        local typical = Session.TypicalSeconds(objective.type)

        if typical then
            workSeconds = workSeconds + typical
        else
            confident = false
        end
    end

    return travelSeconds + workSeconds, confident, travelSeconds, workSeconds
end

-- Builds a route and takes stops from the front of it until the budget is
-- spent.
--
-- Takes from the FRONT rather than choosing the best-fitting subset. The
-- route is already ordered to minimise walking; cherry-picking stops out of
-- it produces a plan that fits the clock and makes you cross the zone twice.
function Session.Plan(minutes)
    local budget = (tonumber(minutes) or 30) * 60

    local mapID, x, y = CN.GetPlayerPosition()

    local plan = {
        minutes   = budget / 60,
        stops     = {},
        seconds   = 0,
        confident = true,
        skipped   = 0,
    }

    if not mapID then
        return plan
    end

    local _, _, hubs = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    if type(hubs) ~= "table" then
        return plan
    end

    local currentX, currentY = x or 0.5, y or 0.5

    for _, hub in ipairs(hubs) do
        local seconds, confident, travel, work =
            Session.EstimateHub(hub, currentX, currentY)

        if plan.seconds + seconds > budget and #plan.stops > 0 then
            plan.skipped = plan.skipped + 1
        else
            table.insert(plan.stops, {
                hub       = hub,
                seconds   = seconds,
                travel    = travel,
                work      = work,
                summary   = CN.DescribeHub and CN.DescribeHub(hub) or nil,
                confident = confident,
            })

            plan.seconds = plan.seconds + seconds

            if not confident then
                plan.confident = false
            end

            currentX, currentY = hub.x or currentX, hub.y or currentY
        end
    end

    return plan
end

function Session.FormatDuration(seconds)
    if not seconds or seconds <= 0 then
        return "0m"
    end

    local minutes = math.floor(seconds / 60 + 0.5)

    if minutes < 60 then
        return minutes .. "m"
    end

    return string.format("%dh %dm", math.floor(minutes / 60), minutes % 60)
end

------------------------------------------------------------
-- WIRING
------------------------------------------------------------

-- The clock starts when something is RECOMMENDED, not when it is collected.
--
-- 0.28.0 hung this on a candidate decorator, which meant a timestamp was
-- taken for every objective the addon knew about on every rebuild -- two
-- hundred at retail scale, the overwhelming majority of which the player
-- never saw and no plan ever used. Wrong on cost and wrong on meaning: an
-- objective sitting at rank 180 has not been "offered" to anybody.
--
-- Recommend() is the moment something is actually put in front of a player.
function Session.NoteRecommended(list)
    for index = 1, math.min(#list, Session.timedRecommendations) do
        Session.NoteOffered(list[index])
    end

    return list
end

Session.timedRecommendations = 25

if CN.RegisterRecommendationHook then
    CN.RegisterRecommendationHook("SessionTiming", Session.NoteRecommended)
end

CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    Session.NoteCompleted(CN.objectiveTypes.QUEST, questID)
end)

CN:RegisterEvent("NEW_PET_ADDED", function()
    -- The client does not say which pet, so nothing can be timed here
    -- honestly. Left deliberately unhandled rather than attributing the
    -- elapsed time to a guess.
end)

local ticker

CN:OnLogin(function()
    Session.Observe()

    if C_Timer and C_Timer.NewTicker and not ticker then
        ticker = C_Timer.NewTicker(10, Session.Observe)
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "plan",
    aliases = { "time", "budget" },
    args    = "<minutes>",
    order   = 13,
    help    = "What fits in the time you actually have.",
    handler = function(args)
        local minutes = tonumber(CN.Trim(args or ""))

        if not minutes or minutes <= 0 then
            Print("Usage: |cffffff00/cn plan 30|r")
            return
        end

        local plan = Session.Plan(minutes)

        if #plan.stops == 0 then
            Print("Nothing here to plan around.")
            return
        end

        Print(string.format("%d stop%s, about %s of the %dm you have:",
            #plan.stops,
            #plan.stops == 1 and "" or "s",
            Session.FormatDuration(plan.seconds),
            minutes))

        for index, stop in ipairs(plan.stops) do
            Print(string.format("  %d. |cffffff00%s|r |cff999999%s|r",
                index,
                tostring(stop.summary or "stop"),
                stop.confident and Session.FormatDuration(stop.seconds)
                    or "time unknown"))
        end

        if plan.skipped > 0 then
            Print("|cff999999" .. plan.skipped
                .. " further stop(s) did not fit.|r")
        end

        if not plan.confident then
            local rate, measured = Session.Speed()

            Print("|cffffff00Some of this is not measured yet.|r "
                .. "|cff999999Travel speed: "
                .. (measured and string.format("%.0f yd/s from %d samples",
                        rate, Session.SpeedSampleCount())
                    or "still learning")
                .. ". Task times are learned from your own play, so the "
                .. "estimate sharpens as you go rather than starting from "
                .. "numbers nobody measured.|r")
        end
    end,
}

return Session
'@

$Embedded['Modules\Vault.lua'] = @'
-- Modules/Vault.lua
-- Completion Navigator :: the Great Vault.
--
-- The weekly reward chest. Three rows -- raid, dungeons, world -- each with
-- three thresholds, and you choose ONE item from everything unlocked.
--
-- This module matters more than its size suggests, because the Great Vault is
-- the only system in the game that hands the addon all three things it
-- normally has to guess at:
--
--   * a hard deadline      -- the weekly reset, which the client reports
--   * a known denominator  -- the thresholds are fixed
--   * a known reward       -- the client reports the item level
--
-- Everywhere else this addon reports counts rather than percentages, because
-- a percentage needs a denominator the client will not supply. Here it will.
-- "3 of 4 dungeons" is a fact, and "one more Heroic before Tuesday unlocks a
-- second reward" is a genuine next action rather than an estimate.
--
-- The nearly-there row is the whole point. A row sitting one activity short of
-- a threshold is the highest-value, most time-boxed objective the addon can
-- offer; a row already at its cap is worth nothing this week.

local ADDON_NAME, CN = ...

local Vault = CN:RegisterModule("Vault")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- ROWS
------------------------------------------------------------

Vault.rowLabels = {
    RAID    = "Raid",
    DUNGEON = "Dungeons",
    WORLD   = "World",
    PVP     = "PvP",
    UNKNOWN = "Other",
}

-- What the player would actually go and do to advance each row. Naming the
-- action is the difference between a progress bar and a recommendation.
Vault.rowActions = {
    RAID    = "defeat another raid boss",
    DUNGEON = "run another Heroic or higher dungeon",
    WORLD   = "complete another Delve, weekly quest or zone event",
    PVP     = "complete another rated PvP match",
    UNKNOWN = "complete another qualifying activity",
}

local ROW_ORDER = { "RAID", "DUNGEON", "WORLD", "PVP", "UNKNOWN" }

------------------------------------------------------------
-- READING THE VAULT
------------------------------------------------------------

-- Collapses the flat activity list into one entry per row:
--
--   { row, label, progress, unlocked, tiers, next, remaining, capped }
--
-- `next` is the next unmet threshold; `remaining` is how many activities
-- away it is. Both nil when the row is capped.
function Vault.Rows()
    local activities = Blizzard.GetWeeklyRewardActivities()

    if #activities == 0 then
        return {}
    end

    local byRow = {}

    for _, activity in ipairs(activities) do
        local row = byRow[activity.row]

        if not row then
            row = {
                row      = activity.row,
                label    = Vault.rowLabels[activity.row] or activity.row,
                progress = 0,
                unlocked = 0,
                tiers    = {},
            }

            byRow[activity.row] = row
        end

        -- Every tier of a row reports the same progress figure; taking the
        -- maximum is defensive rather than necessary.
        row.progress = math.max(row.progress, activity.progress or 0)

        table.insert(row.tiers, {
            threshold = activity.threshold,
            progress  = activity.progress,
            level     = activity.level,
            unlocked  = activity.unlocked,
        })

        if activity.unlocked then
            row.unlocked = row.unlocked + 1
        end
    end

    local rows = {}

    for _, name in ipairs(ROW_ORDER) do
        local row = byRow[name]

        if row then
            table.sort(row.tiers, function(a, b)
                return (a.threshold or 0) < (b.threshold or 0)
            end)

            for _, tier in ipairs(row.tiers) do
                if not tier.unlocked and not row.next then
                    row.next      = tier.threshold
                    row.remaining = math.max(0, (tier.threshold or 0) - row.progress)
                end
            end

            row.capped = row.next == nil

            table.insert(rows, row)
        end
    end

    return rows
end

function Vault.IsAvailable()
    return Blizzard.HasWeeklyRewards()
end

-- Total reward choices unlocked across every row.
function Vault.Summary()
    local rows = Vault.Rows()

    local summary = {
        rows     = #rows,
        unlocked = 0,
        closest  = nil,
        resetsIn = Blizzard.GetSecondsUntilWeeklyReset(),
        claimable = Blizzard.HasAvailableWeeklyRewards(),
    }

    for _, row in ipairs(rows) do
        summary.unlocked = summary.unlocked + row.unlocked

        if not row.capped and row.remaining then
            if not summary.closest or row.remaining < summary.closest.remaining then
                summary.closest = row
            end
        end
    end

    return summary
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

local function FormatReset(seconds)
    if not seconds then
        return nil
    end

    local days  = math.floor(seconds / 86400)
    local hours = math.floor((seconds % 86400) / 3600)

    if days > 0 then
        return days .. "d " .. hours .. "h"
    end

    if hours > 0 then
        return hours .. "h"
    end

    return math.max(1, math.floor(seconds / 60)) .. "m"
end

Vault.FormatReset = FormatReset

function Vault.DescribeRow(row)
    local text = row.label .. ": " .. row.progress

    if row.capped then
        return text .. " |cff00ff00all " .. row.unlocked .. " unlocked|r"
    end

    return text .. " of " .. row.next
        .. " |cff999999(" .. row.unlocked .. " unlocked, "
        .. row.remaining .. " more for the next)|r"
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Urgency rises as the reset approaches AND as the row nears its threshold.
-- One activity away with a day left is the single most actionable thing the
-- addon can surface; three away with six days left is barely worth a mention.
local function Urgency(remaining, resetsIn)
    local value = 0

    if remaining then
        if remaining <= 1 then
            value = value + 3
        elseif remaining <= 2 then
            value = value + 2
        else
            value = value + 1
        end
    end

    if resetsIn then
        local days = resetsIn / 86400

        if days <= 1 then
            value = value + 3
        elseif days <= 2 then
            value = value + 2
        elseif days <= 4 then
            value = value + 1
        end
    end

    return value
end

Vault.Urgency = Urgency

-- How many activities away a row can be and still be worth recommending.
-- Beyond this it is a plan for the week, not a next action.
Vault.maxRemaining = 4

CN.RegisterCandidateProvider("Vault", function()
    local candidates = {}

    if not Vault.IsAvailable() then
        return candidates
    end

    local resetsIn = Blizzard.GetSecondsUntilWeeklyReset()

    -- An unclaimed vault from last week outranks everything: it is free, it
    -- takes thirty seconds, and it expires.
    if Blizzard.HasAvailableWeeklyRewards() then
        table.insert(candidates, CN.NewObjective({
            id               = 0,
            type             = CN.objectiveTypes.CURRENCY,
            name             = "Collect your Great Vault reward",
            accountWide      = false,
            completionValue  = 8,
            limitedTimeBonus = 3,
            travelCost       = 2,
            reasons          = {
                "a reward is waiting to be claimed",
                "it is replaced when the vault next fills",
            },
        }))
    end

    for _, row in ipairs(Vault.Rows()) do
        if not row.capped
            and row.remaining
            and row.remaining <= Vault.maxRemaining
            and not CN.IsIgnored(CN.objectiveTypes.CURRENCY, row.row)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, row.row) then

            local reasons = {
                row.remaining .. " more to unlock a "
                    .. (row.unlocked > 0 and "further" or "first")
                    .. " Great Vault reward",
                Vault.rowActions[row.row] or "complete another activity",
            }

            if resetsIn then
                table.insert(reasons, "resets in " .. FormatReset(resetsIn))
            end

            table.insert(candidates, CN.NewObjective({
                id               = row.row,
                type             = CN.objectiveTypes.CURRENCY,
                name             = "Great Vault: " .. row.label,
                accountWide      = false,
                completionValue  = 4,
                limitedTimeBonus = Urgency(row.remaining, resetsIn),
                -- Instanced content has no map coordinate, but it is not
                -- "location unknown" either: the group finder is one click.
                travelCost       = 3,
                expiresIn        = resetsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, { events = { "WEEKLY_REWARDS_UPDATE", "CHALLENGE_MODE_COMPLETED",
                  "ENCOUNTER_END", "QUEST_TURNED_IN" }, volatile = true })

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "vault",
    aliases = { "greatvault" },
    order   = 16,
    help    = "Great Vault progress and what unlocks the next reward.",
    handler = function()
        if not Vault.IsAvailable() then
            Print("The Great Vault is not available on this client.")
            return
        end

        local rows = Vault.Rows()

        if #rows == 0 then
            Print("No Great Vault progress recorded yet.")
            Print("|cff999999The client reports vault progress once you have "
                .. "completed at least one qualifying activity this week.|r")
            return
        end

        local summary = Vault.Summary()

        Print("Great Vault: " .. summary.unlocked .. " reward"
            .. (summary.unlocked == 1 and "" or "s") .. " unlocked"
            .. (summary.resetsIn
                and (" |cff999999resets in " .. FormatReset(summary.resetsIn) .. "|r")
                or ""))

        if summary.claimable then
            Print("|cff00ff00A reward is waiting to be collected.|r")
        end

        for _, row in ipairs(rows) do
            Print("  " .. Vault.DescribeRow(row))
        end

        if summary.closest then
            Print("|cffffff00Closest:|r " .. summary.closest.label
                .. " -- " .. summary.closest.remaining .. " more, "
                .. (Vault.rowActions[summary.closest.row] or "keep going") .. ".")
        else
            Print("|cff00ff00Every row is capped. Nothing more to earn this week.|r")
        end

        Print("|cff999999You choose one item from everything unlocked.|r")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Navigation.lua'] = @'
-- Modules/Navigation.lua
-- Completion Navigator :: native waypoints and the on-screen arrow.
--
-- Until now the addon decided WHERE to go and handed the job of pointing at it
-- to TomTom. That made TomTom effectively required: without it you got a
-- static map pin and no arrow, which is not navigation.
--
-- This file removes that dependency. It is not an attempt to reimplement
-- TomTom -- it is the minimum that makes the addon complete on its own:
--
--   * a waypoint store of our own
--   * an arrow that points at the current target and colours by whether you
--     are facing it
--   * real distance in yards, not map percentage
--   * arrival detection, which is what makes auto-advance work properly
--
-- TomTom stays supported. Someone who already runs it and likes its arrow can
-- keep using it -- /cn nav tomtom -- and everything else still works.
--
------------------------------------------------------------------------------
-- THE MATH, and an admission about it.
--
--   Map coordinates run x east, y SOUTH. North is therefore -y.
--   bearing clockwise from north = atan2(dx, -dy)
--   relative bearing             = bearing - (facing * facingSign)
--   rotation to apply            = -(relative bearing)
--
-- The one thing that cannot be derived from first principles is which way
-- GetPlayerFacing() counts. 0 is north on every build; whether the value grows
-- as you turn left or as you turn right is a client convention.
--
-- 0.19.0 assumed counter-clockwise and shipped a bearing that pointed people
-- away from their target. The harness "verified" it against seven cases -- and
-- every one of those cases computed its expected answer from the same
-- assumption, so the tests agreed with the bug. A test that encodes the
-- premise it is meant to check proves nothing.
--
-- So the sign is not asserted here. It defaults to the convention every
-- established navigation addon uses, and then CORRECTS ITSELF from evidence:
-- if you are lined up with the arrow, moving, and the distance is growing,
-- the sign is wrong, and the addon flips it and says so. The game is the only
-- thing that can settle this, so the game settles it.
------------------------------------------------------------------------------

local ADDON_NAME, CN = ...

local Navigation = CN:RegisterModule("Navigation")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STATE
------------------------------------------------------------

-- The single active target. One arrow, one destination: a list of waypoints is
-- TomTom's job, and duplicating it would be duplicating the wrong half.
local target = nil

local arrow, ticker

Navigation.arrivalYards = 12

function Navigation.GetTarget()
    return target
end

------------------------------------------------------------
-- GEOMETRY
------------------------------------------------------------

-- Radians clockwise from straight ahead. nil when the bearing cannot be
-- computed, which is different from zero and must not be shown as zero.
-- +1 means GetPlayerFacing() grows clockwise; -1 means counter-clockwise.
-- Persisted once determined, so the correction happens at most once ever.
function Navigation.FacingSign()
    local settings = CN.Settings()

    if settings and settings.facingSign then
        return settings.facingSign
    end

    return 1
end

function Navigation.SetFacingSign(sign)
    local settings = CN.Settings()

    if settings then
        settings.facingSign = (sign < 0) and -1 or 1
    end
end

function Navigation.RelativeBearing(playerX, playerY, targetX, targetY, facing, sign)
    if not (playerX and playerY and targetX and targetY and facing) then
        return nil
    end

    local dx = targetX - playerX
    local dy = targetY - playerY

    if dx == 0 and dy == 0 then
        return 0
    end

    -- -dy because map y grows southward.
    local bearing = math.atan(dx, -dy)

    local relative = bearing - (facing * (sign or Navigation.FacingSign()))

    -- Normalize to (-pi, pi] so "how far off am I" is a small number.
    while relative > math.pi do
        relative = relative - (2 * math.pi)
    end

    while relative <= -math.pi do
        relative = relative + (2 * math.pi)
    end

    return relative
end

-- Distance in yards, using the client's world positions. Map coordinates are
-- normalized per map, so a 0.1 difference is a different real distance in
-- every zone; converting is the only way to get a number worth printing.
--
-- Returns nil when the client cannot convert, rather than a made-up figure.
function Navigation.DistanceYards(mapID, playerX, playerY, targetX, targetY)
    if not (mapID and playerX and playerY and targetX and targetY) then
        return nil
    end

    if not C_Map or not C_Map.GetWorldPosFromMapPos then
        return nil
    end

    -- GetWorldPosFromMapPos takes a Vector2D, NOT a UiMapPoint.
    --
    -- These are two different types and 0.19.0 passed the wrong one, so the
    -- call returned nothing and the arrow reported "distance unknown" for
    -- every target. UiMapPoint carries a nested `position`; Vector2D carries
    -- x and y directly. SetUserWaypoint wants the former, this wants the
    -- latter, and they are easy to confuse because both describe a point.
    if not CreateVector2D then
        return nil
    end

    local function worldPosition(x, y)
        local ok, continentID, position =
            pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

        if not ok or not position then
            return nil, nil
        end

        -- Vector2D exposes GetXY(); some builds also expose x and y directly.
        local wx, wy

        if position.GetXY then
            local gotXY, gx, gy = pcall(position.GetXY, position)

            if gotXY then
                wx, wy = gx, gy
            end
        end

        wx = wx or position.x
        wy = wy or position.y

        if not wx or not wy then
            return nil, nil
        end

        return continentID, { x = wx, y = wy }
    end

    local fromContinent, fromPos = worldPosition(playerX, playerY)

    if not fromPos then
        return nil
    end

    local toContinent, toPos = worldPosition(targetX, targetY)

    if not toPos then
        return nil
    end

    -- Different continents means the straight-line number would be nonsense.
    if fromContinent and toContinent and fromContinent ~= toContinent then
        return nil
    end

    local dx = toPos.x - fromPos.x
    local dy = toPos.y - fromPos.y

    return math.sqrt((dx * dx) + (dy * dy))
end

function Navigation.FormatDistance(yards)
    if not yards then
        return "distance unknown"
    end

    if yards >= 1000 then
        return string.format("%.1f km", yards * 0.0009144)
    end

    return string.format("%d yd", math.floor(yards + 0.5))
end

------------------------------------------------------------
-- THE ARROW
------------------------------------------------------------

local function Settings()
    return CN.Settings() or {}
end

function Navigation.IsArrowEnabled()
    local settings = Settings()

    return settings.arrow ~= false
end

local function BuildArrow()
    if arrow or not CreateFrame then
        return arrow
    end

    arrow = CreateFrame("Frame", "CompletionNavigatorArrow", UIParent)

    arrow:SetSize(56, 56)
    arrow:SetFrameStrata("MEDIUM")
    arrow:SetMovable(true)
    arrow:EnableMouse(true)
    arrow:RegisterForDrag("LeftButton")
    arrow:SetClampedToScreen(true)

    local settings = Settings()

    settings.arrowPosition = settings.arrowPosition or {}

    arrow:SetPoint(
        settings.arrowPosition.point or "CENTER",
        UIParent,
        settings.arrowPosition.point or "CENTER",
        settings.arrowPosition.x or 0,
        settings.arrowPosition.y or 160)

    arrow.texture = arrow:CreateTexture(nil, "ARTWORK")
    arrow.texture:SetAllPoints()
    arrow.texture:SetTexture(CN.MEDIA_PATH .. "Arrow")

    -- SetTexture fails silently on a missing file, so verify rather than
    -- shipping an invisible arrow.
    if not arrow.texture:GetTexture() then
        arrow.texture:SetTexture("Interface\\Minimap\\MinimapArrow")
    end

    arrow.label = arrow:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    arrow.label:SetPoint("TOP", arrow, "BOTTOM", 0, -2)
    arrow.label:SetJustifyH("CENTER")

    arrow.distance = arrow:CreateFontString(nil, "OVERLAY", "GameFontHighlightLarge")
    arrow.distance:SetPoint("TOP", arrow.label, "BOTTOM", 0, -2)
    arrow.distance:SetJustifyH("CENTER")

    arrow:SetScript("OnDragStart", function(self)
        self:StartMoving()
    end)

    arrow:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        local point, _, _, x, y = self:GetPoint()

        local saved = Settings()

        saved.arrowPosition = { point = point, x = x, y = y }
    end)

    arrow:Hide()

    return arrow
end

Navigation.BuildArrow = BuildArrow

-- The arrow's palette.
--
-- ON_COURSE is the blue of the waypoint marker in the addon's own logo,
-- sampled from it rather than guessed: #5DD2FB. Because you are pointed at
-- your target most of the time, this is the colour the arrow actually wears,
-- which is what makes it read as part of the addon rather than as generic
-- navigation furniture.
--
-- The texture is greyscale for exactly this reason: tinting is a multiply, so
-- a pre-coloured blue arrow could never turn amber, and the bearing feedback
-- would be lost to make one screenshot prettier.
Navigation.colors = {
    ON_COURSE = { 0.365, 0.824, 0.984 },   -- #5DD2FB, the logo's marker blue
    DRIFTING  = { 1.000, 0.780, 0.310 },   -- the logo's gold, for "turn a bit"
    AWAY      = { 0.960, 0.420, 0.380 },   -- you are walking the wrong way
    UNKNOWN   = { 0.600, 0.640, 0.680 },   -- no bearing available
}

-- Blue when you are walking toward it, gold when you are drifting, red when
-- you are walking away. The single most useful thing an arrow does, and it
-- costs one comparison.
function Navigation.BearingColor(relative)
    local palette = Navigation.colors

    if not relative then
        return palette.UNKNOWN[1], palette.UNKNOWN[2], palette.UNKNOWN[3]
    end

    local off = math.abs(relative)

    if off < 0.35 then
        return palette.ON_COURSE[1], palette.ON_COURSE[2], palette.ON_COURSE[3]
    end

    if off < 1.2 then
        return palette.DRIFTING[1], palette.DRIFTING[2], palette.DRIFTING[3]
    end

    return palette.AWAY[1], palette.AWAY[2], palette.AWAY[3]
end

-- Recomputes the arrow. Split out so the harness can drive it without a frame.
function Navigation.Compute()
    if not target then
        return nil
    end

    local mapID, playerX, playerY = CN.GetPlayerPosition()

    if not mapID or not playerX or not playerY then
        return { state = "NO_POSITION" }
    end

    if mapID ~= target.mapID then
        return {
            state = "WRONG_MAP",
            zone  = target.zone or Blizzard.GetMapName(target.mapID),
        }
    end

    local facing = GetPlayerFacing and GetPlayerFacing() or nil

    local relative = Navigation.RelativeBearing(playerX, playerY,
        target.x, target.y, facing)

    local yards = Navigation.DistanceYards(mapID, playerX, playerY,
        target.x, target.y)

    return {
        state    = (yards and yards <= Navigation.arrivalYards) and "ARRIVED" or "TRACKING",
        relative = relative,
        yards    = yards,
        facing   = facing,
    }
end

------------------------------------------------------------
-- SELF-CORRECTION
------------------------------------------------------------

-- Evidence that the facing convention is backwards.
--
-- If you are lined up with the arrow and moving, the distance must shrink. If
-- it grows instead, the arrow is pointing at the reciprocal. That is not a
-- guess -- it is the definition of the arrow being wrong, observed directly.
--
-- Several consecutive samples are required so that walking backwards, a
-- flight path, or a teleport cannot trigger it.
local calibration = {
    lastDistance = nil,
    growing      = 0,
    corrected    = false,
}

Navigation.calibrationSamples = 4

function Navigation.ResetCalibration()
    calibration.lastDistance = nil
    calibration.growing      = 0
end

function Navigation.NoteObservation(relative, yards)
    -- Only meaningful while genuinely lined up: if you are not following the
    -- arrow, the distance says nothing about whether the arrow is right.
    if not relative or not yards or math.abs(relative) > 0.3 then
        Navigation.ResetCalibration()
        return false
    end

    local previous = calibration.lastDistance

    calibration.lastDistance = yards

    if not previous then
        return false
    end

    local delta = yards - previous

    -- Ignore standing still and ignore jumps far too large to be walking,
    -- which are loading screens rather than movement.
    if math.abs(delta) < 0.5 or math.abs(delta) > 200 then
        return false
    end

    if delta > 0 then
        calibration.growing = calibration.growing + 1
    else
        calibration.growing = 0
    end

    if calibration.growing < Navigation.calibrationSamples then
        return false
    end

    calibration.growing = 0

    if calibration.corrected then
        -- Already flipped once this session and still wrong: flipping back and
        -- forth forever would be worse than leaving it alone.
        return false
    end

    calibration.corrected = true

    Navigation.SetFacingSign(-Navigation.FacingSign())

    Print("The arrow was pointing the wrong way. Corrected, and remembered.")
    DebugPrint("Facing sign is now " .. Navigation.FacingSign() .. ".")

    return true
end

local function Refresh()
    if not arrow then
        return
    end

    if not target or not Navigation.IsArrowEnabled() then
        arrow:Hide()
        return
    end

    local state = Navigation.Compute()

    if not state then
        arrow:Hide()
        return
    end

    arrow:Show()

    arrow.label:SetText(target.title or "Destination")

    if state.state == "WRONG_MAP" then
        arrow.texture:SetRotation(0)
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
        arrow.distance:SetText("|cff999999" .. (state.zone or "another zone") .. "|r")
        return
    end

    if state.state == "NO_POSITION" then
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
        arrow.distance:SetText("|cff999999no position|r")
        return
    end

    if state.relative then
        -- SetRotation turns counter-clockwise; the relative bearing is
        -- clockwise, hence the negation.
        arrow.texture:SetRotation(-state.relative)
    end

    arrow.texture:SetVertexColor(Navigation.BearingColor(state.relative))

    arrow.distance:SetText(Navigation.FormatDistance(state.yards))

    -- Watch whether following the arrow actually works.
    Navigation.NoteObservation(state.relative, state.yards)

    if state.state == "ARRIVED" then
        Navigation.Arrive()
    end
end

Navigation.Refresh = Refresh

function Navigation.Arrive()
    if not target or target.arrived then
        return
    end

    target.arrived = true

    Print("Arrived: " .. tostring(target.title or "destination"))

    -- Arrival is exactly the moment auto-advance was designed for; before
    -- this, it could only re-point on a timer or an event.
    if CN.IsAutoWaypointEnabled and CN.IsAutoWaypointEnabled() then
        CN.AutoAdvance("arrival", true)
    else
        Navigation.Clear()
    end
end

------------------------------------------------------------
-- TICKER
------------------------------------------------------------

-- Ten times a second. A rotating arrow needs to feel continuous; recomputing
-- world positions every frame does not.
Navigation.tickSeconds = 0.1

function Navigation.StartTicker()
    if ticker or not C_Timer or not C_Timer.NewTicker then
        return
    end

    ticker = C_Timer.NewTicker(Navigation.tickSeconds, function()
        local ok, err = pcall(Refresh)

        if not ok then
            DebugPrint("Arrow refresh failed: " .. tostring(err))
        end
    end)
end

function Navigation.StopTicker()
    if ticker then
        ticker:Cancel()
        ticker = nil
    end
end

------------------------------------------------------------
-- WAYPOINT PROVIDER
------------------------------------------------------------

local provider = {}

function provider.IsAvailable()
    -- Native navigation needs nothing but the map API, which is why it is the
    -- default: it is the only provider that cannot be missing.
    return C_Map ~= nil and C_Map.GetBestMapForUnit ~= nil
end

function provider.SetWaypoint(mapID, x, y, title)
    target = {
        mapID = mapID,
        x     = x,
        y     = y,
        title = title,
        zone  = Blizzard.GetMapName(mapID),
        setAt = time(),
    }

    Navigation.ResetCalibration()

    BuildArrow()
    Navigation.StartTicker()
    Refresh()

    -- Also drop a map pin, so the destination is visible on the world map and
    -- not only in front of the player.
    if C_Map.SetUserWaypoint and UiMapPoint and UiMapPoint.CreateFromCoordinates then
        local ok = pcall(function()
            C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(mapID, x, y))
        end)

        if ok and C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then
            pcall(C_SuperTrack.SetSuperTrackedUserWaypoint, true)
        end
    end

    return true
end

function provider.ClearAll()
    Navigation.Clear()
end

function Navigation.Clear()
    target = nil

    if arrow then
        arrow:Hide()
    end

    Navigation.StopTicker()

    if C_Map and C_Map.ClearUserWaypoint then
        pcall(C_Map.ClearUserWaypoint)
    end
end

-- Priority 5: ahead of TomTom's 10. The addon is self-contained now, and a
-- player who prefers TomTom's arrow can say so with /cn nav tomtom.
CN.RegisterWaypointProvider("Native", provider, 5)

Navigation.provider = provider

------------------------------------------------------------
-- PROVIDER PREFERENCE
------------------------------------------------------------

-- Overrides the priority order. Stored rather than inferred, because
-- "whichever addon happens to be loaded" is not a preference.
function Navigation.SetPreference(name)
    local settings = Settings()

    if name == "auto" or name == nil then
        settings.navigation = nil
        return true, "automatic"
    end

    local key = string.lower(name)

    local known = {
        native  = "Native",
        tomtom  = "TomTom",
        blizzard = "Blizzard",
    }

    if not known[key] then
        return false, nil
    end

    settings.navigation = known[key]

    return true, known[key]
end

function Navigation.Preference()
    return Settings().navigation
end

-- Consulted by Routing before the priority order.
function CN.GetPreferredWaypointProvider()
    local preferred = Navigation.Preference()

    if not preferred then
        return nil
    end

    local candidate = CN.waypointProviders[preferred]

    if candidate and candidate.IsAvailable and candidate.IsAvailable() then
        return candidate, preferred
    end

    return nil
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "arrow",
    args    = "[on or off]",
    order   = 40,
    help    = "Toggle the on-screen navigation arrow.",
    handler = function(args)
        local settings = Settings()

        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            settings.arrow = true
        elseif args == "off" then
            settings.arrow = false
        elseif args ~= "" then
            Print("Usage: /cn arrow [on or off]")
            return
        else
            settings.arrow = (settings.arrow == false)
        end

        Print("Navigation arrow: " .. CN.YesNo(Navigation.IsArrowEnabled()))

        if Navigation.IsArrowEnabled() then
            BuildArrow()
            Refresh()
        elseif arrow then
            arrow:Hide()
        end

        if not target then
            Print("|cff999999Nothing is being tracked. |cffffff00/cn go|r "
                .. "points it at something.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "calibrate",
    aliases = { "flip" },
    order   = 43,
    help    = "Flip the navigation arrow if it points the wrong way.",
    handler = function()
        Navigation.SetFacingSign(-Navigation.FacingSign())
        Navigation.ResetCalibration()

        Print("Arrow direction flipped and remembered.")
        Print("|cff999999Whether GetPlayerFacing counts clockwise or "
            .. "counter-clockwise is a client convention, so the addon "
            .. "normally works this out on its own by watching whether "
            .. "following the arrow shortens the distance.|r")

        Navigation.Refresh()
    end,
}

CN:RegisterCommand{
    name    = "nav",
    args    = "[auto, native, tomtom or blizzard]",
    order   = 41,
    help    = "Choose which navigation provider to use.",
    handler = function(args)
        args = CN.Trim(args or "")

        if args ~= "" then
            local ok, resolved = Navigation.SetPreference(args)

            if not ok then
                Print("Not a navigation provider: " .. args)
                Print("|cff999999Choose auto, native, tomtom or blizzard.|r")
                return
            end

            Print("Navigation provider: |cffffff00" .. tostring(resolved) .. "|r")
        end

        local preference = Navigation.Preference()

        Print("Preference: " .. (preference or "automatic"))

        local active, name = CN.GetWaypointProvider()

        Print("Currently using: " .. (active and name or "none available"))

        Print("Available:")

        for _, entry in ipairs(CN.waypointOrder) do
            local candidate = CN.waypointProviders[entry.name]

            local available = candidate and candidate.IsAvailable
                and candidate.IsAvailable()

            Print("  " .. entry.name .. " " .. CN.YesNo(available)
                .. " |cff999999priority " .. entry.priority .. "|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "where am i",
    aliases = { "here" },
    order   = 42,
    help    = "Report your position and what is being tracked.",
    handler = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            Print("Your position is not available right now.")
            return
        end

        Print("You are in " .. tostring(Blizzard.GetMapName(mapID))
            .. (x and y and string.format(" at %.1f, %.1f", x * 100, y * 100) or ""))

        if not target then
            Print("Nothing is being tracked.")
            return
        end

        local state = Navigation.Compute()

        Print("Tracking: |cffffff00" .. tostring(target.title) .. "|r in "
            .. tostring(target.zone))

        if state and state.state == "WRONG_MAP" then
            Print("  |cff999999It is in another zone.|r")
        elseif state then
            Print("  " .. Navigation.FormatDistance(state.yards)
                .. (state.relative and string.format(" |cff999999%d degrees off|r",
                    math.floor(math.abs(math.deg(state.relative)) + 0.5)) or ""))
        end
    end,
}

------------------------------------------------------------
-- LIFECYCLE
------------------------------------------------------------

CN:OnLogin(function()
    if Navigation.IsArrowEnabled() then
        BuildArrow()
    end
end)

-- Zone changes can move you onto the target's map, or off it.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    if target then
        Refresh()
    end
end)

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\MapPins.lua'] = @'
-- Modules/MapPins.lua
-- Completion Navigator :: the plan, drawn on the world map.
--
-- Everything else in this addon answers "what next?" one line at a time. That
-- is the right answer to the question, but it hides the thing that actually
-- makes the routing worth having: the SHAPE of the work. The router already
-- groups objectives into hubs, orders the hubs to minimise walking, and
-- improves that order with a 2-opt pass -- and until now a player saw none of
-- it. They saw a list and an arrow, and had no way to know that stops three
-- through six were all the same camp, or that the route doubles back for a
-- reason.
--
-- So: one numbered pin per HUB, in route order, on the map you are looking at.
-- The number is the order. The tooltip is what you do when you arrive, in the
-- order you would do it. Clicking navigates there.
--
-- One pin per hub, not per objective. Twelve overlapping pins on one camp
-- communicate less than a single pin reading "3 -- pick up 2, do 4, hand in
-- 1", and a map that becomes unreadable when you have a lot to do is a map
-- that fails exactly when it matters most.
--
-- Deliberately NOT a MapCanvasDataProvider. The data-provider API is the
-- blessed route, and it is also a moving target that has broken addons across
-- several expansions. A pooled frame parented to the canvas is boring, has no
-- version surface to speak of, and degrades to "no pins" rather than to a Lua
-- error inside Blizzard's map code.

local ADDON_NAME, CN = ...

local MapPins = CN:RegisterModule("MapPins")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local function Settings()
    return CN.Settings() or {}
end

------------------------------------------------------------
-- ENABLEMENT
------------------------------------------------------------

-- On by default. Pins are additive and read-only -- like tooltip lines, and
-- unlike the waypoint, they take nothing over and interrupt nothing. They
-- also appear only on a map you have deliberately opened.
function MapPins.IsEnabled()
    return Settings().mapPins ~= false
end

function MapPins.SetEnabled(value)
    Settings().mapPins = value and true or false

    if value then
        MapPins.Refresh(true)
    else
        MapPins.Clear()
    end

    return MapPins.IsEnabled()
end

------------------------------------------------------------
-- GEOMETRY
------------------------------------------------------------

-- Normalised map coordinates to a canvas offset.
--
-- The canvas is anchored from its TOPLEFT and y grows DOWNWARD, while map
-- coordinates also grow downward -- so the offset is +x and -y. Getting the
-- sign wrong mirrors every pin vertically, which looks plausible on a
-- symmetrical map and is completely wrong on every other one.
--
-- Pure, and tested as such: this is the one piece of the file that can be
-- wrong in a way no amount of looking at the screen would reveal, because a
-- mirrored pin is still a pin in a believable place.
function MapPins.CanvasOffset(x, y, width, height)
    if not x or not y or not width or not height then
        return nil
    end

    return x * width, -(y * height)
end

MapPins.pinSize      = 26
MapPins.maxPins      = 40
MapPins.crowdedScale = 0.8

-- How big a pin should be. A hub holding six things is worth more of the
-- player's attention than one holding a single stray pet, and size is the
-- cheapest way to say so without adding another colour to read.
function MapPins.PinSize(hubSize, pinCount)
    local size = MapPins.pinSize

    if (hubSize or 1) > 1 then
        size = size + math.min(10, (hubSize - 1) * 2)
    end

    -- A busy zone gets smaller pins rather than fewer of them. Dropping stops
    -- silently would misrepresent the route; shrinking them does not.
    if (pinCount or 0) > 12 then
        size = size * MapPins.crowdedScale
    end

    return math.floor(size + 0.5)
end

------------------------------------------------------------
-- LAYOUT
------------------------------------------------------------

-- Turns ordered hubs into pin descriptors. Pure: no frames, no client, no
-- side effects. Everything that decides what a pin SAYS happens here, so it
-- can be asserted offline.
function MapPins.Layout(hubs)
    local pins = {}

    if type(hubs) ~= "table" then
        return pins
    end

    local total = 0

    for _, hub in ipairs(hubs) do
        if hub.x and hub.y then
            total = total + 1
        end
    end

    for index, hub in ipairs(hubs) do
        if #pins >= MapPins.maxPins then
            break
        end

        -- A hub with no coordinates cannot be drawn. It is not dropped from
        -- the route -- the list still reports it -- it simply has nowhere to
        -- go on a map.
        if hub.x and hub.y then
            local objectives = hub.objectives or {}

            table.insert(pins, {
                order      = index,
                mapID      = hub.mapID,
                x          = hub.x,
                y          = hub.y,
                size       = MapPins.PinSize(#objectives, total),
                hubSize    = #objectives,
                summary    = CN.DescribeHub and CN.DescribeHub(hub) or nil,
                objectives = objectives,
            })
        end
    end

    return pins
end

-- The tooltip body for one pin: what you do when you get there, in the order
-- you would do it. The hub's objectives are already sorted pick up -> do ->
-- hand in by the router, so this only has to not re-sort them.
function MapPins.DescribeLines(pin)
    local lines = {}

    if not pin then
        return lines
    end

    local quests = CN:GetModule("Quests")

    local shown = 0

    for _, objective in ipairs(pin.objectives or {}) do
        if shown >= 8 then
            table.insert(lines, string.format(
                "and %d more", #pin.objectives - shown))
            break
        end

        local verb = "do"

        if objective.phase and quests and quests.PhaseVerb then
            verb = quests.PhaseVerb(objective.phase)
        end

        table.insert(lines, string.format("%s: %s",
            verb, tostring(objective.name or objective.id)))

        shown = shown + 1
    end

    return lines
end

------------------------------------------------------------
-- THE CANVAS
------------------------------------------------------------

-- Resolves the world map's canvas, or nil. Every layer here is optional
-- because every layer is Blizzard's: if any of it moves, pins stop appearing
-- and nothing else in the addon notices.
function MapPins.Canvas()
    local map = _G and _G.WorldMapFrame

    if not map or not map.ScrollContainer then
        return nil
    end

    return map.ScrollContainer.Child
end

-- Which map the player is LOOKING AT, which is not necessarily where they
-- are standing.
function MapPins.DisplayedMapID()
    local map = _G and _G.WorldMapFrame

    if not map or not map.GetMapID then
        return nil
    end

    local ok, mapID = pcall(map.GetMapID, map)

    if ok then
        return mapID
    end

    return nil
end

function MapPins.IsMapShown()
    local map = _G and _G.WorldMapFrame

    if not map or not map.IsShown then
        return false
    end

    local ok, shown = pcall(map.IsShown, map)

    return ok and shown == true
end

------------------------------------------------------------
-- THE ROUTE FOR A DISPLAYED MAP
------------------------------------------------------------

-- Where a route across THIS map should start.
--
-- If you are looking at the zone you are standing in, the route starts at
-- your feet -- that is the whole point of routing. If you are looking at
-- somewhere else, your position is meaningless there: using it would order
-- the stops by their distance from a point on another continent, producing a
-- route that is not merely suboptimal but arbitrary. Start from the middle
-- instead, which orders the stops by their relationship to each other.
function MapPins.RouteStart(displayedMapID)
    local playerMap, x, y = nil, nil, nil

    if CN.GetPlayerPosition then
        local ok, a, b, c = pcall(CN.GetPlayerPosition)

        if ok then
            playerMap, x, y = a, b, c
        end
    end

    if displayedMapID and playerMap == displayedMapID and x and y then
        return x, y, true
    end

    return 0.5, 0.5, false
end

local cache = { mapID = nil, generation = nil, hubs = nil }

function MapPins.InvalidateCache()
    cache.mapID      = nil
    cache.generation = nil
    cache.hubs       = nil
end

local function CandidateGeneration()
    if not CN.GetCandidateCacheState then
        return 0
    end

    local ok, state = pcall(CN.GetCandidateCacheState)

    if ok and state then
        return state.generation or 0
    end

    return 0
end

-- Building a zone route means collecting and scoring every candidate, so it
-- must not happen on every map pan. It happens when the map you are looking
-- at changes, or when the underlying candidates do.
function MapPins.HubsForMap(mapID, force)
    if not mapID or not CN.BuildZoneRoute then
        return nil
    end

    local generation = CandidateGeneration()

    if not force
        and cache.mapID == mapID
        and cache.generation == generation
        and cache.hubs then

        return cache.hubs
    end

    local startX, startY = MapPins.RouteStart(mapID)

    local ok, _, _, hubs = pcall(CN.BuildZoneRoute, mapID, startX, startY)

    if not ok then
        return nil
    end

    cache.mapID      = mapID
    cache.generation = generation
    cache.hubs       = hubs

    return hubs
end

------------------------------------------------------------
-- THE PINS THEMSELVES
------------------------------------------------------------

local pool = {}

local function PinColor(order)
    local nav = CN:GetModule("Navigation")

    local palette = nav and nav.colors

    if not palette then
        return 0.365, 0.824, 0.984
    end

    -- The next stop wears the addon's blue. Everything after it is dimmed,
    -- so "where do I go now" is answerable at a glance rather than by
    -- reading numbers.
    if order == 1 then
        local c = palette.ON_COURSE
        return c[1], c[2], c[3]
    end

    local c = palette.UNKNOWN

    return c[1], c[2], c[3]
end

local function ShowPinTooltip(frame)
    if not GameTooltip or not frame.pin then
        return
    end

    GameTooltip:SetOwner(frame, "ANCHOR_RIGHT")

    GameTooltip:AddLine(string.format("Stop %d", frame.pin.order), 1, 1, 1)

    if frame.pin.summary then
        GameTooltip:AddLine(frame.pin.summary, 0.365, 0.824, 0.984)
    end

    for _, line in ipairs(MapPins.DescribeLines(frame.pin)) do
        GameTooltip:AddLine(line, 0.8, 0.8, 0.8)
    end

    GameTooltip:AddLine("Click to navigate here", 0.6, 0.6, 0.6)

    GameTooltip:Show()
end

local function HidePinTooltip()
    if GameTooltip then
        GameTooltip:Hide()
    end
end

-- Clicking navigates to the STOP, not to whichever objective happens to be
-- listed first there.
--
-- Those are different things. An objective's own coordinates may be missing
-- -- plenty of collectibles are known to be in a zone and nowhere more
-- precise -- while the stop's are the centre of everything at it and always
-- exist, because that is how the stop was formed. Routing to the member and
-- finding it has no location would answer a click with "no coordinates are
-- known", which from the player's side is the addon refusing to go to a place
-- it just drew a pin on.
local function ClickPin(frame)
    local pin = frame.pin

    if not pin then
        return
    end

    for _, objective in ipairs(pin.objectives or {}) do
        if objective.x and objective.y and CN.NavigateToObjective then
            CN.NavigateToObjective(objective)
            return
        end
    end

    if pin.x and pin.y and pin.mapID and CN.SetWaypoint then
        local first = (pin.objectives or {})[1]

        CN.SetWaypoint(pin.mapID, pin.x, pin.y,
            first and tostring(first.name or first.id) or
                ("Stop " .. tostring(pin.order)))
    end
end

local function AcquirePin(index, canvas)
    if pool[index] then
        return pool[index]
    end

    if not CreateFrame or not canvas then
        return nil
    end

    local frame = CreateFrame("Button", "CompletionNavigatorMapPin" .. index, canvas)

    frame:SetSize(MapPins.pinSize, MapPins.pinSize)

    frame.texture = frame:CreateTexture(nil, "OVERLAY")
    frame.texture:SetAllPoints()
    frame.texture:SetTexture(CN.MEDIA_PATH .. "Arrow")

    if not frame.texture:GetTexture() then
        frame.texture:SetTexture("Interface\\Minimap\\MinimapArrow")
    end

    frame.label = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
    frame.label:SetPoint("CENTER")

    frame:SetScript("OnEnter", ShowPinTooltip)
    frame:SetScript("OnLeave", HidePinTooltip)
    frame:SetScript("OnClick", ClickPin)

    pool[index] = frame

    return frame
end

MapPins.AcquirePin = AcquirePin

function MapPins.Clear()
    for _, frame in ipairs(pool) do
        frame:Hide()
    end
end

-- Positions the pins. Separated from Refresh so the arithmetic can be driven
-- offline against a stubbed canvas.
function MapPins.Place(pins, canvas)
    if not canvas then
        return 0
    end

    local width  = canvas:GetWidth()
    local height = canvas:GetHeight()

    if not width or not height or width <= 0 or height <= 0 then
        return 0
    end

    local placed = 0

    for index, pin in ipairs(pins) do
        local frame = AcquirePin(index, canvas)

        if frame then
            local offsetX, offsetY = MapPins.CanvasOffset(pin.x, pin.y, width, height)

            if offsetX then
                frame.pin = pin

                frame:SetSize(pin.size, pin.size)
                frame:ClearAllPoints()
                frame:SetPoint("CENTER", canvas, "TOPLEFT", offsetX, offsetY)

                frame.label:SetText(tostring(pin.order))
                frame.texture:SetVertexColor(PinColor(pin.order))

                frame:Show()

                placed = placed + 1
            end
        end
    end

    -- Surplus frames from a busier map are hidden, never destroyed. Pin
    -- frames are cheap to keep and expensive to churn.
    for index = #pins + 1, #pool do
        pool[index]:Hide()
        pool[index].pin = nil
    end

    return placed
end

function MapPins.Refresh(force)
    if not MapPins.IsEnabled() then
        MapPins.Clear()
        return 0
    end

    if not MapPins.IsMapShown() then
        return 0
    end

    local canvas = MapPins.Canvas()

    if not canvas then
        return 0
    end

    local mapID = MapPins.DisplayedMapID()

    if not mapID then
        MapPins.Clear()
        return 0
    end

    local hubs = MapPins.HubsForMap(mapID, force)

    if not hubs then
        MapPins.Clear()
        return 0
    end

    local pins = MapPins.Layout(hubs)

    local placed = MapPins.Place(pins, canvas)

    DebugPrint(string.format("Map pins: %d stop(s) on map %s.",
        placed, tostring(mapID)))

    return placed
end

------------------------------------------------------------
-- HOOKS
------------------------------------------------------------

local hooked = false

-- Hooked, not overwritten. The world map is shared with every other addon
-- the player runs, and replacing a script on it would break them.
function MapPins.Install()
    if hooked then
        return true
    end

    local map = _G and _G.WorldMapFrame

    if not map or not map.HookScript then
        return false
    end

    map:HookScript("OnShow", function()
        MapPins.Refresh()
    end)

    map:HookScript("OnHide", function()
        MapPins.Clear()
    end)

    -- Panning to a different zone is a map change, not a redraw, so the
    -- route must be rebuilt for the map now on screen.
    if map.RegisterCallback and map.OnMapChanged then
        pcall(map.RegisterCallback, map, "WorldMapOnMapChanged", function()
            MapPins.Refresh()
        end)
    end

    hooked = true

    return true
end

CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    MapPins.Install()
end)

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    MapPins.InvalidateCache()
    MapPins.Refresh()
end)

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    MapPins.InvalidateCache()
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "pins",
    aliases = { "map" },
    args    = "[on, off, or refresh]",
    order   = 18,
    help    = "Show the route as numbered pins on the world map.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            MapPins.SetEnabled(true)
            Print("Map pins are on.")
            return
        end

        if args == "off" then
            MapPins.SetEnabled(false)
            Print("Map pins are off.")
            return
        end

        if args == "refresh" then
            MapPins.InvalidateCache()

            local placed = MapPins.Refresh(true)

            Print(string.format("Redrew %d stop(s).", placed))
            return
        end

        if not MapPins.IsEnabled() then
            Print("Map pins are off. Turn them on with /cn pins on")
            return
        end

        local mapID = MapPins.DisplayedMapID()

        if not mapID then
            Print("Map pins are on. Open the world map to see the route.")
            return
        end

        local hubs = MapPins.HubsForMap(mapID)
        local pins = MapPins.Layout(hubs or {})

        if #pins == 0 then
            Print("Nothing to route on this map.")
            return
        end

        Print(string.format("%d stop(s) on this map:", #pins))

        for _, pin in ipairs(pins) do
            Print(string.format("  %d. %s (%d)",
                pin.order,
                tostring(pin.summary or "do " .. pin.hubSize),
                pin.hubSize))
        end
    end,
}

return MapPins
'@

$Embedded['Modules\Broker.lua'] = @'
-- Modules/Broker.lua
-- Completion Navigator :: LibDataBroker feed, and rare-spawn alerts.
--
-- Two small things that share a theme: telling you something without you
-- having to ask.
--
-- The broker is the addon's answer to "what next?" displayed permanently in
-- whatever bar you already run -- Titan Panel, ElvUI, ChocolateBar. This is
-- the only place the addon touches an external library, and it does so the
-- same way it touches TomTom and AllTheThings: probed, wrapped, optional. If
-- LibDataBroker is not installed nothing happens and nothing is said, because
-- an addon complaining about a library you never asked for is noise.
--
-- Alerts are OFF by default. Unsolicited sound is worse than a waypoint you
-- did not ask for, and this addon has already decided how it feels about that.

local ADDON_NAME, CN = ...

local Broker = CN:RegisterModule("Broker")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- LIBDATABROKER
------------------------------------------------------------

Broker.available = false

local dataObject

local function CurrentText()
    local ok, results = pcall(CN.Recommend, 1)

    if not ok or not results or not results[1] then
        return "Completion Navigator", "nothing actionable"
    end

    local objective = results[1]

    return tostring(objective.name or objective.id), tostring(objective.type)
end

Broker.CurrentText = CurrentText

function Broker.Refresh()
    if not dataObject then
        return
    end

    local name, kind = CurrentText()

    dataObject.text  = name
    dataObject.value = name
    dataObject.label = kind
end

function Broker.Install()
    if Broker.available or not LibStub then
        return Broker.available
    end

    -- LibStub's silent form: it returns nil rather than throwing when the
    -- library is absent, which is exactly what optional means.
    local ok, ldb = pcall(LibStub, "LibDataBroker-1.1", true)

    if not ok or not ldb then
        return false
    end

    local created, object = pcall(ldb.NewDataObject, ldb, "CompletionNavigator", {
        type  = "data source",
        text  = "Completion Navigator",
        icon  = CN.MEDIA_PATH .. "Logo",

        OnClick = function(_, button)
            if button == "RightButton" then
                local results = CN.Recommend(1)

                if results and results[1] then
                    CN.NavigateToObjective(results[1])
                end

                return
            end

            if CN.UI and CN.UI.Toggle then
                CN.UI.Toggle()
            end
        end,

        OnTooltipShow = function(tooltip)
            if not tooltip or not tooltip.AddLine then
                return
            end

            tooltip:AddLine("Completion Navigator")

            local results = CN.Recommend(3)

            if not results or #results == 0 then
                tooltip:AddLine("Nothing actionable yet.", 0.6, 0.6, 0.6)
                tooltip:AddLine("Run /cn setup once.", 0.6, 0.6, 0.6)
                return
            end

            for index, objective in ipairs(results) do
                tooltip:AddLine(
                    (index == 1 and "Next: " or "     ")
                        .. tostring(objective.name or objective.id),
                    index == 1 and 0.365 or 0.7,
                    index == 1 and 0.824 or 0.7,
                    index == 1 and 0.984 or 0.7)
            end

            tooltip:AddLine(" ")
            tooltip:AddLine("Left-click to open, right-click to navigate.", 1, 1, 1)
        end,
    })

    if not created or not object then
        return false
    end

    dataObject      = object
    Broker.available = true

    Broker.Refresh()

    DebugPrint("LibDataBroker feed registered.")

    return true
end

------------------------------------------------------------
-- RARE ALERTS
------------------------------------------------------------

-- Which vignettes have already been announced this session. A rare drifting
-- in and out of vignette range must not announce itself repeatedly.
local announced = {}

function Broker.AlertsEnabled()
    local settings = CN.Settings()

    -- Off by default, deliberately. See the file header.
    return settings and settings.rareAlerts == true
end

function Broker.ResetAnnounced()
    announced = {}
end

-- Returns the vignettes worth announcing: up right now, not already announced,
-- not already cleared by this character, and not something you have ignored.
function Broker.PendingAlerts()
    local rares = CN:GetModule("Rares")

    if not rares then
        return {}
    end

    local pending = {}

    for _, vignette in ipairs(rares.GetActive()) do
        local id = vignette.vignetteID

        if id
            and not announced[id]
            and vignette.kind == "RARE"
            and not rares.IsClearedByCharacter(id)
            and not CN.IsIgnored(CN.objectiveTypes.RARE, id) then

            table.insert(pending, vignette)
        end
    end

    return pending
end

function Broker.Announce(vignette)
    announced[vignette.vignetteID] = time()

    Print("|cff5DD2FBRare up:|r " .. tostring(vignette.name or "unknown")
        .. (vignette.x and vignette.y
            and string.format(" |cff999999%.1f, %.1f|r",
                vignette.x * 100, vignette.y * 100)
            or ""))

    if PlaySound then
        -- A quiet, non-alarming stock sound. Raid warnings are for raids.
        pcall(PlaySound, 8959, "Master")
    end

    return true
end

function Broker.CheckAlerts()
    if not Broker.AlertsEnabled() then
        return 0
    end

    local sent = 0

    for _, vignette in ipairs(Broker.PendingAlerts()) do
        Broker.Announce(vignette)

        sent = sent + 1
    end

    return sent
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

for _, event in ipairs({ "VIGNETTE_MINIMAP_UPDATED", "VIGNETTES_UPDATED" }) do
    CN:RegisterEvent(event, function()
        local ok, err = pcall(Broker.CheckAlerts)

        if not ok then
            DebugPrint("Rare alert check failed: " .. tostring(err))
        end
    end)
end

-- A new zone is a new set of rares; nothing carries over.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    Broker.ResetAnnounced()
end)

CN:OnLogin(function()
    Broker.Install()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "alerts",
    args    = "[on or off]",
    order   = 44,
    help    = "Announce rares that appear near you.",
    handler = function(args)
        local settings = CN.Settings()

        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            settings.rareAlerts = true
        elseif args == "off" then
            settings.rareAlerts = false
        elseif args ~= "" then
            Print("Usage: /cn alerts [on or off]")
            return
        else
            settings.rareAlerts = not Broker.AlertsEnabled()
        end

        Print("Rare alerts: " .. CN.YesNo(Broker.AlertsEnabled()))

        if Broker.AlertsEnabled() then
            Print("|cff999999Announced once each, only for rares you have not "
                .. "already cleared, and reset when you change zone.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "broker",
    order   = 45,
    help    = "Show LibDataBroker status.",
    handler = function()
        if Broker.available then
            local name = CurrentText()

            Print("LibDataBroker feed: " .. CN.YesNo(true))
            Print("Currently showing: |cffffff00" .. tostring(name) .. "|r")
            Print("|cff999999Add it from your display addon: Titan Panel, "
                .. "ElvUI datatexts, ChocolateBar.|r")
            return
        end

        Print("LibDataBroker feed: " .. CN.YesNo(false))
        Print("|cff999999LibDataBroker is not installed, which is fine -- it is "
            .. "optional. Display addons like Titan Panel and ElvUI ship it, "
            .. "and the feed appears automatically when one of them is present.|r")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

